var QUESTOES_ANALISESINTATICA = [{"id":519,"enunciado":"Em relação ao trecho “A corrupção é uma atitude que resulta de um cálculo no qual pesam dois principais fatores: a importância que se dá às normas sociais e o risco de ser pego.”, é correto afirmar que","opcoes":["os dois-pontos marcam a pausa antes da introdução de justificativas.","“uma atitude” é um objeto direto.","“dá” possui um sujeito oculto.","em “correto” há um encontro vocálico.","“às” introduz um complemento de objeto indireto."],"correta":4,"explicacao":"Gabarito: <strong>“às” introduz um complemento de objeto indireto.</strong>.","banca":"AOCP","ano":2016,"temas_relacionados":["analiseSintatica"]},{"id":2085,"enunciado":"Considere o trecho “Pacientes com transtorno dismórfico corporal (TDC) têm preocupação extrema com defeitos físicos pessoais que não são percebidos pelos outros e podem levar a graves prejuízos na realização social e profissional.” Analise as afirmativas a seguir, tendo em vista a organização morfossintática do referido trecho. I- O verbo “têm” encontra-se acentuado para indicar a terceira pessoa do plural do presente do indicativo, concordância que faz com o núcleo do sujeito “pacientes”. II- O termo “que” foi usado como elemento de coesão, uma vez que retoma o termo “defeitos físicos pessoais”, anteriormente expresso. III- O termo “dismórfico” foi formado pelo processo de derivação prefixal e sufixal, já que os afixos -dis e -ico se juntam ao radical -morf. IV- O termo “que” foi usado como elemento de coesão, pois se trata de uma conjunção integrante, a qual liga uma oração principal a uma oração subordinada substantiva. V- O verbo “têm” foi acentuado porque as palavras monossílabas átonas devem ser acentuadas graficamente quando terminadas por -em. Estão CORRETAS as afirmativas","opcoes":["I, II, IV e V, apenas.","I, II e III, apenas.","II, III e IV, apenas.","II, III e V, apenas.","III, IV e V, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II e III, apenas.</strong>.","banca":"COTEC","ano":2024,"temas_relacionados":["analiseSintatica","silabas"]},{"id":2199,"enunciado":"“A lei prevê que o cliente pode questionar o contrato de fidelização caso haja a constatação da má prestação de serviço por parte da empresa concessionária, inclusive com a liberação da fidelização”, crava. Sobre sujeito da oração, assinale a alternativa CORRETA.","opcoes":["Sujeito de “crava” é desinencial.","Sujeito de “prevê” é indeterminado.","Sujeito de “pode questionar” é composto.","Sujeito de “haja” é composto","Sujeito de “crava” é inexistente."],"correta":0,"explicacao":"Gabarito: <strong>Sujeito de “crava” é desinencial.</strong>.","banca":"EDUCA","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":2233,"enunciado":"No trecho: “o Conselho Federal de Enfermagem (Cofen), o Ministério da Saúde e outras instituições lançaram plataformas digitais de combate à desinformação, como o Cofenplay e o Saúde com Ciência, buscando levar conteúdo científico verificado à população”, as vírgulas que isolam a expressão “como o Cofenplay e o Saúde com Ciência” isolam:","opcoes":["Uma oração subordinada adverbial conformativa, que indica a maneira pela qual as instituições combateram a desinformação, equiparando a ação à norma estabelecida previamente no contexto do texto.","Um aposto explicativo, que exemplifica e especifica o referente “plataformas digitais de combate à desinformação” mencionado imediatamente antes na oração principal.","Um adjunto adverbial de modo deslocado, que indica como as plataformas foram lançadas, funcionando como modificador do predicado verbal “lançaram” deslocado para posição medial da oração.","Uma oração subordinada adjetiva explicativa, que acrescenta informação não restritiva ao sujeito composto da oração, formado pelas três instituições citadas no início do período."],"correta":1,"explicacao":"Gabarito: <strong>Um aposto explicativo, que exemplifica e especifica o referente “plataformas digitais de combate à desinformação” mencionado imediatamente antes na oração principal.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":2247,"enunciado":"“Sonhar cansa, como qualquer outra coisa (...)” a vírgula tem a função de","opcoes":["separar o adjunto adverbial deslocado.","deslocar o vocativo.","separar a oração adverbial comparativa e sua oração principal.","separar a oração adverbial causal."],"correta":2,"explicacao":"Gabarito: <strong>separar a oração adverbial comparativa e sua oração principal.</strong>.","banca":"Instituto UniFil","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":2279,"enunciado":"No trecho “O esforço começa a parecer sofrimento. O silêncio, ameaça. A continuidade, tédio.” (6º§), a organização sintática das duas últimas orações e o emprego das vírgulas justificam-se por:","opcoes":["Separar orações coordenadas assindéticas que apresentam uma relação de causa e consequência.","Isolar apostos explicativos que definem os conceitos de “silêncio” e “continuidade” para a mente humana.","Estabelecer uma relação de subordinação adjetiva, em que “ameaça” e “tédio” restringem os sujeitos anteriores.","Marcar a elipse de um termo verbal anteriormente expresso no período, recurso sintático que evita a repetição desnecessária.","Isolar adjuntos adverbiais de modo deslocados, que indicam como os sentimentos se manifestam na mente daqueles que a tecnologia passa a ser um vício."],"correta":3,"explicacao":"Gabarito: <strong>Marcar a elipse de um termo verbal anteriormente expresso no período, recurso sintático que evita a repetição desnecessária.</strong>.","banca":"Instituto Consulplan","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":2408,"enunciado":"Leia o trecho e analise as afirmações que seguem: Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo, é importante que o dentista seja consultado para que seja feita uma avaliação, identificada a causa e iniciado o tratamento, caso seja necessário. I.A primeira vírgula do trecho foi empregada para separar expressões que indiquem explicação intercaladas na oração. II.Em \"Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo\" a primeira oração é subordinada adverbial condicional. III.Em \"...é importante que o dentista seja consultado para que seja feita uma avaliação\" a segunda oração tem a função de um sujeito. Está CORRETO o que se afirma em:","opcoes":["I, II e III.","II e III, apenas.","&#x20;II, apenas.","I e II, apenas."],"correta":1,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":2411,"enunciado":"Leia o trecho e analise as afirmações que seguem: Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo, é importante que o dentista seja consultado para que seja feita uma avaliação, identificada a causa e iniciado o tratamento, caso seja necessário. I.A primeira vírgula do trecho foi empregada para separar expressões que indiquem explicação intercaladas na oração. II.Em \"Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo\" a primeira oração é subordinada adverbial condicional. III.Em \"...é importante que o dentista seja consultado para que seja feita uma avaliação\" a segunda oração tem a função de um sujeito. Está CORRETO o que se afirma em:","opcoes":["II, apenas.","I e II, apenas.","II e III, apenas.","&#x20;I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":2419,"enunciado":"Leia o trecho e analise as afirmações que seguem: Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo, é importante que o dentista seja consultado para que seja feita uma avaliação, identificada a causa e iniciado o tratamento, caso seja necessário. I.A primeira vírgula do trecho foi empregada para separar expressões que indiquem explicação intercaladas na oração. II.Em \"Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo\" a primeira oração é subordinada adverbial condicional. III.Em \"...é importante que o dentista seja consultado para que seja feita uma avaliação\" a segunda oração tem a função de um sujeito. Está CORRETO o que se afirma em:","opcoes":["II, apenas.","I, II e III.","I e II, apenas.","II e III, apenas."],"correta":3,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":2529,"enunciado":"No trecho: “E maçãs vermelhas, enormes cenouras amarelas, redondos tomates de pele quase estalando, chuchus de um verde líquido, abacaxis malignos na sua selvageria, laranjas alaranjadas e calmas, maxixes eriçados como porcos-espinhos, pepinos que se fechavam duros sobre a própria carne aquosa...”, o uso das vírgulas dá-se pela seguinte regra:","opcoes":["Separar apostos.","Separar orações coordenadas.","Separar termos coordenados.","Separar orações subordinadas adjetivas explicativas. Resposta correta"],"correta":3,"explicacao":"Gabarito: <strong>Separar orações subordinadas adjetivas explicativas. Resposta correta</strong>.","banca":"Instituto Unique","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":3005,"enunciado":"Analise o texto e assinale a alternativa CORRETA: \"Perdi-me dentro de mim, porque eu era labirinto e minhas saudades não tinham fim.\"","opcoes":["O pronome \"me\", em \"Perdi-me dentro de mim\", exerce a função de sujeito da oração.","A expressão \"dentro de mim\" exerce a função de complemento nominal do substantivo \"labirinto\".","A palavra \"porque\" introduz uma oração subordinada adverbial causal.","A forma verbal \"era\" está conjugada no pretérito perfeito do indicativo.","O termo \"saudades\" é um adjetivo que caracteriza o pronome \"mim\"."],"correta":2,"explicacao":"Gabarito: <strong>A palavra \"porque\" introduz uma oração subordinada adverbial causal.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":3317,"enunciado":"Nas duas ocorrências sublinhadas a seguir, o pronome oblíquo exerce função sintática de: “Diz-me com quem andas e eu te direi quem és.” (ditado popular)","opcoes":["Objeto direto.","Objeto indireto.","Objeto direto preposicionado.","Objeto indireto pleonástico."],"correta":1,"explicacao":"Gabarito: <strong>Objeto indireto.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":3637,"enunciado":"Dos termos da oração: \"Onde os pulmões se consomem, ( ... )\", é inadequado afirmar:","opcoes":["\"onde\" se relaciona com antecedente \"ares\".","o pronome \"se\" está enclítico.","\"onde\", sintaticamente, é adjunto adverbial de lugar.","o sujeito, \"os pulmões\", é simples.","\"os\" é artigo e adjunto adnominal morfossintaticamenle."],"correta":1,"explicacao":"Gabarito: <strong>o pronome \"se\" está enclítico.</strong>.","banca":"CETAP","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":3800,"enunciado":"Considere o período a seguir, retirado do texto: ▀ “E se ela está sempre nesse centro, ela não se move em relação às estrelas”. Assinale a alternativa correta em relação ao período.","opcoes":["O pronome oblíquo átono está em próclise obrigatória.","O período é composto por duas orações subordinadas adversativas.","Nas duas vezes em que aparece, a partícula “se” exerce a mesma função sintática, dentro das orações a que pertence.","Na expressão “às estrelas” a crase em “as” foi usada de modo optativo.","Na expressão “olhando às estrelas no céu”, comparada à expressão “em relação às estrelas”, também apresenta uso facultativo da crase em “as”."],"correta":0,"explicacao":"Gabarito: <strong>O pronome oblíquo átono está em próclise obrigatória.</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4014,"enunciado":"\"Poucos países possuem um programa de biocombustíveis tão avançado quanto o brasileiro, o que aumenta a resiliência diante de choques externos.Considerando a análise sintática dos elementos linguísticos empregados no trecho, julgue as afirmativas a seguir:I. O sintagma 'Poucos países' exerce a função de sujeito simples, assim como \"duas horas\" na oração 'No relógio deram duas horas', construção gramaticalmente correta.II. O substantivo 'programa' exerce a função de núcleo do objeto direto do verbo 'possuir' e de núcleo do sujeito do verbo 'avançar'.III. A expressão 'a resiliência diante de choques externos' exerce a função sintática de sujeito posposto do verbo 'aumentar'.IV. O vocábulo 'países' exerce a mesma função sintática do pronome oblíquo 'a', considerando o verbo 'entrar', na frase 'Eu a vi entrar no quarto'.Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["II e III, apenas.","I e II, apenas.","III e IV, apenas.","II, III e IV, apenas.","I, II e IV, apenas."],"correta":4,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4134,"enunciado":"Assinale a alternativa que classifica CORRETAMENTE a função sintática da oração destacada no trecho “Mas a verdade é que você faz um papel subalterno”.","opcoes":["Objeto direto.","Predicativo do sujeito.","Sujeito.","Objeto indireto."],"correta":1,"explicacao":"Gabarito: <strong>Predicativo do sujeito.</strong>.","banca":"INBRASP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4135,"enunciado":"Considerando o período “Você ignora que quem os cose sou eu”, assinale a alternativa CORRETA.","opcoes":["“Que” é pronome relativo e retoma o antecedente “você”, introduzindo uma oração subordinada adjetiva; “quem” é pronome interrogativo e introduz uma pergunta indireta sobre a identidade de quem cose.","“Que” é conjunção subordinativa integrante e introduz uma oração subordinada substantiva objetiva direta; “quem” é pronome relativo sem antecedente expresso e exerce a função de sujeito na oração que introduz.","“Que” é conjunção subordinativa integrante e introduz uma oração subordinada substantiva objetiva direta; “quem” é pronome interrogativo indireto e funciona como objeto direto do verbo “cose”.","“Que” é pronome relativo e retoma o antecedente “você”; “quem” é pronome indefinido e funciona como adjunto adverbial da oração em que aparece."],"correta":1,"explicacao":"Gabarito: <strong>“Que” é conjunção subordinativa integrante e introduz uma oração subordinada substantiva objetiva direta; “quem” é pronome relativo sem antecedente expresso e exerce a função de sujeito na oração que introduz.</strong>.","banca":"INBRASP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4136,"enunciado":"No primeiro período do último parágrafo do texto CG1A1, a oração “que tanto instituições educacionais quanto empregadores nos campos de STEM implementem políticas proativas de inclusão” exerce sintaticamente a função de","opcoes":["complemento nominal.","sujeito.","objeto direto.","objeto indireto."],"correta":1,"explicacao":"Gabarito: <strong>sujeito.</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4137,"enunciado":"Considerando os trechos a seguir, retirados do texto, assinale a alternativa na qual a palavra “que” esteja sendo empregada como conjunção integrante que introduz uma oração cuja função é de objeto direto.","opcoes":["“é frequente que a relação entre IA e educação seja organizada em dois eixos analíticos”.","“com aplicações que incluem apoio à aprendizagem”.","“são importantes porque evidenciam que a IA não se reduz a ferramentas digitais”","“dispositivos já disponíveis nas escolas e interfaces que demandem níveis reduzidos”."],"correta":2,"explicacao":"Gabarito: <strong>“são importantes porque evidenciam que a IA não se reduz a ferramentas digitais”</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4138,"enunciado":"Assinale a alternativa em que a oração é subordinada substantiva objetiva direta:","opcoes":["Desejo que todos participem da reunião.","O problema é que ninguém compareceu.","Tenho certeza de que ele voltará.","A verdade é que o prazo terminou.","Era necessário que os alunos estudassem."],"correta":0,"explicacao":"Gabarito: <strong>Desejo que todos participem da reunião.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4139,"enunciado":"\"Propomos a ideia de que a comida humana, por não ser adaptada à sua dieta natural, desencadeia problemas estomacais e, potencialmente, perturbações no microbioma...\" A oração iniciada por 'de que a comida...' é classificada como:","opcoes":["Oração subordinada substantiva objetiva direta, pois completa o sentido do verbo 'propor', sem uso de preposição.","Oração subordinada adjetiva explicativa, pois caracteriza o termo 'ideia', acrescentando uma informação adicional.","Oração subordinada substantiva objetiva indireta, pois completa o sentido do verbo 'propor', com preposição.","Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo."],"correta":3,"explicacao":"Gabarito: <strong>Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4141,"enunciado":"adaptada à sua dieta natural, desencadeia problemas estomacais e, potencialmente, perturbações no microbioma...\" A oração iniciada por 'de que a comida...' é classificada como:","opcoes":["Oração subordinada substantiva objetiva indireta, pois completa o sentido do verbo 'propor', com preposição.","Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.","Oração subordinada substantiva objetiva direta, pois completa o sentido do verbo 'propor', sem uso de preposição.","Oração subordinada adjetiva explicativa, pois caracteriza o termo 'ideia', acrescentando uma informação adicional."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4142,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item seguinte. No período “Mais do que delegar o tema ao setor de compliance, portanto, é essencial que os C‑levels assumam liderança ativa, direta e estratégica na integração do ESG à governança corporativa.”, o segmento “que os C‑levels assumam liderança ativa, direta e estratégica na integração do ESG à governança corporativa” exerce a função sintática de sujeito da forma verbal “é”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4144,"enunciado":"No trecho “Ter um site atualizado, estar presente nas redes sociais, produzir conteúdo relevante e adotar canais de atendimento digitais são medidas essenciais”, as formas verbais “ter”, “estar”, “produzir” e “adotar” desempenham uma função específica na organização das ideias. Com base nessa informação, assinale a opção que apresenta corretamente essa estruturação sintático‑semântica.","opcoes":["Atuam como conectores de oposição às inovações tecnológicas citadas anteriormente.","Funcionam como núcleos de orações substantivas subjetivas que enumeram ações necessárias.","Representam marcas de linguagem coloquial voltadas à aproximação com o público jovem.","Constituem uma estrutura de subordinação adjetiva que restringe o conceito de “medidas”.","Indicam uma relação de causa e consequência direta entre o site e a venda final."],"correta":1,"explicacao":"Gabarito: <strong>Funcionam como núcleos de orações substantivas subjetivas que enumeram ações necessárias.</strong>.","banca":"Quadrix","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4145,"enunciado":"Considere o período abaixo:“Os concorrentes demonstram que exames qualificatórios têm desdobramentos inevitáveis na qualidade de vida a curto prazo.”Conforme a análise sintática do período composto, assinale a alternativa correta.","opcoes":["O período é composto por coordenação, sendo a oração introduzida por “que” classificada como coordenada sindética explicativa.","A oração “que exames qualificatórios têm desdobramentos inevitáveis na qualidade de vida a curto prazo” é subordinada substantiva completiva nominal, exercendo função de complemento do termo “demonstram”.","O período é composto por subordinação, e a oração introduzida por “que” exerce função de objeto direto do termo “demonstram”.","A oração principal é estruturalmente incompleta, exigindo complemento preposicionado para a correção sintática do período."],"correta":2,"explicacao":"Gabarito: <strong>O período é composto por subordinação, e a oração introduzida por “que” exerce função de objeto direto do termo “demonstram”.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4146,"enunciado":"No trecho “Já existem estudos mostrando que a exposição excessiva a telas e diferentes conteúdos on-line está relacionada com a depressão...”, a oração introduzida por “que” exerce função de:","opcoes":["oração subordinada adverbial causal.","oração subordinada adjetiva explicativa.","oração subordinada substantiva objetiva direta.","oração coordenada sindética explicativa.","oração subordinada substantiva subjetiva."],"correta":2,"explicacao":"Gabarito: <strong>oração subordinada substantiva objetiva direta.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4147,"enunciado":"\"Há muita evidência de que avançamos. Mas, quando consideramos os níveis de desigualdade, entendemos que ainda precisamos fazer muito, muito, muito mais.\"Com base na análise sintática, identifique a alternativa incorreta.","opcoes":["A expressão 'muita evidência de que avançamos' exerce a mesma função sintática do pronome oblíquo átono 'vos' na construção 'Beijo-vos a testa', uma vez que, em ambos os casos, os termos em questão funcionam como objetos diretos.","A substituição de 'Há' por existe mantém a correção gramatical, todavia, a expressão 'muita evidência de que avançamos' tem sua função sintática alterada, demonstrando que a equivalência entre os dois verbos é semântica, e não sintática.","A oração 'quando consideramos os níveis de desigualdade\" é uma oração subordinada adverbial temporal, exercendo a função de adjunto adverbial de tempo em relação à oração principal.","A oração 'que ainda precisamos fazer muito mais' é objeto direto do verbo 'entender', tratando-se, portanto, de uma oração subordinada substantiva objetiva direta, ao passo que \"de que avançamos\" é complemento nominal do substantivo 'evidência'."],"correta":0,"explicacao":"Gabarito: <strong>A expressão 'muita evidência de que avançamos' exerce a mesma função sintática do pronome oblíquo átono 'vos' na construção 'Beijo-vos a testa', uma vez que, em ambos os casos, os termos em questão funcionam como objetos diretos.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4149,"enunciado":"Leia o trecho a seguir:“Todo vexame advém da falta de timing.”Com base nos conceitos gramaticais de frase, oração e período, analise as afirmativas a seguir e julgue-as como verdadeiras (V) ou falsas (F).( ) O enunciado constitui uma frase verbal, pois apresenta verbo e sentido completo.( ) O trecho apresenta apenas uma oração, caracterizando um período simples.( ) O verbo “advém” funciona como núcleo da oração presente no período.( ) O segmento “da falta de timing” constitui uma oração subordinada substantiva completiva nominal.Após análise, conclui-se que a sequência correta é:","opcoes":["V – F – V – V.","F – V – F – V.","V – V – F – F.","V – V – V – F.","F – F – V – V."],"correta":3,"explicacao":"Gabarito: <strong>V – V – V – F.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4150,"enunciado":"Alguém insiste que um objeto simplesmente não está ali, que é impossível de encontrá-lo, apesar de dizer que fez uma busca minuciosa e eficaz.Com base na classificação da oração 'que é impossível de encontrá-lo', assinale a alternativa correta.","opcoes":["A oração é classificada como oração subordinada substantiva predicativa, pois o adjetivo 'impossível' funciona como núcleo do predicativo do sujeito, exigindo uma oração que complete seu sentido.","A oração é classificada como oração subordinada adjetiva restritiva, pois o pronome 'que' retoma toda a oração 'Alguém insiste que um objeto simplesmente não está ali'.","A oração é classificada como oração subordinada substantiva completiva nominal, pois completa o sentido do adjetivo 'impossível, exercendo função de complemento nominal.","A oração é classificada como oração subordinada substantiva objetiva direta, pois completa o sentido do verbo 'insistir', exercendo função de objeto direto sem preposição."],"correta":3,"explicacao":"Gabarito: <strong>A oração é classificada como oração subordinada substantiva objetiva direta, pois completa o sentido do verbo 'insistir', exercendo função de objeto direto sem preposição.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4151,"enunciado":"Assinale a alternativa que apresente a função sintática exercida pela oração em destaque no período: Ainda assim, Lima afirma que o café solúvel brasileiro tem condições para manter a liderança no mercado europeu.","opcoes":["Objeto Direto.","Sujeito.","Aposto.","Objeto Indireto.","Predicativo do Sujeito."],"correta":0,"explicacao":"Gabarito: <strong>Objeto Direto.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4152,"enunciado":"\"A vida é uma coisa que tem de passar, uma obrigação de que é preciso dar conta.\"Analise a classificação da oração 'de que é preciso dar conta' e identifique a alternativa correta.","opcoes":["Oração subordinada substantiva completiva nominal","Oração subordinada substantiva objetiva indireta","Oração coordenada sindética explicativa.","Oração subordinada adjetiva restritiva"],"correta":3,"explicacao":"Gabarito: <strong>Oração subordinada adjetiva restritiva</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4153,"enunciado":"Considerando a classificação das orações subordinadas substantivas na língua portuguesa, analise a estrutura sintática da oração a seguir, observando a relação estabelecida entre a oração principal e a subordinada:\"O diretor afirmou que os resultados seriam divulgados ainda nesta semana.\"Assinale a alternativa que classifica corretamente a oração subordinada destacada:","opcoes":["Oração subordinada substantiva subjetiva.","Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva objetiva indireta."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4154,"enunciado":"“Não importa quantos passos você deu para trás, o importante é quantos passos agora você vai dar pra frente.” (Provérbio chinês). Sobre a estruturação sintática desse pensamento, analisar os itens. ( ) Na primeira oração principal, temos sujeito desinencial.( ) Temos duas orações subordinadas substantivas com a mesma classificação.( ) Na segunda oração principal, não temos sujeito simples e claro.( ) Temos uma oração subordinada substantiva subjetiva, seguida de uma substantiva predicativa.","opcoes":["C - E - E - C.","C - C - E - E.","E - C - C - E.","E - E - E - C."],"correta":3,"explicacao":"Gabarito: <strong>E - E - E - C.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4155,"enunciado":"Analise e assinale a alternativa que apresenta a classificação correta da oração abaixo:“Eu acho que não precisamos brigar por isso.”","opcoes":["Oração Subordinada Substantiva Objetiva Direta.","Oração Subordinada Substantiva Predicativa.","Oração Subordinada Substantiva Completiva Nominal.","Oração Subordinada Substantiva Objetiva Indireta."],"correta":0,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Objetiva Direta.</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4156,"enunciado":"Analise e assinale a alternativa que apresenta a classificação correta da oração abaixo: “Eu acho que não precisamos brigar por isso.","opcoes":["Oração Subordinada Substantiva Objetiva Direta.","Oração Subordinada Substantiva Predicativa.","Oração Subordinada Substantiva Completiva Nominal.","Oração Subordinada Substantiva Objetiva Indireta."],"correta":0,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Objetiva Direta.</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4157,"enunciado":"\"Propomos a ideia de que a comida humana, por não ser adaptada à sua dieta natural, desencadeia problemas estomacais e, potencialmente, perturbações no microbioma, cujos efeitos negativos são atenuados pelos componentes do solo\", disse Sylvain Lemoine, antropólogo biológico da Universidade de Cambridge, na Inglaterra, e principal autor do estudo publicado na quarta-feira na revista Scientific Reports.Com base nas regras de acentuação dos vocábulos presentes no trecho, analise as afirmativas e assinale a incorreta.","opcoes":["Oração subordinada substantiva objetiva direta, pois completa o sentido do verbo 'propor', sem uso de preposição.","Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.","Oração subordinada substantiva objetiva indireta, pois completa o sentido do verbo 'propor', com preposição.","Oração subordinada adjetiva explicativa, pois caracteriza o termo 'ideia', acrescentando uma informação adicional."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4158,"enunciado":"\"Propomos a ideia de que a comida humana, por não ser adaptada à sua dieta natural, desencadeia problemas estomacais e, potencialmente, perturbações no microbioma...\"A oração iniciada por 'de que a comida...' é classificada como:","opcoes":["Oração subordinada adjetiva explicativa, pois caracteriza o termo 'ideia', acrescentando uma informação adicional.","Oração subordinada substantiva objetiva indireta, pois completa o sentido do verbo 'propor', com preposição.","Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.","Oração subordinada substantiva objetiva direta, pois completa o sentido do verbo 'propor', sem uso de preposição."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva completiva nominal, pois completa o sentido de um substantivo.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4159,"enunciado":"Observe o segmento: \"Ele se ouviu dizer, com toda intensidade necessária, aquilo que queria ter dito (...).\" A oração introduzida pelo pronome \"que\" em \"aquilo que queria ter dito\" classifica-se como:","opcoes":["Oração subordinada adjetiva restritiva.","Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva objetiva direta.","Oração subordinada adverbial conformativa."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada adjetiva restritiva.</strong>.","banca":"FUNATEC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4160,"enunciado":"“Para entender onde ela \"mora\", seria importante então entender o efeito dos anestésicos.” A oração subordinada destacada deste período exerce a função sintática de","opcoes":["Predicativo.","Sujeito.","Objeto direto.","Aposto.","Adjunto adverbial"],"correta":1,"explicacao":"Gabarito: <strong>Sujeito.</strong>.","banca":"Instituto Legatus","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4161,"enunciado":"Considerando o trecho, extraído do texto 1 “Em vez de negociar com cada credor isoladamente, o devedor pode acionar um procedimento que reúne todos os credores de dívidas de consumo em uma única audiência de conciliação, com apresentação de plano de pagamento unificado [...]” (linhas 25-28), analise as assertivas e identifique com V as verdadeiras e com F as falsas.( ) O termo “que” é uma conjunção integrante que introduz uma oração subordinada substantiva objetiva direta.( ) A expressão “de consumo” atua como um adjunto adnominal, caracterizando o tipo de dívida mencionada.( ) No trecho “reúne todos os credores”, o termo “todos” é um pronome substantivo que exerce função de núcleo do objeto direto.( ) O vocábulo “isoladamente” é um advérbio de modo porque indica a maneira como a ação de negociar é praticada no contexto.( ) A expressão “em vez de” pode ser substituída por “ao invés de” sem alteração de sentido, pois ambas são equivalentes em qualquer contexto.A alternativa que contém a sequência correta, de cima para baixo, é","opcoes":["F V F F V","F V F V F","F F F V F","V V F V V","V V F F F"],"correta":1,"explicacao":"Gabarito: <strong>F V F V F</strong>.","banca":"CEFET-BA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4162,"enunciado":"Analise as orações destacadas nos períodos a seguir, extraídos do texto 1.Período I: “A lei 14.181/21, que alterou o CDC, reconheceu que esse fenômeno não é um problema moral do devedor [...]” (linhas 4-5).Período II: \"O problema é que essa mesma automaticidade cria um incentivo perverso [...] (linhas 18-19).A oração destacada no período I é classificada como __________________________ e a oração destacada no período II é uma oração ____________________________________.A alternativa que preenche, correta e sequencialmente, as lacunas do trecho acima é","opcoes":["subordinada substantiva objetiva direta / subordinada substantiva predicativa.","subordinada adverbial causal / subordinada substantiva completiva nominal.","subordinada substantiva subjetiva / subordinada adverbial consecutiva.","coordenada sindética aditiva / subordinada adjetiva explicativa.","subordinada adjetiva restritiva / coordenada explicativa."],"correta":0,"explicacao":"Gabarito: <strong>subordinada substantiva objetiva direta / subordinada substantiva predicativa.</strong>.","banca":"CEFET-BA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4164,"enunciado":"\"Nós vimos que, de fato, são espécies bastante distintas, que foram todas agrupadas dentro desse nome, Purpureocillium atypicola, observa o cientista.\" A oração \"que, de fato, são espécies bastante distintas\" é classifica como:","opcoes":["Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva predicativa.","Oração subordinada substantiva objetiva indireta.","Oração subordinada substantiva objetiva direta."],"correta":3,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4165,"enunciado":"Considerando o trecho \"Uma pesquisa do Datafolha de outubro de 2024 apontou que 62% da população é a favor da proibição do celular nas escolas.\", assinale a alternativa que apresenta a análise sintática correta da oração \"que 62% da população é a favor da proibição do celular nas escolas\".","opcoes":["A estrutura introduzida por \"que\" estabelece relação circunstancial de causa em relação ao verbo principal, sendo classificada como subordinada adverbial causal.","A oração introduzida por \"que\" exerce a função de complemento do verbo \"apontou\", sendo classificada como subordinada substantiva objetiva direta.","A oração subordinada funciona como adjunto adnominal do substantivo \"pesquisa\", caracterizando-se como subordinada adjetiva explicativa.","A oração subordinada exerce função predicativa do sujeito, complementando o sentido do verbo de ligação implícito na construção."],"correta":1,"explicacao":"Gabarito: <strong>A oração introduzida por \"que\" exerce a função de complemento do verbo \"apontou\", sendo classificada como subordinada substantiva objetiva direta.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4167,"enunciado":"\"Nós vimos que, de fato, são espécies bastante distintas, que foram todas agrupadas dentro desse nome, Purpureocillium atypicola, observa o cientista.\"A oração \"que, de fato, são espécies bastante distintas\" é classificada como:","opcoes":["Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva predicativa.","Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva objetiva indireta."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4168,"enunciado":"Considerando o trecho \"Uma pesquisa do Datafolha de outubro de 2024 apontou que 62% da população é a favor da proibição do celular nas escolas .\", assinale a alternativa que apresenta a análise sintática correta da oração \"que 62% da população é a favor da proibição do celular nas escolas\".","opcoes":["A oração introduzida por \"que\" exerce a função de complemento do verbo \"apontou\", sendo classificada como subordinada substantiva objetiva direta.","A oração subordinada exerce função predicativa do sujeito, complementando o sentido do verbo de ligação implícito na construção.","A oração subordinada funciona como adjunto adnominal do substantivo \"pesquisa\", caracterizando-se como subordinada adjetiva explicativa.","A estrutura introduzida por \"que\" estabelece relação circunstancial de causa em relação ao verbo principal, sendo classificada como subordinada adverbial causal."],"correta":0,"explicacao":"Gabarito: <strong>A oração introduzida por \"que\" exerce a função de complemento do verbo \"apontou\", sendo classificada como subordinada substantiva objetiva direta.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4174,"enunciado":"\"Nós vimos que, de fato, são espécies bastante distintas, que foram todas agrupadas dentro desse nome, Purpureocillium atypicola, observa o cientista.\" A oração \"que, de fato, são espécies bastante distintas\" é classificada como:","opcoes":["Oração subordinada substantiva predicativa.","Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva objetiva indireta.","Oração subordinada substantiva objetiva direta."],"correta":3,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4175,"enunciado":"Em “John Ford, por exemplo, tinha tempo para contar uma boa história e sabia que também o tínhamos para apreciá-la.” (7º§), é possível observar o emprego de:","opcoes":["Orações explicativas e subordinadas aditivas.","Oração explicativa separada por vírgulas do restante do período.","Período simples formado por orações subordinadas que se complementam.","Oração que, reconhecidamente, possui a mesma função exercida sintaticamente pelo objeto direto."],"correta":3,"explicacao":"Gabarito: <strong>Oração que, reconhecidamente, possui a mesma função exercida sintaticamente pelo objeto direto.</strong>.","banca":"Instituto Consulplan","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4177,"enunciado":"Especialistas destacam que a prática médica enfrenta o desafio de lidar com amplo volume de conhecimento, especialmente em sistemas de saúde sobrecarregados.Assinale a alternativa CORRETA quanto à sintaxe do período apresentado.","opcoes":["A expressão \"especialmente em sistemas de saúde sobrecarregados\" integra o núcleo do predicado, compondo elemento essencial da estrutura do período.","A oração iniciada por 'que' classifica-se como subordinada substantiva objetiva direta, exercendo a função de objeto direto do verbo 'destacam'.\"","A oração iniciada por \"que\" possui relação de coordenação com o verbo \"destacam\", compondo estrutura de igual nível sintático no período.","O segmento \"de lidar com amplo volume de conhecimento\" estabelece relação com o verbo \"enfrenta\", compondo diretamente a estrutura verbal do período.","O trecho \"de lidar com amplo volume de conhecimento\" relaciona-se ao sujeito \"a prática médica\", compondo estrutura que define sua atuação no período."],"correta":1,"explicacao":"Gabarito: <strong>A oração iniciada por 'que' classifica-se como subordinada substantiva objetiva direta, exercendo a função de objeto direto do verbo 'destacam'.\"</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4179,"enunciado":"Observe o período abaixo:“Convém que os candidatos leiam atentamente o edital antes de se inscreverem no certame.”Assinale a alternativa que apresenta a análise sintática correta.","opcoes":["“Convém” é verbo de ligação.","O sujeito de “convém” é “os candidatos”.","A oração introduzida por “que” exerce função de objeto direto.","“Antes de se inscreverem no certame” é oração concessiva.","A oração “que os candidatos leiam atentamente o edital” exerce função de sujeito de “convém”."],"correta":4,"explicacao":"Gabarito: <strong>A oração “que os candidatos leiam atentamente o edital” exerce função de sujeito de “convém”.</strong>.","banca":"IBADE","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4180,"enunciado":"Assinale a alternativa que analisa corretamente o excerto “Como destacam os autores, é improvável que toda a população alcance as diretrizes da OMS (150 minutos de atividade física por semana).”","opcoes":["O termo “como” exerce o mesmo papel na estrutura sintática do período que em “[...] como tarefas domésticas ou caminhada lenta [...]” (oitavo parágrafo).","A expressão “é improvável que” modaliza afetivamente o conteúdo posterior, imprimindo sobre ele uma avaliação negativa por parte de Bruno Gualano.","A informação apresentada entre parênteses especifica as diretrizes da OMS, sendo indispensável à estrutura sintática do período.","A vírgula separa duas orações coordenadas, isto é, sintaticamente independentes, o que possibilita que a primeira oração possa ser movida para a posição final no período.","O artigo “a”, que precede o substantivo “população”, pode ser omitido sem que isso prejudique a estrutura sintática do período."],"correta":4,"explicacao":"Gabarito: <strong>O artigo “a”, que precede o substantivo “população”, pode ser omitido sem que isso prejudique a estrutura sintática do período.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4181,"enunciado":"Além disso, a escrita encontrada em selos ainda não foi compreendida, o \"que\" dificulta o acesso a informações sobre a cultura, as crenças e a organização dessa sociedade.Assinale a alternativa correta quanto à classe de palavra do vocábulo \"que\" no trecho apresentado.","opcoes":["Conjunção integrante, pois introduz oração subordinada substantiva que completa o sentido do verbo anterior.","Conjunção coordenativa explicativa, pois estabelece relação de explicação entre duas orações independentes.","Pronome demonstrativo, pois substitui diretamente o termo \"escrita\" e exerce função de núcleo do sujeito da oração seguinte.","Pronome relativo, pois retoma a ideia de que a escrita ainda não foi compreendida e introduz oração que a explica."],"correta":3,"explicacao":"Gabarito: <strong>Pronome relativo, pois retoma a ideia de que a escrita ainda não foi compreendida e introduz oração que a explica.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4184,"enunciado":"\"Professora de Biologia no Centro de Ensino em Período Integral (Cepi) Osvaldo da Costa Meireles, em Luziânia, Gabrielle Rosa Silva, de 29 anos, explicou ao g1 que a ideia surgiu durante pesquisas, na escola, sobre o desenvolvimento de algum produto através de material que fosse descartado de maneira comum.\"Analise a classificação da oração iniciada pelo 'que' em \"que a ideia surgiu durante pesquisas, na escola...\" e identifique a alternativa CORRETA.","opcoes":["Oração subordinada adverbial causal, pois a conjunção integrante 'que' indica a causa da explicação, estabelecendo uma relação de motivo entre a oração principal e a subordinada.","Oração subordinada substantiva objetiva direta, pois o pronome 'que' inicia uma oração que completa o sentido do verbo 'explicar', funcionando como objeto direto da oração principal.","Substantiva subjetiva, pois a conjunção integrante 'que' introduz a oração que funciona como sujeito da oração principal, desempenhando papel essencial no sentido da frase.","Oração subordinada adjetiva restritiva, pois o pronome 'que' antecede o substantivo 'ideia', dando característica específica e determinando de forma restritiva o sentido do substantivo.","Oração subordinada substantiva objetiva indireta, pois o pronome 'que' vem precedido da preposição 'a', estabelecendo ligação com o verbo 'explicar' e completando seu sentido."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta, pois o pronome 'que' inicia uma oração que completa o sentido do verbo 'explicar', funcionando como objeto direto da oração principal.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4185,"enunciado":"Muitos brasileiros retornam ao país de origem ou buscam alternativas em outras regiões da Europa, evidenciando \"que o principal desafio não é migrar\".A oração destacada classifica-se como:","opcoes":["Oração subordinada substantiva subjetiva.","Oração subordinada substantiva objetiva direta.","Oração subordinada adjetiva explicativa.","Oração subordinada substantiva completiva nominal."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4187,"enunciado":"\"Professora de Biologia no Centro de Ensino em Período Integral (Cepi) Osvaldo da Costa Meireles, em Luziânia, Gabrielle Rosa Silva, de 29 anos, explicou ao g1 que a ideia surgiu durante pesquisas, na escola, sobre o desenvolvimento de algum produto através de material que fosse descartado de maneira comum.\" Analise a classificação da oração iniciada pelo 'que' em \"que a ideia surgiu durante pesquisas, na escola...\" e identifique a alternativa CORRETA.","opcoes":["Oração subordinada substantiva objetiva indireta, pois o pronome 'que' vem precedido da preposição 'a', estabelecendo ligação com o verbo 'explicar' e completando seu sentido.","Substantiva subjetiva, pois a conjunção integrante 'que' introduz a oração que funciona como sujeito da oração principal, desempenhando papel essencial no sentido da frase.","Oração subordinada adjetiva restritiva, pois o pronome 'que' antecede o substantivo 'ideia', dando característica específica e determinando de forma restritiva o sentido do substantivo.","Oração subordinada adverbial causal, pois a conjunção integrante 'que' indica a causa da explicação, estabelecendo uma relação de motivo entre a oração principal e a subordinada.","Oração subordinada substantiva objetiva direta, pois o pronome 'que' inicia uma oração que completa o sentido do verbo 'explicar', funcionando como objeto direto da oração principal."],"correta":4,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta, pois o pronome 'que' inicia uma oração que completa o sentido do verbo 'explicar', funcionando como objeto direto da oração principal.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4188,"enunciado":"Considere o trecho a seguir.\"A criação do CNPq, em 1951, foi um dos movimentos mais visionários da história do Brasil. Em um contexto em que o sistema científico nacional ainda era incipiente, a decisão de instituir uma agência dedicada à ciência e à tecnologia revelou a compreensão de que o conhecimento seria essencial ao desenvolvimento\".De acordo com o trecho, avalie as assertivas que se seguem no que diz respeito à gramática normativa vigente.I.Em relação à norma-padrão, há um desvio ortográfico no emprego da palavra \"incipiente\", uma vez que, no contexto utilizado, o termo deveria ter sido substituído por \"insipiente\", já que apresenta valor semântico de \"inicial\", embora isso em nada prejudique a consolidação comunicativa.II.No segmento \"Em um contexto em que\", o termo \"em que\" é constituído por conjunção integrante acompanhada de preposição e pode ser substituído, sem prejuízo sintático-semântico, pelo termo \"onde\", segundo a norma-padrão.III.A forma verbal \"revelou\" encontra-se no pretérito perfeito do modo indicativo, uma vez que aponta uma ação concluída no passado, tomada como fato certo no eixo da enunciação, e apresenta como núcleo do sujeito o termo \"decisão\".IV.A última oração do trecho classifica-se como oração subordinada substantiva completiva nominal.Acerca das assertivas acima, assinale a alternativa CORRETA.","opcoes":["Apenas uma está correta.","Apenas duas estão corretas.","Apenas três estão corretas.","Todas as quatro estão corretas.","Todas as quatro estão incorretas."],"correta":1,"explicacao":"Gabarito: <strong>Apenas duas estão corretas.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":4195,"enunciado":"Na frase 'É necessário que todos colaborem', a oração 'que todos colaborem' é classificada como oração subordinada substantiva subjetiva, pois exerce a função de sujeito da oração principal, cujo verbo de ligação ('é') está na terceira pessoa do singular.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Instituto IBED","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4196,"enunciado":"Julgue o item a seguir, referente a ideias e aspectos gramaticais do texto precedente. No trecho “se os príncipes tomarem por violência o que se lhes não deve, é rapina e latrocínio” (penúltimo período), a estrutura sintática “o que se lhes não deve” corresponde a o que não lhes é devido.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4198,"enunciado":"Com base no seguinte período, extraído do texto \"Relação conturbada\", analise a estrutura sintática que o compõe e assinale a alternativa correta:\"Não sei direito quem são essas pessoas que vou ver; sei seus nomes, de onde as conheço, e tenho uma imagem vaga de alguns deles, mas não sei como são nem como vou chegar até eles.\"","opcoes":["O período é composto por coordenação assindética e apresenta uma única oração subordinada adjetiva restritiva, introduzida por \"que\", além de orações coordenadas sindéticas conclusivas.","O uso do ponto e vírgula indica que as orações a ele justapostas mantêm entre si relação de subordinação causal, iniciada pelo conector \"mas\", o qual retoma e explica a oração anterior.","O trecho \"de onde as conheço\" é uma oração subordinada substantiva objetiva direta do verbo \"sei\", funcionando como termo acessório e podendo ser suprimido sem prejuízo sintático.","A oração \"quem são essas pessoas que vou ver\" funciona como objeto direto de \"não sei\" e contém, em seu interior, uma oração subordinada adjetiva restritiva iniciada por \"que vou ver\"."],"correta":3,"explicacao":"Gabarito: <strong>A oração \"quem são essas pessoas que vou ver\" funciona como objeto direto de \"não sei\" e contém, em seu interior, uma oração subordinada adjetiva restritiva iniciada por \"que vou ver\".</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4199,"enunciado":"No contexto da frase \"Quem diria que ficar sentado cansa?\", a palavra \"que\" desempenha qual função morfossintática e pertence a qual classe gramatical?","opcoes":["Conjunção coordenativa explicativa, estabelecendo relação lógica com valor de explicação entre as orações do período.","Conjunção integrante, introduzindo uma oração subordinada substantiva.","Conjunção subordinativa causal, estabelecendo relação de causa entre o sujeito da oração principal e a ação de ficar sentado.","Pronome relativo, retomando o termo \"quem\" e introduzindo uma oração subordinada adjetiva."],"correta":1,"explicacao":"Gabarito: <strong>Conjunção integrante, introduzindo uma oração subordinada substantiva.</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4202,"enunciado":"No trecho \"Encarou novamente a maçaneta, certo de que abriria logo\", e na frase \"Então, aquele homem que acabou de sair nos agradou muito\", temos dois tipos distintos de orações subordinadas. Com base na análise sintática e semântica das estruturas, assinale a alternativa correta quanto à classificação dessas orações.","opcoes":["Ambas são orações subordinadas substantivas: a primeira exerce função de objeto indireto e a segunda, função de predicativo do sujeito, pois complementa a noção expressa pelo termo \"homem\".","A oração \"de que abriria logo\" é subordinada substantiva objetiva indireta, pois funciona como objeto indireto do adjetivo \"certo\"; a segunda oração é subordinada substantiva subjetiva, pois exerce o papel de sujeito da oração principal.","Ambas são orações subordinadas adjetivas, pois exercem função de adjunto adnominal, caracterizando os respectivos substantivos a que se referem no período.","A oração \"de que abriria logo\" é subordinada substantiva completiva nominal, pois completa o sentido do adjetivo \"certo\"; já a oração \"que acabou de sair nos agradou muito\" é subordinada adjetiva restritiva, por delimitar o sentido de \"homem\"."],"correta":3,"explicacao":"Gabarito: <strong>A oração \"de que abriria logo\" é subordinada substantiva completiva nominal, pois completa o sentido do adjetivo \"certo\"; já a oração \"que acabou de sair nos agradou muito\" é subordinada adjetiva restritiva, por delimitar o sentido de \"homem\".</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4204,"enunciado":"No trecho \"Certa noite, quis saber se o mundo inteiro dormia com ela\", o vocábulo \"se\" desempenha papel fundamental na construção da oração. Assinale a alternativa que apresenta corretamente a classificação gramatical dessa ocorrência da palavra \"se\".","opcoes":["Conjunção condicional, já que introduz uma hipótese cuja realização depende do sujeito da oração principal.","Conjunção integrante, que introduz uma oração subordinada substantiva objetiva direta, funcionando como complemento do verbo \"saber\".","Conjunção integrante, que introduz uma oração subordinada substantiva objetiva indireta.","Pronome pessoal oblíquo, pois retoma o sujeito oculto e atua como complemento do verbo na forma reflexiva."],"correta":1,"explicacao":"Gabarito: <strong>Conjunção integrante, que introduz uma oração subordinada substantiva objetiva direta, funcionando como complemento do verbo \"saber\".</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4205,"enunciado":"No trecho do texto \"A luavezinha\" − \"Disse que a canção que sonhara ainda ecoava dentro dela\" −, há duas orações subordinadas introduzidas pela conjunção \"que\". Com base na análise sintática e na relação entre as orações, assinale a alternativa que classifica corretamente cada uma delas.","opcoes":["Ambas são orações subordinadas substantivas: a primeira objetiva direta e a segunda subjetiva.","A primeira oração introduzida por \"que\" é subordinada adjetiva, pois se refere a uma ideia abstrata; já a segunda, também iniciada por \"que\", é uma oração subordinada adverbial causal.","A primeira oração iniciada por \"que\" é uma oração subordinada substantiva objetiva direta, e a segunda é uma oração subordinada adjetiva explicativa.","A primeira oração iniciada por \"que\" exerce a função de objeto direto de \"disse\", e a segunda é uma oração subordinada adjetiva restritiva, que caracteriza o substantivo \"canção\"."],"correta":3,"explicacao":"Gabarito: <strong>A primeira oração iniciada por \"que\" exerce a função de objeto direto de \"disse\", e a segunda é uma oração subordinada adjetiva restritiva, que caracteriza o substantivo \"canção\".</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4217,"enunciado":"Com base no seguinte período, extraído do texto \"Relação conturbada\", analise a estrutura sintática que o compõe e assinale a alternativa correta: \"Não sei direito quem são essas pessoas que vou ver; sei seus nomes, de onde as conheço, e tenho uma imagem vaga de alguns deles, mas não sei como são nem como vou chegar até eles.\"","opcoes":["O trecho \"de onde as conheço\" é uma oração subordinada substantiva objetiva direta do verbo \"sei\", funcionando como termo acessório e podendo ser suprimido sem prejuízo sintático.","O uso do ponto e vírgula indica que as orações a ele justapostas mantêm entre si relação de subordinação causal, iniciada pelo conector \"mas\", o qual retoma e explica a oração anterior.","O período é composto por coordenação assindética e apresenta uma única oração subordinada adjetiva restritiva, introduzida por \"que\", além de orações coordenadas sindéticas conclusivas.","A oração \"quem são essas pessoas que vou ver\" funciona como objeto direto de \"não sei\" e contém, em seu interior, uma oração subordinada adjetiva restritiva iniciada por \"que vou ver\"."],"correta":3,"explicacao":"Gabarito: <strong>A oração \"quem são essas pessoas que vou ver\" funciona como objeto direto de \"não sei\" e contém, em seu interior, uma oração subordinada adjetiva restritiva iniciada por \"que vou ver\".</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4228,"enunciado":"Assinale a alternativa que apresenta um trecho do Texto 1 com oração subordinada de função substantiva.","opcoes":["“[...] embora ainda sejam o grupo que menos usa a rede [...]”","“[…] a internet tem feito cada vez mais parte do cotidiano da sociedade, de uma forma geral [...]”","“A oferta de serviços fornecidos pela internet também é um dos motivos que explicam essa ampliação [...]”","“[...] esses números revelam que, em 2016, 44,8% das pessoas com 60 anos ou mais utilizavam a internet.”","“[...] o crescimento expressivo reflete o envelhecimento da população [...]”"],"correta":3,"explicacao":"Gabarito: <strong>“[...] esses números revelam que, em 2016, 44,8% das pessoas com 60 anos ou mais utilizavam a internet.”</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4229,"enunciado":"No período “Um estudo publicado na Revista de Administração Hospitalar e Inovação em Saúde destaca que o fortalecimento e a valorização do SUS são imprescindíveis”, a oração destacada exerce a função de:","opcoes":["Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva subjetiva.","Oração subordinada substantiva completiva nominal.","Oração subordinada adjetiva restritiva."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"JCM CONCURSOS","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4230,"enunciado":"De acordo com o texto, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa correta.( ) No trecho “Os resíduos urbanos, que correspondem àqueles gerados e descartados nas áreas da cidade [...]”, o uso da crase está correto, pois traz a fusão da preposição “a”, exigida pelo verbo, com o pronome demonstrativo “aqueles” que se inicia com a vogal “a”.( ) No excerto “Segundo Marcos Buckeridge, professor do Instituto de Biociências (IB) da USP [...]”, o termo “Biociências” deveria ter sido grafado com hífen: “Bio-ciências”.( ) Em “O docente ainda complementa que, mesmo a coleta domiciliar cobrindo quase toda a população, a participação na coleta seletiva é muito pequena”, o termo “que” é a conjunção integrante que introduz uma oração subordinada substantiva.( ) No título do texto, “São Paulo produz cerca de 20 mil toneladas de resíduos urbanos, mas reciclagem é muito baixa”, é correto afirmar que há duas orações coordenadas, sendo a segunda uma oração coordenada adversativa sindética.","opcoes":["V – V – F – F.","V – F – F – V.","F – V – F – F.","V – F – V – V.","F – F – V – F."],"correta":3,"explicacao":"Gabarito: <strong>V – F – V – V.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["analiseSintatica","crase","hifen"]},{"id":4233,"enunciado":"Assinale a alternativa que NÃO faz a classificação da oração corretamente.","opcoes":["Ela reivindica uma identidade feita de dois inteiros, para que possa ser ao mesmo tempo completamente egípcia e completamente afro-americana. → Oração subordinada adverbial final.","O avião que me levou à América me obrigou a redesenhar meu mapa. → oração subordinada adjetiva restritiva.","Parece que podemos nos dividir até não se identificar mais nada. → oração subordinada substantiva objetiva direta.","Tenho observado o conflito de alguns de meus alunos com essas mesmas questões enquanto tentam entender como sangue, localização e língua se tornam marcas de identidade. → Oração subordinada adverbial temporal."],"correta":2,"explicacao":"Gabarito: <strong>Parece que podemos nos dividir até não se identificar mais nada. → oração subordinada substantiva objetiva direta.</strong>.","banca":"FUMARC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4234,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir. No período “Não há dúvidas que o futuro será ‘analógico’.”, a oração “que o futuro será analógico” funciona como complemento nominal da oração anterior, sendo, portanto, subordinada a ela.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4235,"enunciado":"Com base no texto e nos seus aspectos linguísticos, julgue o item seguinte. No trecho “Não diga que a canção está perdida”, a segunda oração é classificada como subordinada substantiva completiva nominal, ao completar o sentido da primeira.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4237,"enunciado":"Com base nas ideias e nos aspectos gramaticais do texto apresentado, julgue (C ou E) o item a seguir. O paradoxo ao qual o narrador se refere esta contido na oração que exerce função de complemento direto em relação à oração principal “Eu sei dizer sem pudor”, apresentada no período anterior.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IADES","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4241,"enunciado":"Com base no texto, julgue o item a seguir. No período “Imagens gravadas por câmeras de segurança, e que circulam nas redes sociais, mostram que José não reagiu ao assalto”, por modificar a forma verbal “mostram”, a oração “que José não reagiu ao assalto” é adverbial.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4243,"enunciado":"Sobre as orações presentes no período \"Essas lições reforçavam que não era azar, mas uma justiça invisível protegendo o bem\", analise as alternativas abaixo e escolha a correta:","opcoes":["O período é composto por uma oração coordenada assindética: \"Essas lições reforçavam que não era azar\", e uma oração subordinada adjetiva explicativa: \"mas uma justiça invisível protegendo o bem.\"","O período apresenta uma oração principal: \"Essas lições reforçavam\", seguida de uma oração subordinada substantiva completiva: \"que não era azar\".","O período apresenta uma oração subordinada substantiva objetiva direta \"que não era azar\" e uma oração coordenada sindética adversativa \"mas uma justiça invisível protegendo o bem.\"","O período é composto por uma oração coordenada assindética: \"Essas lições reforçavam que não era azar\" e uma oração subordinada substantiva objetiva direta \"que não era azar.\""],"correta":2,"explicacao":"Gabarito: <strong>O período apresenta uma oração subordinada substantiva objetiva direta \"que não era azar\" e uma oração coordenada sindética adversativa \"mas uma justiça invisível protegendo o bem.\"</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4245,"enunciado":"Com base no período “Segundo o pensador, a solidariedade é uma relação moral que permite aos indivíduos se sentirem pertencentes a uma sociedade.” (4º parágrafo), julgue as afirmações abaixo e marque a alternativa correta:I – A vírgula separa um adjunto adverbial.II – A palavra “que” inicia oração subordinada substantiva.III – A oração “se sentirem pertencentes a uma sociedade” é subordinada adverbial condicional.","opcoes":["Todas as afirmações estão corretas.","Somente a afirmação I está correta.","Somente as afirmações I e III estão corretas.","Somente as afirmações II e III estão corretas.","Nenhuma afirmação está correta."],"correta":1,"explicacao":"Gabarito: <strong>Somente a afirmação I está correta.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4249,"enunciado":"A única alternativa que traz uma oração subordinada substantiva subjetiva é:","opcoes":["A minha vontade é que seja feliz.","É essencial que você vença a partida.","Todo ser humano precisa de paz.","Tenho esperança de que as crianças sejam melhor educadas."],"correta":1,"explicacao":"Gabarito: <strong>É essencial que você vença a partida.</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4250,"enunciado":"Sobre o período “É sabido que egípcios e chineses ensinaram ao homem primitivo uma das palavras mais bonitas” (6§), a correta classificação da oração subordinada é:","opcoes":["Substantiva objetiva direta.","Adverbial concessiva.","Substantiva completiva nominal.","Adverbial comparativa.","Substantiva subjetiva."],"correta":4,"explicacao":"Gabarito: <strong>Substantiva subjetiva.</strong>.","banca":"IVIN","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4251,"enunciado":"Qual é a classificação da seguinte oração subordinada: “Tenho certeza de que seremos campeões em 2026.”","opcoes":["substantiva predicativa.","substantiva objetiva indireta","substantiva subjetiva","substantiva completiva nominal."],"correta":3,"explicacao":"Gabarito: <strong>substantiva completiva nominal.</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4253,"enunciado":"No período \"Não, de nosso pai não se podia ter esquecimento; e, se, por um pouco, a gente fazia que esquecia, era só para se despertar de novo, de repente, com a memória, no passo de outros sobressaltos.\", a oração \"que esquecia\" exerce função de:","opcoes":["Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva subjetiva.","Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva apositiva.","Oração subordinada substantiva predicativa."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"FAFIPA","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4254,"enunciado":"Qual é a classificação sintática da oração que se inicia pelo segundo QUE na tirinha abaixo?LANGONA, Fabiane. Viver dói. Folha de São Paulo, 22 de fevereiro de 2025. Disponível em: https://cartum.folha.uol.com.br/quadrinhos/2025/02/22/viverdoi-fabiane-langona.shtml. Acesso em: 22 fev. 2025.","opcoes":["Oração subordinada substantiva subjetiva","Oração subordinada substantiva objetiva direta","Oração subordinada substantiva completiva nominal","Oração subordinada substantiva predicativa","Oração subordinada substantiva apositiva"],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta</strong>.","banca":"Instituto Legatus","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4256,"enunciado":"O excerto em que ocorre um verbo cujo complemento é uma oração é:","opcoes":["“Proponho que ela exista [...]”","“Ouvi o teu suspiro; vi, na penumbra, teus olhos que brilhavam.”","“Que rosa tão bela, mendigo. Onde a colheu?”","“Então vem o primeiro domingo da primavera.”","“Iríamos para a amplidão dos mares.”"],"correta":0,"explicacao":"Gabarito: <strong>“Proponho que ela exista [...]”</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4257,"enunciado":"Leia com atenção as afirmativas abaixo:I.O homem que encontrei na rua era meu antigo professor.II.É necessário que você leia o manual antes de operar o equipamento.III.Avise-me quando o evento começar, por favor.IV.A casa cujas janelas estão quebradas será reformada.V.É importante que você participe das reuniões.Em quais das afirmativas lidas há o emprego de uma oração subordinada substantiva?","opcoes":["III e V.","II e V.","I e III.","II e IV."],"correta":1,"explicacao":"Gabarito: <strong>II e V.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4259,"enunciado":"“A previsão é concluir 2024 com pelo menos 92 mil doações” (4º parágrafo). A oração em destaque é classifi cada sintaticamente como:","opcoes":["principal","coordenada assindética","subordinada adjetiva restritiva","subordinada substantiva predicativa"],"correta":3,"explicacao":"Gabarito: <strong>subordinada substantiva predicativa</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4263,"enunciado":"Na frase \"Propõe que voltem a conversar nas calçadas, sem esses aparelhos.\", o termo \"que\" desempenha uma função essencial na estrutura da oração. Analise as alternativas abaixo e identifique a classe gramatical e a função sintática desse termo no contexto apresentado.","opcoes":["Advérbio, modificando o verbo \"voltem\" e indicando a maneira como a ação deve ocorrer.","Conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta.","Conjunção subordinativa causal, indicando a causa da ação descrita na oração principal.","Pronome relativo, retomando o termo \"conversar\" na oração principal."],"correta":1,"explicacao":"Gabarito: <strong>Conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4266,"enunciado":"Assinalar a alternativa cuja oração sublinhada NÃO é classificada como coordenada.","opcoes":["São amigos, portanto irão à faculdade juntos.","Chorou de alegria, pois ela estava livre.","Jantei e depois descansei.","É provável que ele venha jantar."],"correta":3,"explicacao":"Gabarito: <strong>É provável que ele venha jantar.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4267,"enunciado":"“...todas as espécies trabalham para proteger o nosso meio ambiente.” A oração reduzida “para proteger o nosso meio ambiente” pode ser nominalizada do seguinte modo:","opcoes":["para a proteção do nosso meio ambiente.","para que protejam o nosso meio ambiente.","para que protegessem o nosso meio ambiente.","para o protecionismo do nosso meio ambiente.","para protegerem o nosso meio ambiente."],"correta":0,"explicacao":"Gabarito: <strong>para a proteção do nosso meio ambiente.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4268,"enunciado":"Analise o período abaixo.O identitário grita \"racismo religioso\" ou \"transfobia\" com a mesma celeridade com que o conservador conclui que \"não é certo o ensinamento desse livro\".Em relação às orações subordinadas nele presentes,","opcoes":["a primeira é adjetiva; a última, substantiva.","a primeira é substantiva; a última, adjetiva.","ambas são substantivas.","ambas são adjetivas."],"correta":0,"explicacao":"Gabarito: <strong>a primeira é adjetiva; a última, substantiva.</strong>.","banca":"COMPERVE - UFRN","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4270,"enunciado":"Leia com atenção as alternativas abaixo e assinale aquela que possui o emprego de uma oração subordinada substantiva apositiva:","opcoes":["O gestor afirmou que a transparência é prioridade.","O servidor tinha dúvidas se suas ações estavam corretas.","Todos tinham a certeza de que os princípios éticos seriam seguidos.","O código de conduta estabelece uma regra clara: que os atos administrativos devem ser transparentes."],"correta":3,"explicacao":"Gabarito: <strong>O código de conduta estabelece uma regra clara: que os atos administrativos devem ser transparentes.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4272,"enunciado":"“É assim que a inteligência artificial ajuda a decifrar essas folhas” (5º parágrafo). A oração em destaque classifica-se como subordinada substantiva:","opcoes":["subjetiva","objetiva direta","objetiva indireta","completiva nominal"],"correta":2,"explicacao":"Gabarito: <strong>objetiva indireta</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4273,"enunciado":"No período \"O fato é que somos pouco apaixonados por nós mesmos.\", classifique a oração subordinada \"que somos pouco apaixonados por nós mesmos\", considerando sua função sintática no contexto do período.","opcoes":["Oração Subordinada Substantiva Completiva Nominal.","Oração Subordinada Substantiva Apositiva.","Oração Subordinada Substantiva Subjetiva.","Oração Subordinada Substantiva Predicativa.","Oração Subordinada Substantiva Objetiva Direta."],"correta":3,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Predicativa.</strong>.","banca":"AMAUC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4274,"enunciado":"“[...] e as redes sociais serão em breve obrigadas a tomar “medidas razoáveis” para impedir que os adolescentes tenham contas nas suas plataformas” (2º parágrafo). A oração destacada é classificada como subordinada:","opcoes":["adjetiva restritiva","adjetiva explicativa","substantiva subjetiva","substantiva objetiva direta"],"correta":3,"explicacao":"Gabarito: <strong>substantiva objetiva direta</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4276,"enunciado":"Identifique qual dos períodos abaixo possui uma oração subordinada substantiva completiva nominal:","opcoes":["Eu estava desejando doce mais cedo.","O mais importante é vencer o jogo.","Não te liguei porque estava ocupada.","Nosso desejo é te ver feliz!","Temos fé de que a humanidade pare de destruir o planeta."],"correta":4,"explicacao":"Gabarito: <strong>Temos fé de que a humanidade pare de destruir o planeta.</strong>.","banca":"FACET Concursos","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4277,"enunciado":"Com base no texto \"A fila do mineiro\", de Fabrício Carpinejar, analise as orações abaixo e assinale a alternativa que classifica corretamente a relação sintática entre elas.\"Pensei primeiramente que era um recurso para ampliar o campo de visão e espiar o quanto faltava para o final.\"","opcoes":["A oração \"o quanto faltava para o final\" é subordinada adverbial concessiva, pois estabelece uma relação de contrariedade.","A oração \"que era um recurso\" é subordinada substantiva objetiva direta, pois complementa o verbo \"pensei\".","A oração \"que era um recurso\" é subordinada adverbial causal, pois indica a causa do pensamento expresso na oração principal.","A oração \"para ampliar o campo de visão\" é subordinada adjetiva explicativa, pois caracteriza o termo \"recurso\"."],"correta":1,"explicacao":"Gabarito: <strong>A oração \"que era um recurso\" é subordinada substantiva objetiva direta, pois complementa o verbo \"pensei\".</strong>.","banca":"IGEDUC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4278,"enunciado":"Julgue o próximo item, relativo a aspectos gramaticais do texto 19A1. No último período do segundo parágrafo, a oração “não confundir a língua com o discurso” classifica-se como subordinada substantiva objetiva direta reduzida de infinitivo.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4279,"enunciado":"Identifique a alternativa onde a oração é subordinada:","opcoes":["Não fui convidada para o casamento, mas eu fui assim mesmo.","Hoje eu acordei bem cedo, corri no parque, tomei banho, fui para a escola.","Hoje eu preparei o almoço, limpei a casa, estudei e saí para o cinema.","Tenho certeza de que hoje ele termina o projeto."],"correta":3,"explicacao":"Gabarito: <strong>Tenho certeza de que hoje ele termina o projeto.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4280,"enunciado":"Considerando a estrutura do período composto “Se você duvida, experimente entrar numa favela do Rio vestindo roupa social e vá conversar com os traficantes usando linguagem de magistrado para ver o que lhe acontece”, analise as afirmações abaixo.I- A oração em destaque em “para ver o que lhe acontece” funciona como objeto direto.II- “Se”, no período composto em análise, exerce a função de conjunção integrante.III- “Se”, no período composto em análise, exerce a função de conjunção condicional.IV- A oração introduzida pelo “se” é uma oração subordinada substantiva subjetiva.V- O período é composto por orações subordinadas.É CORRETO o que se afirma apenas em:","opcoes":["I e II.","I, III e IV.","II, IVe V.","I, III e V.","I e III."],"correta":4,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4284,"enunciado":"No período “Sabe-se que o mundo carece de solução para fake news.”, a oração sublinhada é classificada como:","opcoes":["Subordinada substantiva objetiva direta.","Subordinada substantiva subjetiva.","Subordinada substantiva predicativa.","Subordinada substantiva completiva nominal."],"correta":1,"explicacao":"Gabarito: <strong>Subordinada substantiva subjetiva.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4285,"enunciado":"Em “A pesquisa mostrou que o YouTube é a plataforma que tem o melhor impacto e o Instagram é a mais prejudicial para a saúde mental” (4º parágrafo), a oração destacada é classificada como:","opcoes":["principal","coordenada assindética","subordinada substantiva objetiva direta","subordinada substantiva objetiva indireta"],"correta":0,"explicacao":"Gabarito: <strong>principal</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4286,"enunciado":"No período “Os novos estudos em cognição canina, no entanto, revelam que essa é apenas uma pequena parte da complexa inteligência desses animais...”, a oração destacada é classificada como:","opcoes":["Oração subordinada substantiva objetiva indireta.","Oração subordinada substantiva subjetiva.","Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva apositiva."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4287,"enunciado":"Assinale a alternativa cujo exemplo apresentado não está de acordo com a Oração Subordinada Substantiva apresentada:","opcoes":["Oração Subordinada Substantiva Subjetiva. Ex: “Quem tirou nota ruim no primeiro trimestre fará a prova de novo.”","Oração Subordinada Substantiva Objetiva Direta. Ex: “Eu estou vendo que o cachorro está mordendo o meu livro!”","Oração Subordinada Substantiva Objetiva Indireta. Ex: “Eu preciso que você me ajude.”","Oração Subordinada Substantiva Completiva Nominal. Ex: “Ele tem medo que a sogra descubra o seu segredo.”","Oração Subordinada Substantiva Apositiva: Ex: “A regra do jogo é que você não pode me vencer.”"],"correta":4,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Apositiva: Ex: “A regra do jogo é que você não pode me vencer.”</strong>.","banca":"IF-MG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4288,"enunciado":"O período composto é formado por duas ou mais orações e cada oração possui uma determinada classificação. Sendo assim, analise o seguinte trecho: “Se mudássemos o foco e concluíssemos que a infelicidade não existe ,.. ”. Marque a assertiva que apresenta a correta classificação da oração grifada no período em questão.","opcoes":["Oração subordinada adverbial concessiva.","Oração subordinada adverbial comparativa.","Oração subordinada adjetiva explicativa.","Oração subordinada substantiva objetiva indireta.","Oração subordinada substantiva objetiva direta."],"correta":4,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"Instituto Ágata","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4289,"enunciado":"Analise os seguintes períodos compostos presentes no texto e, em seguida, assinale a alternativa CORRETA: PERÍODO 1:PERÍODO 2:PERÍODO 3:Considerando os três períodos compostos descritos acima, assinale a alternativa CORRETA:","opcoes":["No período (2), a oração (2) se classifica como uma oração subordinada adjetiva restritiva.","O período (3) é composto exclusivamente por subordinação.","No período (3), a conjunção integrante que introduz uma oração coordenada sindética aditiva.","No período (1), a oração (2) se classifica como uma oração subordinada substantiva objetiva direta reduzida de infinitivo.","Ainda no período (2), a oração (3) atua como oração coordenada assindética."],"correta":3,"explicacao":"Gabarito: <strong>No período (1), a oração (2) se classifica como uma oração subordinada substantiva objetiva direta reduzida de infinitivo.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4290,"enunciado":"“– Anda, condenado do diabo!” gritou-lhe o pai. Não obtendo resultado, fustigou-o com a bainha da faca de ponta. 1. Sujeito principal 2. Oração Principal 3. Oração subordinada adverbial 4. Oração subordinada substantiva objetiva direta 5. Adjunto adverbial de instrumento – Anda, condenado do diabo ( ) gritou-lhe o pai( ) o pai( ) Não obtendo resultado( ) fustigou-o com a bainha da faca de ponta( ) . ... com a bainha da faca de ponta( ) Assinale a alternativa que apresenta a sequência CORRETA da análise sintática das 05 (cinco) orações destacadas do trecho acima:","opcoes":["5, 2, 3, 1, 2, 4","4, 2, 1, 3, 2, 5","2, 4, 1, 5, 3, 2","3, 1, 4, 2, 5, 3","1, 2, 3, 4, 5, 2"],"correta":1,"explicacao":"Gabarito: <strong>4, 2, 1, 3, 2, 5</strong>.","banca":"IBPTEC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4291,"enunciado":"Note-se que, a essa altura, o problema não era saber se as duas grafias eram corretas, muito menos se cogitava aproveitar o ensejo para discutir a variação ortográfica ou as acepções da palavra.A respeito do período acima, é correto afirmar que","opcoes":["apresenta uma oração coordenada somente.","é composto por seis orações.","há somente uma oração subordinada substantiva subjetiva.","há somente uma oração reduzida de infinitivo."],"correta":0,"explicacao":"Gabarito: <strong>apresenta uma oração coordenada somente.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["analiseSintatica","ortografia"]},{"id":4292,"enunciado":"Talvez essa postura humanizada explique o fato de hoje ser frequente encontrarmos erros gramaticais em livros caros, ilustrados, produzidos em ótimo papel, com capa dura etc.A oração destacada acima se classifica como","opcoes":["subordinada substantiva objetiva direta.","subordinada substantiva completiva nominal.","subordinada substantiva subjetiva.","subordinada substantiva predicativa."],"correta":2,"explicacao":"Gabarito: <strong>subordinada substantiva subjetiva.</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4293,"enunciado":"Leia com atenção as afirmativas abaixo:I.O professor afirmou que a leitura de Machado de Assis é essencial para entender o Realismo.II.O autor expressou apenas uma preocupação: que a obra fosse mal interpretada pelos leitores.III.Os críticos tinham a esperança de que a nova edição valorizasse mais os autores brasileiros.IV.Ela insistiu em que os alunos lessem mais autores do Modernismo.Em qual(is) das afirmativas acima há a presença de uma oração subordinada substantiva apositiva?","opcoes":["II e III.","I e III.","II.","IV."],"correta":2,"explicacao":"Gabarito: <strong>II.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4294,"enunciado":"Analise as funções desempenhadas pela palavra \"que\" na frase: \"Sempre acredita que o resto pode ser usado de noite ou completar o próximo cardápio\" e assinale a alternativa correta.","opcoes":["O termo \"que\" é um pronome relativo, pois retoma o antecedente \"resto\", funcionando como sujeito da oração subordinada.","O termo \"que\" é uma preposição, visto que liga o verbo \"acredita\" à ideia de continuidade expressa na oração subordinada.","A palavra \"que\" é uma conjunção integrante, pois introduz uma oração subordinada substantiva objetiva direta que completa o sentido do verbo \"acredita\".","A palavra \"que\" é uma conjunção subordinativa causal, pois estabelece uma relação de causa entre as orações do período."],"correta":2,"explicacao":"Gabarito: <strong>A palavra \"que\" é uma conjunção integrante, pois introduz uma oração subordinada substantiva objetiva direta que completa o sentido do verbo \"acredita\".</strong>.","banca":"IBAM","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4297,"enunciado":"Assinale a alternativa cuja oração em destaque foi corretamente classificada:","opcoes":["Depois, descobri com sua melhor amiga que ela tinha um único pré-requisito para um partidão: QUE ELE NÃO GOSTASSE DE FUTEBOL. (Oração Subordinada Substantiva Subjetiva)","Jamais cogitou a hipótese DE QUE EU SERIA UM FANÁTICO DO ESPORTE OU DE UM CLUBE. (Oração Subordinada Substantiva Objetiva Indireta)","Esclareci QUE ERA COLORADO DOENTE, cônsul do Inter, ia em todos os jogos.(Oração Subordinada Substantiva Predicativa)","Não queria que entendesse QUE ESTAVA FAZENDO POUCO CASO ... (Oração Subordinada Substantiva Objetiva Direta)"],"correta":3,"explicacao":"Gabarito: <strong>Não queria que entendesse QUE ESTAVA FAZENDO POUCO CASO ... (Oração Subordinada Substantiva Objetiva Direta)</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4298,"enunciado":"Assinale a alternativa cuja oração em destaque foi corretamente classificada:","opcoes":["Esclareci QUE ERA COLORADO DOENT E, cônsul do Inter, ia em todos os jogos.(Oração Subordinada Substantiva Predicativa)","Depois, descobri com sua melhor amiga que ela tinha um único pré-requisito para um partidão: QUE ELE NÃO GOSTASSE DE FUTEBOL. (Oração Subordinada Substantiva Subjetiva)","Jamais cogitou a hipótese DE QUE EU SERIA UM FANÁTICO DO ESPORTE OU DE UM CLUBE. (Oração Subordinada Substantiva Objetiva Indireta)","Não queria que entendesse QUE ESTAVA FAZENDO POUCO CASO ... (Oração Subordinada Substantiva Objetiva Direta)"],"correta":3,"explicacao":"Gabarito: <strong>Não queria que entendesse QUE ESTAVA FAZENDO POUCO CASO ... (Oração Subordinada Substantiva Objetiva Direta)</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4299,"enunciado":"A classificação da oração “Peço-lhe um grande favor: que me deixe em paz” é:","opcoes":["Subordinada Substantiva Apositiva.","Subordinada Substantiva Objetiva Direta.","Subordinada Adverbial Concessiva.","Subordinada Adjetiva Restritiva."],"correta":0,"explicacao":"Gabarito: <strong>Subordinada Substantiva Apositiva.</strong>.","banca":"ADM&TEC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4301,"enunciado":"A classificação da oração sublinhada “Quando retornaram da viagem, o pai perguntou ao filho\" é:","opcoes":["Subordinada adverbial causal.","Subordinada adverbial temporal.","Subordinada substantiva objetiva direta.","Subordinada substantiva objetiva indireta."],"correta":1,"explicacao":"Gabarito: <strong>Subordinada adverbial temporal.</strong>.","banca":"ADM&TEC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4302,"enunciado":"Em “Esses fatores afetam diretamente a capacidade de se concentrar e reter informações”, as duas orações destacadas estão coordenadas entre si. Elas são classificadas como subordinadas:","opcoes":["adjetivas restritivas","adjetivas explicativas","substantivas objetivas indiretas","substantivas completivas nominais"],"correta":3,"explicacao":"Gabarito: <strong>substantivas completivas nominais</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4303,"enunciado":"Na frase \"É de suma importância que acompanhemos a aula\", temos uma oração subordinada substantiva:","opcoes":["Completiva nominal.","Objetiva indireta.","Predicativa.","Subjetiva.","Objetiva direta."],"correta":3,"explicacao":"Gabarito: <strong>Subjetiva.</strong>.","banca":"AMAUC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4304,"enunciado":"Analise os três períodos que seguem: I. É necessário que faças o exame imediatamente.II. Consta que você foi eliminada do certame.III. Espera-se que você entenda a minha situação.As orações em destaque são, respectivamente:","opcoes":["I. Oração Subordinada Substantiva Subjetiva II. Oração Subordinada Substantiva Objetiva Direta III. Oração Subordinada Substantiva Subjetiva","I. Oração Subordinada Substantiva Predicativa II. Oração Subordinada Substantiva Subjetiva III. Oração Subordinada Substantiva Subjetiva","I. Oração Subordinada Substantiva Predicativa II. Oração Subordinada Substantiva Objetiva Direta III. Oração Subordinada Substantiva Subjetiva","I. Oração Subordinada Substantiva Subjetiva II. Oração Subordinada Substantiva Subjetiva III. Oração Subordinada Substantiva Subjetiva","I. Oração Subordinada Substantiva Subjetiva II. Oração Subordinada Substantiva Objetiva Direta III. Oração Subordinada Substantiva Objetiva Direta"],"correta":3,"explicacao":"Gabarito: <strong>I. Oração Subordinada Substantiva Subjetiva II. Oração Subordinada Substantiva Subjetiva III. Oração Subordinada Substantiva Subjetiva</strong>.","banca":"AMAUC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4305,"enunciado":"As orações subordinadas são aquelas que dependem de outras no período e que não têm sentido completo se aparecerem isoladas. Assim sendo, indique a alternativa, a qual há uma oração subordinada destacada, corretamente classificada.","opcoes":["“Na mesma hora em que li esse relato, imaginei um sem-número de sons [...] (linha 6) (adverbial temporal)","“E o mais aliviante para pais que possuem adolescentes baladeiros [...]” (linha 7) (substantiva objetiva direta)","“Uma conversa em outro idioma na mesa ao lado da sua, provocando a falsa sensação de que você está viajando (linha 17) [...]” (substantiva completiva nominal)","“O barulho da chuva forte no meio da madrugada, quando você está no quentinho da sua cama.” (linha 16) (adjetiva restritiva)","“[...] fazendo você lembrar que o mundo não é tão vasto assim.” (linha 19) (substantiva objetiva indireta)"],"correta":2,"explicacao":"Gabarito: <strong>“Uma conversa em outro idioma na mesa ao lado da sua, provocando a falsa sensação de que você está viajando (linha 17) [...]” (substantiva completiva nominal)</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4306,"enunciado":"Dado o excerto: “Aí lembrei que não tenho conta no Banco do Brasil (...).” A oração subordinada presente no fragmento pode ser classificada como:","opcoes":["Oração subordinada adjetiva explicativa.","Oração subordinada substantiva objetiva indireta.","Oração subordinada substantiva subjetiva.","Oração subordinada substantiva objetiva direta.","Nenhuma das alternativas anteriores."],"correta":3,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"FucapSul","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4309,"enunciado":"“A equipe descobriu que as temperaturas noturnas na superfície lunar caíram significativamente durante o rigoroso período de bloqueio, de abril a maio de 2020” (1º parágrafo). Nesse trecho, a oração destacada pode ser classificada como:","opcoes":["oração principal","oração coordenada assindética","oração subordinada adjetiva restritiva","oração subordinada substantiva objetiva direta"],"correta":0,"explicacao":"Gabarito: <strong>oração principal</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4310,"enunciado":"Qual frase destacada não se classifica como oração subordinada substantiva, desempenhando o papel de complemento nominal?","opcoes":["Sempre tive uma imensa vontade de que ele viajasse comigo.","O diretor da empresa necessita de que todos os colaboradores estejam presentes na reunião.","Temos fé de que a humanidade pare de destruir o planeta.","Estamos bem longe do que seria o ideal."],"correta":1,"explicacao":"Gabarito: <strong>O diretor da empresa necessita de que todos os colaboradores estejam presentes na reunião.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4311,"enunciado":"No trecho “[...] acham que não obrigando o povo a tomar seu café da manhã com pão dormido conseguirão não sei bem o que do governo.” (1º§), a oração em destaque exerce a função de:","opcoes":["Oração subordinada adverbial final.","Oração subordinada adjetiva explicativa.","Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva completiva nominal."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4312,"enunciado":"Após a leitura do trecho abaixo, analise as explicações fornecidas acerca de alguns recursos linguísticos nele presentes.“O Crisóstomo disse ao Camilo: todos nascemos filhos de mil pais e de mais de mil mães, e a solidão é sobretudo a incapacidade de ver qualquer pessoa como nos pertencendo, para que nos pertença de verdade e se gere um cuidado mútuo”.I- A conjunção “sobretudo”, no contexto mencionado, tem função modalizadora, com valor de reforço do enunciador ao próprio enunciado.II- O uso do “e” em: “e a solidão é sobretudo a incapacidade de ver qualquer pessoa como nos pertencendo” estabelece uma oração coordenada adversativa.III- “filhos de mil pais e de mais de mil mães” é uma locução adjetiva que assume na oração função de predicativo do sujeito.IV- “de ver qualquer pessoa como nos pertencendo” é uma oração subordinada substantiva completiva nominal reduzida de infinitivo.É CORRETO o que se afirma apenas em:","opcoes":["II e III.","I, II e IV.","I e II.","I e IV.","III e IV."],"correta":1,"explicacao":"Gabarito: <strong>I, II e IV.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4313,"enunciado":"A sequência: “Saulo gostava de estudar matemática básica”, é formada por:","opcoes":["Uma oração subordinada adverbial.","Uma oração subordinada substantiva objetiva direta.","Uma oração subordinada substantiva objetiva indireta.","Uma oração subordinada completiva nominal."],"correta":2,"explicacao":"Gabarito: <strong>Uma oração subordinada substantiva objetiva indireta.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4314,"enunciado":"A sequência: “Ana gostava de se vestir de forma elegante”, é formada por:","opcoes":["Uma oração subordinada adverbial.","Uma oração subordinada substantiva objetiva direta.","Uma oração subordinada completiva nominal.","Uma oração subordinada substantiva objetiva indireta."],"correta":3,"explicacao":"Gabarito: <strong>Uma oração subordinada substantiva objetiva indireta.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4315,"enunciado":"O arqueólogo Alexander Marshack, da Universidade de Harvard, explicou \"que essas marcas representam as diferentes fases da Lua\", indicando que o osso foi usado como um calendário lunar de seis meses.Assinale a alternativa correta quanto à classificação da oração destacada.","opcoes":["Coordenada sindética explicativa.","Explicativa intercalada.","Subordinada substantiva completiva nominal.","Subordinada substantiva objetiva direta."],"correta":3,"explicacao":"Gabarito: <strong>Subordinada substantiva objetiva direta.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4316,"enunciado":"Leia com atenção as afirmativas abaixo:I.Tenho esperança de que tudo se resolva logo.II.Só tenho um desejo: que todos sejam felizes.III.É importante que você estude todos os dias.IV.Convém que todos compareçam à reunião.V.Ele tinha certeza de que conseguiria o emprego.Em quais das afirmativas lidas há o emprego de uma oração subordinada substantiva subjetiva?","opcoes":["I e V.","II e IV.","I e III.","III e IV."],"correta":3,"explicacao":"Gabarito: <strong>III e IV.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4317,"enunciado":"Assinale a alternativa que possui o emprego de uma oração subordinada substantiva completiva nominal:","opcoes":["É fundamental que todos cumpram as regras de segurança.","Informei aos alunos que a prova será na próxima semana.","Temos esperança de que a situação melhore em breve.","Ele se esqueceu de contar que chegaria mais tarde."],"correta":2,"explicacao":"Gabarito: <strong>Temos esperança de que a situação melhore em breve.</strong>.","banca":"ACCESS","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4318,"enunciado":"Analise e assinale a classificação correta da oração abaixo:“Temos fé de que o time brasileiro ganhe o jogo hoje.”","opcoes":["Oração Subordinada Substantiva Subjetiva","Oração Subordinada Substantiva Predicativa","Oração Subordinada Substantiva Completiva Nominal","Oração Subordinada Substantiva Objetiva Direta"],"correta":2,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Completiva Nominal</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4319,"enunciado":"Relacione e assinale a alternativa correta: 1- Oração Subordinada Substantiva Apositiva 2- Oração Subordinada Substantiva Predicativa 3- Oração Subordinada Substantiva Objetiva Indireta ( ) “Juliana duvida de que você consiga.” ( ) “Tenho um desejo: que tudo dê certo.” ( ) “Meu desejo é que você seja feliz.”","opcoes":["1 – 2 – 3","3 – 1 – 2","3 – 2 – 1","1 – 3 – 2"],"correta":1,"explicacao":"Gabarito: <strong>3 – 1 – 2</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4321,"enunciado":"No texto \"Viajar com casal de amigos\", de Fabrício Carpinejar, a seguinte frase é um exemplo de período composto por subordinação:\"O que deveria ser leve, com drinks e mergulhos, vira martírio.\"Assinale a alternativa que analisa corretamente a estrutura sintática da oração subordinada presente no período:","opcoes":["A oração \"vira martírio\" é subordinada substantiva objetiva direta, pois completa o sentido do verbo da oração subordinada anterior.","A oração \"com drinks e mergulhos\" é subordinada adverbial causal, indicando a razão de algo ser considerado leve.","A oração \"O que deveria ser leve\" é subordinada adjetiva explicativa, pois especifica o que é referido pelo pronome relativo \"que\".","A oração \"O que deveria ser leve\" é subordinada substantiva subjetiva, pois exerce a função de sujeito da oração principal \"vira martírio\"."],"correta":3,"explicacao":"Gabarito: <strong>A oração \"O que deveria ser leve\" é subordinada substantiva subjetiva, pois exerce a função de sujeito da oração principal \"vira martírio\".</strong>.","banca":"IGEDUC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4322,"enunciado":"Em \"A cobradora, cordial, perguntou se ela teria uma moedinha de vinte e cinco centavos para facilitar e devolver um real\" a oração \"se ela teria uma moedinha de vinte e cinco centavos\" é classificada como:","opcoes":["oração principal.","oração subordinada substantiva objetiva direta.","oração coordenada sindética explicativa.","oração subordinada substantiva objetiva indireta."],"correta":1,"explicacao":"Gabarito: <strong>oração subordinada substantiva objetiva direta.</strong>.","banca":"IGEDUC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4323,"enunciado":"O trecho ‘de que o explorador era um italiano de Gênova.’ (linha 11) ligado ao termo ‘teoria’ (linha 09) compõe uma oração nomeada:","opcoes":["oração principal.","subordinada substantiva completiva nominal.","coordenada assindética.","subordinada substantiva objetiva indireta.","coordenada sindética explicativa."],"correta":1,"explicacao":"Gabarito: <strong>subordinada substantiva completiva nominal.</strong>.","banca":"ADVISE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4324,"enunciado":"Sobre a relação entre as orações subordinadas e o desenvolvimento do argumento no texto, assinale a alternativa CORRETA.","opcoes":["No período “É certo que as grandes empresas de tecnologia detêm um poder sem precedentes” contém uma oração subordinada substantiva subjetiva.","Aoração “que as grandes empresas de tecnologia detêm um poder sem precedentes” é uma oração subordinada adverbial causal.","A oração “a exposição prolongada a plataformas digitais pode prejudicar a sua atenção sustentada” é uma oração subordinada substantiva subjetiva.","Aoração “a pressão para estar sempre conectado e atendendo aos modelos de vida expostos pode lhe gerar ansiedade” é uma oração subordinada adjetiva explicativa.","A oração “a exposição prolongada a plataformas digitais pode prejudicar a sua atenção sustentada” é uma oração subordinada adverbial final."],"correta":0,"explicacao":"Gabarito: <strong>No período “É certo que as grandes empresas de tecnologia detêm um poder sem precedentes” contém uma oração subordinada substantiva subjetiva.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4325,"enunciado":"O excerto “É essencial que todos auxiliem na busca de ajuda médica e psicológica ao observar esses sinais” trata-se de uma oração","opcoes":["coordenada sindética consecutiva.","subordinada substantiva subjetiva.","subordinada substantiva objetiva direta.","coordenada sindética aditiva."],"correta":1,"explicacao":"Gabarito: <strong>subordinada substantiva subjetiva.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4326,"enunciado":"Em \"Quando estamos alegres, temos a sensação de que devemos seguir em frente\" temos uma oração subordinada adverbial temporal (Quando estamos alegres) e uma oração subordinada substantiva objetiva indireta (de que devemos seguir em frente).\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4327,"enunciado":"Em \"A alegria é uma atitude, por isso, não devemos esperar que os outros nos alegrem\" temos uma oração subordinada objetiva direta em \"que os outros nos alegrem\" e um exemplo de predicado nominal na oração \"A alegria é uma atitude\".\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4328,"enunciado":"No período \"Creio que foi a principal coisa que me aconteceu\" é classificado como Período Composto por Coordenação e Subordinação, visto que, é formado de uma oração coordenada e de uma oração subordinada em sua estrutura.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4330,"enunciado":"No trecho “É um desejo claro de a China formar muitos professores e tradutores de língua portuguesa”, a preposição “de” aparece separada do artigo “a” que antecede o substantivo “China”. Considerando as relações sintáticas e semânticas estabelecidas por essa construção, assinale a alternativa CORRETA.","opcoes":["A separação da preposição “de” do artigo “a” configura um desvio da norma culta, caracterizando um erro gramatical que compromete a clareza e a coesão do texto.","A construção “de a China” evidencia uma marca de oralidade presente no texto, resultante da transcrição de uma fala espontânea e informal do professor Caio César Christiano.","A construção “de a China” configura um caso de topicalização do sujeito da oração subordinada, destacando o agente da ação de formar professores e tradutores.","A preposição “de” separada do artigo “a” introduz uma oração subordinada substantiva completiva nominal, na qual o termo “a China” exerce a função de sujeito."],"correta":3,"explicacao":"Gabarito: <strong>A preposição “de” separada do artigo “a” introduz uma oração subordinada substantiva completiva nominal, na qual o termo “a China” exerce a função de sujeito.</strong>.","banca":"CONSULPAM","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4331,"enunciado":"Sobre as seguintes orações subordinadas do texto “Violência de gênero: índices são ruins e devem piorar”, podemos fazer as seguintes afirmações:I. A oração “que falhamos miseravelmente em proteger crianças, mulheres e a população negra” é uma oração subordinada substantiva objetiva direta, pois complementa o sentido do verbo “confirmam”.II. A oração “No mesmo tempo em que você gasta assistindo a 20 vídeos de 30 segundos no TikTok” é uma oração subordinada adverbial temporal, pois indica o tempo em que ocorre a ação descrita na oração principal.III. A oração “É bastante provável que essa vítima tenha no máximo 13 anos” contém uma oração subordinada substantiva subjetiva, que funciona como sujeito do verbo “é”.IV. A oração “quando se é mulher” é uma oração subordinada adverbial temporal, pois indica uma circunstância de tempo na oração principal.Estão corretas apenas as alternativas:","opcoes":["II e III","I, II e III","I e III","II, III e IV","I, II e IV"],"correta":0,"explicacao":"Gabarito: <strong>II e III</strong>.","banca":"IF-TO","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4332,"enunciado":"Os dois primeiros versos da estrofe formam um período composto por subordinação. Assinale a alternativa que classifica correta, e respectivamente, as orações desse período.","opcoes":["oração principal e oração substantiva objetiva direta.","oração adjetiva explicativa e oração principal.","oração principal e oração adjetiva restritiva.","oração principal e oração substantiva subjetiva."],"correta":0,"explicacao":"Gabarito: <strong>oração principal e oração substantiva objetiva direta.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4334,"enunciado":"Qual alternativa NÃO apresenta uma oração subordinada?","opcoes":["Eu sei que a prova é amanhã à noite.","Tenho muitos amigos. Carlos é velho, João é jovem.","Ele foi embora, mesmo com muita vontade de ficar.","Flávia tem certeza de que irá comer muito no almoço."],"correta":1,"explicacao":"Gabarito: <strong>Tenho muitos amigos. Carlos é velho, João é jovem.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4335,"enunciado":"Julgue o item subsequente. As orações subordinadas são aquelas que podem estar coordenadas entre si, podem ser as principais, podem ser independentes ou propriamente subordinadas (desenvolvidas ou reduzidas).\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4336,"enunciado":"A classificação de uma oração se dá quando identificamos sua função, sendo ela subordinada ou coordenada. Assinale a alternativa que tem oração com função subordinativa:","opcoes":["O caçador percebeu que a noite chegou.","O caçador percebe a chegada da noite.","A chegada da noite foi percebida pelo caçador.","A chegada da noite percebeu o caçador."],"correta":0,"explicacao":"Gabarito: <strong>O caçador percebeu que a noite chegou.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4337,"enunciado":"No período composto “O importante é que ele me faz rir”, a oração em destaque se classifica CORRETAMENTE como uma oração subordinada:","opcoes":["substantiva objetiva direta.","substantiva predicativa.","substantiva completiva nominal.","adjetiva restritiva.","adverbial causal."],"correta":1,"explicacao":"Gabarito: <strong>substantiva predicativa.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4339,"enunciado":"No período composto “Bem que dizem que repartir é morrer um pouco ”, a oração em destaque se classifica do ponto de vista sintático como uma:","opcoes":["oração subordinada adverbial temporal.","oração subordinada adjetiva restritiva.","oração subordinada substantiva objetiva direta.","oração coordenada sindética explicativa.","oração coordenada sindética conclusiva."],"correta":2,"explicacao":"Gabarito: <strong>oração subordinada substantiva objetiva direta.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4340,"enunciado":"Leia o período composto presente no primeiro quadrinho: Perco o amigo, mas não perco a piada. A oração em destaque é CORRETAMENTE classificada como:","opcoes":["oração subordinada substantiva subjetiva.","oração coordenada sindética aditiva.","oração coordenada assindética.","oração coordenada sindética adversativa.","oração subordinada adjetiva restritiva."],"correta":3,"explicacao":"Gabarito: <strong>oração coordenada sindética adversativa.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4342,"enunciado":"No período: “É fundamental que o aluno participe ativamente de sua aprendizagem.”, a oração destacada é substantiva","opcoes":["objetiva direta.","objetiva indireta.","subjetiva.","completiva nominal.","predicativa."],"correta":2,"explicacao":"Gabarito: <strong>subjetiva.</strong>.","banca":"CETREDE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4343,"enunciado":"Em \"O Comitê disse que essa era uma decisão do Estado francês\". O período é formado por:","opcoes":["Uma oração principal e uma subordinada substantiva objetiva direta.","Uma oração principal e uma subordinada adverbial causal.","Uma oração principal e uma subordinada adjetiva restritiva.","Uma oração assindética e substantiva objetiva indireta."],"correta":0,"explicacao":"Gabarito: <strong>Uma oração principal e uma subordinada substantiva objetiva direta.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4344,"enunciado":"Acerca de aspectos gerais do texto, julgue o item a seguir. No subtítulo, a oração “ter adquirido conhecimento na área” classifica‑se como subordinada substantiva.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4345,"enunciado":"Considerando a estrutura do período composto “Ela também presumiu que eu não sabia como usar um fogão”, analise as afirmações abaixo.I- Ela também presumiu exerce a função sintática de oração principal. II- Que, no período composto em análise, exerce a função de conjunção integrante. III- Que, no período composto em análise, exerce a função de pronome relativo. IV- A oração introduzida pelo que se classifica como oração subordinada substantiva objetiva direta. V- A oração introduzida pelo que se classifica como oração subordinada adverbial consecutiva. É CORRETO o que se afirma apenas em:","opcoes":["I, III e V.","I, III e IV.","II, IV e V.","I, II e IV.","I e II."],"correta":3,"explicacao":"Gabarito: <strong>I, II e IV.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4346,"enunciado":"Assinale a única alternativa que possui uma oração subordinada substantiva subjetiva.","opcoes":["Ficou estabelecido que todos os estudantes ficassem em silêncio durante a aplicação da prova.","O fato é que todos naquela sala pareciam muito concentrados e disciplinados.","Os professores tinham certeza de que seus estudantes estavam bem preparados.","Todos ali desejavam apenas uma coisa: que o tempo passasse lentamente."],"correta":0,"explicacao":"Gabarito: <strong>Ficou estabelecido que todos os estudantes ficassem em silêncio durante a aplicação da prova.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4347,"enunciado":"Em qual frase há oração subordinada substantiva predicativa?","opcoes":["Meu desejo é que você passe na prova do Enem.","Sou a favor que o reprovem.","Desejo que sejas feliz.","O aluno que não estuda não consegue superar as dificuldades do vestibular."],"correta":0,"explicacao":"Gabarito: <strong>Meu desejo é que você passe na prova do Enem.</strong>.","banca":"AGIRH","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4348,"enunciado":"A partir das Orações Subordinadas, leia as assertivas e assinale a incorreta.","opcoes":["“Acordamos cedo para viajar” é uma oração subordinada adverbial final.","“É fundamental que participem das reuniões trimestrais” é uma oração subordinada substantiva subjetiva.","“O problema é só um: que eu não estudei para as provas semestrais” é uma oração subordinada substantiva predicativa.","“Não gosto de comer doces, porque engordo” é uma oração subordinada adverbial causal.","“Caso você venha, jantamos juntos” é uma oração subordinada adverbial condicional."],"correta":2,"explicacao":"Gabarito: <strong>“O problema é só um: que eu não estudei para as provas semestrais” é uma oração subordinada substantiva predicativa.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4350,"enunciado":"Veja a propaganda abaixo e analise as assertivas: I- Mediante o texto verbal da propaganda, é válida a pressuposição de que os designers são pressionados pelo pouco tempo para criar um projeto. II- No período composto “Não somos panela para trabalhar sob pressão”, temos um período composto por coordenação. III- No período composto “Não somos panela para trabalhar sob pressão”, a oração em destaque é uma oração subordinada adverbial final. IV- O enunciado “Respeite o tempo de um designer” visa a persuadir o interlocutor. V- No período composto “Ideias levam tempo para serem desenvolvidas”, a oração em destaque se classifica como uma oração coordenada sindética conclusiva. É CORRETO o que se afirma apenas em:","opcoes":["I, III e V.","I, II e IV.","II, III e IV.","III, IV e V.","I, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, III e IV.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4351,"enunciado":"Analise os seguintes períodos compostos presentes no texto e, em seguida, assinale a alternativa CORRETA:Considerando os três períodos compostos descritos acima, assinale a alternativa CORRETA:","opcoes":["No período (2), a oração (2) se classifica como uma oração subordinada adjetiva restritiva.","O período (3) é composto exclusivamente por subordinação.","No período (3), a conjunção integrante que introduz uma oração coordenada sindética aditiva.","No período (1), a oração (2) se classifica como uma oração subordinada substantiva objetiva direta reduzida de infinitivo.","Ainda no período (2), a oração (3) atua como oração coordenada assindética."],"correta":3,"explicacao":"Gabarito: <strong>No período (1), a oração (2) se classifica como uma oração subordinada substantiva objetiva direta reduzida de infinitivo.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4352,"enunciado":"No verso “E garanto que não beberei nunca mais”, a segunda oração é:","opcoes":["Oração subordinada substantiva objetiva direta.","Oração subordinada adverbial causal.","Oração subordinada adjetiva restritiva.","Oração subordinada substantiva apositiva."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4353,"enunciado":"Em relação à subordinação das orações, assinale a afirmativa que apresenta oração subordinada completiva nominal.","opcoes":["“Os filhos aprendem em casa com os valores que veem e presenciam em sua vida diária.” (6º§)","“[...] Raimundo e Curvelo, que me deram o primeiro conhecimento, um da corrupção, outro da delação.” (7º§)","“[…] mas meu pai respondia que aplicava na minha educação um sistema inteiramente superior ao sistema usado [...]” (2º§)","“[...] mas ser preconceituoso com tranquilidade, furar filas e defender na vida prática o contrário do que entrega no texto escolar.” (8º§)"],"correta":3,"explicacao":"Gabarito: <strong>“[...] mas ser preconceituoso com tranquilidade, furar filas e defender na vida prática o contrário do que entrega no texto escolar.” (8º§)</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4354,"enunciado":"A pesquisadora defende que pessoas surdas possam se comunicar sem a necessidade de intérpretes... A oração destacada deve ser classificada como:","opcoes":["Oração subordinada substantiva objetiva indireta.","Oração subordinada substantiva objetiva direta.","Oração subordinada adjetiva restritiva.","Oração subordinada adjetiva explicativa."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4355,"enunciado":"Assinale a alternativa que corresponde à função exercida pela oração em destaque no último período do Texto 1.","opcoes":["Substantiva.","Adjetiva.","Adverbial.","Explicativa."],"correta":0,"explicacao":"Gabarito: <strong>Substantiva.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4356,"enunciado":"Na língua portuguesa, o conectivo “que” pode ocupar diversas funções sintáticas e morfológicas. Nesse sentido, analise todos os casos de recorrência do “que, no texto exposto, e indique a alternativa que se refere adequadamente ao seu emprego.","opcoes":["No verso “um cavalo mais veloz que o pensamento”, possui função integrante.","No verso “Quero que ele me leve para bem longe”, introduz uma oração subordinada substantiva.","No verso “e que galope ao deus-dará”, é uma conjunção adverbial comparativa.","No verso “que já me cansei deste engarrafamento...”, desempenha função conclusiva.","Em todas as recorrências destacadas, expressa a ideia de explicação."],"correta":1,"explicacao":"Gabarito: <strong>No verso “Quero que ele me leve para bem longe”, introduz uma oração subordinada substantiva.</strong>.","banca":"APICE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4357,"enunciado":"Assinale a opção em que a oração destacada pode ser classificada como subordinada substantiva objetiva direta:","opcoes":["“... faz com que a escola se adapte para uma vida moderna, mas de maneira defensiva, tardia, ...”;","“Enquanto isso, nós continuamos longe de atingir a meta de alfabetizar todas as crianças até os 8 anos de idade...”;","“É preciso abandonar a crença de que as atitudes dos professores só se modificam na medida em que os docentes percebem resultados positivos na aprendizagem dos alunos.”;","“Já sabemos que não basta, como se pensou nos anos 1950 e 1960, dotar professores de livros e novos materiais pedagógicos.”;","“Enquanto isso, nós continuamos longe de atingir a meta de alfabetizar todas as crianças até os 8 anos de idade e carregando o fardo de um baixo desempenho no IDEB.”."],"correta":3,"explicacao":"Gabarito: <strong>“Já sabemos que não basta, como se pensou nos anos 1950 e 1960, dotar professores de livros e novos materiais pedagógicos.”;</strong>.","banca":"INAZ do Pará","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4359,"enunciado":"Analise as sentenças a seguir e assinale aquela em que ocorre uma oração subordinada substantiva subjetiva.","opcoes":["A expectativa é de que o professor cancele a prova.","Ela se esqueceu de anotar os compromissos naquele dia.","Não é segredo que eles já não se toleram no ambiente de trabalho.","Não demore muito, que estou com pressa.","Os meninos foram suspensos porque só faziam bagunça na sala de aula."],"correta":2,"explicacao":"Gabarito: <strong>Não é segredo que eles já não se toleram no ambiente de trabalho.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4360,"enunciado":"Em “o estudo lembra o chamado ‘efeito de superioridade da imagem’, que classifica as imagens como mais memoráveis e emocionalmente evocativas do que os textos”, a oração sublinhada classifica-se como:","opcoes":["Oração subordinada adjetiva explicativa.","Oração subordinada substantiva objetiva direta.","Oração subordinada adjetiva restritiva.","Oração coordenada assindética."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada adjetiva explicativa.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4361,"enunciado":"Leia com atenção a afirmativa a seguir: Eu gosto muito de corrida de carro, embora não saiba dirigir. Qual o tipo de oração subordinada empregada acima?","opcoes":["Oração subordinada adverbial concessiva.","Oração subordinada adverbial conformativa.","Oração subordinada substantiva predicativa.","Oração subordinada adjetiva explicativa."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada adverbial concessiva.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4362,"enunciado":"Julgue o item subsequente. As orações subordinadas substantivas, como em \"Espero que vocês consigam\", têm a função de complementar o sentido do verbo da oração principal, atuando como seu objeto direto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4363,"enunciado":"Julgue o item subsequente. No período \"É necessário que todos participem da reunião\", a oração \"que todos participem da reunião\" é uma oração subordinada substantiva completiva nominal que completa o sentido do adjetivo \"necessário\" na oração principal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4364,"enunciado":"No trecho do parágrafo 4 “Tim Nichols, um reconhecido pesquisador norte-americano, anunciou que seu livro The Death of Expertise, em português ‘A Morte da Expertise’, aborda a descrença do cidadão comum”, a palavra “que” exerce a mesma função da que está destacada em:","opcoes":["“a ciência nos permite analisar o mundo ao redor e ver além do que os olhos podem enxergar” (parágrafo 2)","“o principal responsável por tudo que a humanidade construiu até aqui” (parágrafo 2)","“Suas realizações estão presentes desde o domínio do fogo até as imensas potencialidades que derivam da moderna ciência da informação” (parágrafo 2)","“apesar de todas as evidências científicas em contrário, parecem corroborar que a análise de Nichols está correta” (parágrafo 4)","“problemas crônicos do subdesenvolvimento, que vão desde o acesso à saúde e à educação de qualidade até questões ambientais e urbanas” (parágrafo 5)"],"correta":3,"explicacao":"Gabarito: <strong>“apesar de todas as evidências científicas em contrário, parecem corroborar que a análise de Nichols está correta” (parágrafo 4)</strong>.","banca":"CESGRANRIO","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4365,"enunciado":"Leia a tira:Em relação a ela, é CORRETO o que se diz em:","opcoes":["Ela apresenta dois períodos sendo 1 composto por COORDENAÇÃO e 1 composto por SUBORDINAÇÃO.","Ela apresenta apenas 1 período composto por 4 orações SUBORDINADAS.","Ela apresenta 1 único período MISTO, com a ideia de COORDENAÇÃO e SUBORDINAÇÃO.","Ela apresenta um PERÍODO SIMPLES."],"correta":0,"explicacao":"Gabarito: <strong>Ela apresenta dois períodos sendo 1 composto por COORDENAÇÃO e 1 composto por SUBORDINAÇÃO.</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4367,"enunciado":"Na frase “E assim, quando mais tarde me procure...”, a oração em destaque está corretamente classificada em:","opcoes":["Oração Coordenada Sindética Explicativa","Oração Principal","Oração Subordinada Substantiva Subjetiva","Oração Subordinada Adverbial Temporal"],"correta":3,"explicacao":"Gabarito: <strong>Oração Subordinada Adverbial Temporal</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4369,"enunciado":"No trecho \"E o homem responde QUE AINDA FALTAVA MUITO\" a oração \"QUE AINDA FALTAVA MUITO\" é classificada como:","opcoes":["Oração Subordinada Substantiva Predicativa.","Oração Subordinada Substantiva Completiva Nominal.","Oração Subordinada Substantiva Subjetiva.","Oração Subordinada Substantiva Objetiva Direta.","Oração Subordinada Substantiva Objetiva indireta."],"correta":3,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Objetiva Direta.</strong>.","banca":"Instituto Abaré-eté","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4370,"enunciado":"No período: “Convenci-me de que não estou nada bem...” A oração destacada é:","opcoes":["Oração Principal","Oração Subordinada Substantiva Subjetiva","Oração Subordinada Substantiva Predicativa","Oração Subordinada Substantiva Objetiva Indireta"],"correta":3,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Objetiva Indireta</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4371,"enunciado":"Relacione as colunas de acordo com a classificação das orações subordinadas: Classificação das Orações Subordinadas (1) Oração Sub. Adverbial Causal (2) Oração Sub. Adjetiva Restritiva (3) Oração Sub. Substantiva Objetiva Direta. (4) Oração Sub. Adverbial Concessiva Frases (A) Ele não veio porque estava doente. (B) O livro que você me deu é muito interessante. (C) Espero que você venha à festa. (D) Embora estivesse chovendo, ele saiu para correr. Agora, escolha a opção que indica corretamente a relação entre as colunas:","opcoes":["1-A, 2-B, 3-C, 4-D","1-B, 2-A, 3-D, 4-C","1-D, 2-C, 3-B, 4-A","1-C, 2-D, 3-A, 4-B"],"correta":0,"explicacao":"Gabarito: <strong>1-A, 2-B, 3-C, 4-D</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4372,"enunciado":"Escolha a opção que apresenta um exemplo de Oração Subordinada Substantiva Completiva Nominal.”","opcoes":["Desejo uma coisa: que sejas feliz.","A senhora Roberta disse que ela própria iria comprar as flores.","Necessitávamos de que nos ajudasse.","Sou favorável a que o condenem."],"correta":3,"explicacao":"Gabarito: <strong>Sou favorável a que o condenem.</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4373,"enunciado":"Assinale a alternativa que presente a função sintática exercida pela oração subordinada em destaque no período: “Apesar disso, nesta semana, o governo afirmou que a maioria dos estados brasileiros já superou o pico de casos de dengue”.","opcoes":["Objeto Indireto.","Sujeito.","Objeto Direto.","Aposto.","Predicativo do Sujeito."],"correta":2,"explicacao":"Gabarito: <strong>Objeto Direto.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4374,"enunciado":"Considerando a estrutura do período composto “Pediu-me que fosse encontrá-lo depois do almoço no porto.”, analise as afirmações abaixo.I- Pediu-me exerce a função sintática de oração principal. II- Que, no período composto em análise, exerce a função de conjunção integrante. III- Que, no período composto em análise, exerce a função de pronome relativo. IV- A oração introduzida pelo que se classifica como oração subordinada substantiva objetiva direta. que V- A oração introduzida pelo que se classifica como oração subordinada substantiva subjetiva. É CORRETO o que se afirma apenas em:","opcoes":["II, IV e V.","I, III e IV.","I, II e IV.","I, III e V.","I e II."],"correta":2,"explicacao":"Gabarito: <strong>I, II e IV.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4375,"enunciado":"Considerando o que diz a norma-padrão, a respeito de orações subordinadas reduzidas, analise as assertivas acerca das propostas de expansão e classificação das orações que se encontram reduzidas:I- Reduzida: É essencial . comparecer à reunião pedagógica Desenvolvida: É essencial que você compareça à reunião pedagógica. Classificação da oração reduzida: Oração Subordinada Substantiva Subjetiva. II- Reduzida: Os alunos não sabiam ser dia de prova. Desenvolvida: Os alunos não sabiam que era dia de prova. Classificação da oração reduzida: Oração Subordinada Substantiva Objetiva Direta Reduzida de Particípio. III- Reduzida: Pensei estar preparado para a prova. Desenvolvida: Pensei que estivesse preparado para a prova. Classificação da oração reduzida: Oração Subordinada Substantiva Objetiva Direta Reduzida de Infinitivo.É CORRETO o que se afirma em:","opcoes":["I e III apenas.","II apenas.","I e II apenas.","III apenas.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>III apenas.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4377,"enunciado":"Julgue o item a seguir.Na frase \"Ele me perguntou se eu iria ao cinema\", a oração \"se eu iria ao cinema\" é uma oração subordinada adverbial causal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4378,"enunciado":"Analise o trecho abaixo:A expressão “Tomou doril a dor sumiu” possui uma relação de ____________ entre as orações. O sentindo interpretativo que a oração ___________ ___________ possui em relação à oração principal é de ______________.As lacunas podem ser CORRETAMENTE preenchidas pela sequência:","opcoes":["subordinação – subordinada – reduzida – consequência.","coordenação – subordinada – adjetiva – explicativa.","coordenação – coordenada – assindética – consequência.","coordenação – coordenada – sindética – consequência.","subordinação – coordenada – sindética – explicativa."],"correta":2,"explicacao":"Gabarito: <strong>coordenação – coordenada – assindética – consequência.</strong>.","banca":"UFRR","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4379,"enunciado":"Assinale a alternativa que indica corretamente a função sintática da oração sublinhada no trecho a seguir, retirado do texto:“É bom que agora há o recurso de editar os textos”.","opcoes":["Objeto direto.","Objeto indireto.","Predicativo do sujeito.","Sujeito.","Complemento nominal."],"correta":3,"explicacao":"Gabarito: <strong>Sujeito.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4381,"enunciado":"A oração destacada em “As TVs que têm processador IA de última geração proporcionam uma experiência incrível aos usuários”:","opcoes":["Oração subordinada adjetiva explicativa.","Oração subordinada adjetiva restritiva.","Oração subordinada substantiva predicativa.","Oração subordinada substantiva subjetiva.","Oração subordinada substantiva apositiva."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada adjetiva restritiva.</strong>.","banca":"Instituto Tupy","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4382,"enunciado":"Julgue o item que se segue. Nas orações subordinadas substantivas, a função sintática pode variar, assumindo papéis como sujeito, objeto direto, objeto indireto, complemento nominal, predicativo e aposto. Por exemplo, na frase \"É necessário que você estude\", a oração subordinada exerce a função de sujeito.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4383,"enunciado":"No Brasil, os sinais de trânsito integram o Código de Trânsito Brasileiro (CTB) a fim de condicionar civilizadamente à atitude ética no trânsito, com base em regras convencionadas na forma de lei. A oração subordinada presente no trecho acima classifica-se como:","opcoes":["Oração subordinada adverbial causal reduzida de infinitivo.","Oração subordinada adverbial final reduzida de infinitivo.","Oração subordinada adverbial conformativa reduzida de infinitivo.","Oração subordinada substantiva subjetiva reduzida de particípio.","Oração subordinada substantiva objetiva direta reduzida de particípio."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada adverbial final reduzida de infinitivo.</strong>.","banca":"CONSULPAM","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4384,"enunciado":"Julgue o item subsequente. Nas orações subordinadas substantivas, a função sintática pode variar, assumindo papéis como sujeito, objeto direto, objeto indireto, complemento nominal, predicativo e aposto. Por exemplo, na frase \"É necessário que você estude\", a oração subordinada exerce a função de sujeito.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4385,"enunciado":"Sobre esta passagem do 4º parágrafo “No começo do texto eu disse que a maioria dos autores...”, a oração destacada foi classificada corretamente como:","opcoes":["Coordenada sindética proporcional.","Subordinada substantiva objetiva direta.","Coordenada assindética.","Subordinada adverbial concessiva.","Subordinada adjetiva restritiva."],"correta":1,"explicacao":"Gabarito: <strong>Subordinada substantiva objetiva direta.</strong>.","banca":"IVIN","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4386,"enunciado":"No período “Não acho que a lógica é um problema” (4º parágrafo), a oração em destaque é:","opcoes":["Subordinada substantiva predicativa.","Subordinada substantiva completiva nominal.","Subordinada substantiva apositiva.","Subordinada substantiva objetiva direta.","Subordinada substantiva subjetiva."],"correta":3,"explicacao":"Gabarito: <strong>Subordinada substantiva objetiva direta.</strong>.","banca":"IVIN","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4387,"enunciado":"Julgue o item a seguir. Nas orações subordinadas substantivas, a função sintática pode variar, assumindo papéis como sujeito, objeto direto, objeto indireto, complemento nominal, predicativo e aposto. Por exemplo, na frase \"É necessário que você estude\", a oração subordinada exerce a função de sujeito.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4388,"enunciado":"Julgue o item subsequente.Na frase \"O professor pediu que os alunos entregassem os trabalhos na próxima semana\", a oração \"que os alunos entregassem os trabalhos na próxima semana\" exerce a função de objeto direto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4390,"enunciado":"Em “Outro ponto importante nesse sentido é que cada situação envolve sua complexidade” (l. 07), a oração subordinada substantiva exerce a função sintática igual à de qual termo a seguir destacado?","opcoes":["“Vivendo uma lição a cada dia” (l. 09).","“Não é fácil praticar a empatia” (l. 01).","“O que se ganha com esse tal poder da empatia?” (l. 04 e 05).","“Pessoas podem se mostrar mais ou menos empáticas” (l. 07 e 08)."],"correta":1,"explicacao":"Gabarito: <strong>“Não é fácil praticar a empatia” (l. 01).</strong>.","banca":"IMPARH","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4393,"enunciado":"Em \"É incomum QUE EM UMA CRISE SE MODIFIQUE SOMENTE UM ASPECTO DA VIDA\", a oração QUE EM UMA CRISE SE MODIFIQUE SOMENTE UM ASPECTO DA VIDA é classificada sintaticamente como:","opcoes":["Oração Coordenada Sindética Explicativa.","Oração Subordinada Substantiva Objetiva Indireta.","Oração Subordinada Substantiva Subjetiva.","Oração Subordinada Substantiva Objetiva Direta."],"correta":2,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Subjetiva.</strong>.","banca":"ACAFE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4395,"enunciado":"Na frase \"É evidente QUE NÃO BASTA SONHAR PARA CONVERTER-SE EM UM TRIUNFADOR\", a oração \"QUE NÃO BASTA SONHAR PARA CONVERTER-SE EM UM TRIUNFADOR\" é classificada como:","opcoes":["Oração Subordinada Substantiva Objetiva Direta","Oração Coordenativa Sindética Explicativa","Oração Subordinada Adjetiva Restritiva","Oração Subordinada Substantiva Subjetiva"],"correta":3,"explicacao":"Gabarito: <strong>Oração Subordinada Substantiva Subjetiva</strong>.","banca":"ACAFE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4396,"enunciado":"Além disso, embora se especule que a ausência de cauda tenha sido um elemento importante para a locomoção bípede, também é verdade que muitas espécies arbóreas ou escaladoras, a exemplo dos orangotangos, tampouco têm cauda. (L.86-90)Em relação ao período acima, analise as afirmativas a seguir:I. É composto por quatro orações. II. Existe uma oração subordinada substantiva objetiva direta. III. Há uma oração subordinada adverbial.Assinale","opcoes":["se apenas as afirmativas I e II estiverem corretas.","se apenas as afirmativas I e III estiverem corretas.","se apenas as afirmativas II e III estiverem corretas.","se nenhuma afirmativa estiver correta.","se todas as afirmativas estiverem corretas."],"correta":1,"explicacao":"Gabarito: <strong>se apenas as afirmativas I e III estiverem corretas.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4397,"enunciado":"Marque a alternativa em que há um caso de oração subordinada substantiva:","opcoes":["É importante que você se exercite todos os dias.","Os homens que mais se exercitaram passaram no teste.","Ela chorou porque estava decepcionada.","Vamos sair quando a chuva amenizar."],"correta":0,"explicacao":"Gabarito: <strong>É importante que você se exercite todos os dias.</strong>.","banca":"FUNATEC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4398,"enunciado":"A respeito da estrutura sintática dos versos “Eu sei que vou te amar /Eu sei que vou chorar/ Eu sei que vou sofrer”, analise as proposições a seguir:I- Os versos são formados por duas orações subordinadas ligadas pela conjunção “que”.II- Os versos são classificados como períodos compostos por subordinação.III- Os versos não são compostos, sintaticamente, por oração principal, mas por apenas orações coordenadas.IV- Os versos são construídos, linguisticamente, apenas por orações subordinadas adverbiais causais.É CORRETO o que se afirma apenas em:","opcoes":["III e IV.","I e IV.","II e III.","I e II.","II."],"correta":3,"explicacao":"Gabarito: <strong>I e II.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4399,"enunciado":"No trecho “os pesquisadores destacavam a maior autoconsciência que as mulheres têm da sua aparência quando se olham em um espelho” (4º parágrafo), há:","opcoes":["uma oração subordinada","duas orações subordinadas","três orações subordinadas","quatro orações subordinadas"],"correta":1,"explicacao":"Gabarito: <strong>duas orações subordinadas</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4400,"enunciado":"Assinale, a seguir, a alternativa que apresenta um período composto por subordinação e coordenação.","opcoes":["Muitos professores do curso continuam escrevendo artigos para seus alunos!","Estudo hoje com apenas uma gramática específica para concursos","Os resultados foram ótimos, por isso ficamos satisfeitos.","Pedi que todos viessem preparados.","Sei que eles passaram e que se estabeleceram na profissão."],"correta":4,"explicacao":"Gabarito: <strong>Sei que eles passaram e que se estabeleceram na profissão.</strong>.","banca":"APICE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4401,"enunciado":"No período “No entanto, o remoto também exige um alto grau de automotivação e pode ser um desafio para pessoas que têm dificuldade em se comunicar ou ensinar a distância”, as orações sublinhadas são classificadas como subordinadas","opcoes":["adverbiais finais.","adverbiais causais.","substantivas subjetivas.","substantivas objetivas indiretas.","substantivas completivas nominais."],"correta":4,"explicacao":"Gabarito: <strong>substantivas completivas nominais.</strong>.","banca":"COSEAC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4402,"enunciado":"O período “A professora de Meio Ambiente e Filosofia, Elane Carvalho, lembrou que alguns alunos dessas duas turmas de terceiro ano estão fazendo com a Biofábrica um projeto com produção de cartilhas pedagógicas para serem distribuídas como trabalho de conscientização no município” é composto por subordinação, contendo, além da oração principal,","opcoes":["uma oração subordinada substantiva objetiva direta, uma oração subordinada substantiva predicativa e uma oração subordinada adverbial final.","uma oração subordinada substantiva objetiva indireta, uma oração subordinada substantiva predicativa e uma oração subordinada adjetiva restritiva.","uma oração subordinada substantiva objetiva direta e uma oração subordinada adverbial final.","uma oração subordinada substantiva objetiva direta e uma oração subordinada adjetiva explicativa","uma oração subordinada substantiva objetiva indireta e uma oração subordinada adverbial consecutiva."],"correta":2,"explicacao":"Gabarito: <strong>uma oração subordinada substantiva objetiva direta e uma oração subordinada adverbial final.</strong>.","banca":"COSEAC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4403,"enunciado":"A comparação com os gorilas de hoje também faz sentido quando se considera que o macacão parece ter sido estritamente herbívoro. (L.18-20)A terceira oração do período acima se classifica como","opcoes":["subordinada substantiva subjetiva.","subordinada substantiva objetiva direta.","subordinada substantiva predicativa.","subordinada adjetiva restritiva."],"correta":0,"explicacao":"Gabarito: <strong>subordinada substantiva subjetiva.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4405,"enunciado":"O período composto por subordinação caracteriza-se pela formação de orações que exercem uma função sintática sobre outra oração, denominada principal.Há de se considerar que, na passagem “Mas isso não impediu que se espalhasse, inquestionada, por todos os cantos.”, há uma oração subordinada classificada corretamente como","opcoes":["adjetiva restritiva.","adjetiva explicativa.","substantiva subjetiva.","substantiva objetiva direta."],"correta":3,"explicacao":"Gabarito: <strong>substantiva objetiva direta.</strong>.","banca":"FCM","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4406,"enunciado":"Em “É previsto que o projeto esteja disponível até o fim do ano no site da Lenovo” (8º parágrafo), a oração destacada é classificada como subordinada:","opcoes":["substantiva objetiva direta","substantiva subjetiva","adjetiva explicativa","adjetiva restritiva"],"correta":1,"explicacao":"Gabarito: <strong>substantiva subjetiva</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4407,"enunciado":"“Ele fica perplexo com isso, mas depois descobre que o verdadeiro amor não vai parar.” 3º§A oração sublinhada é classificada corretamente como:","opcoes":["oração coordenada sindética conclusiva.","oração subordinada adverbial condicional.","oração subordinada adjetiva restritiva.","oração subordinada substantiva objetiva direta.","oração subordinada substantiva completiva nominal."],"correta":3,"explicacao":"Gabarito: <strong>oração subordinada substantiva objetiva direta.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4408,"enunciado":"Em “É importante recapitular um pouco a história dos direitos autorais” (2º parágrafo), há um período:","opcoes":["simples","composto por coordenação","composto por subordinação","composto por coordenação e por subordinação"],"correta":2,"explicacao":"Gabarito: <strong>composto por subordinação</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4409,"enunciado":"No período “Não era proibido que as pessoas se manifestassem”, a oração subordinada substantiva é","opcoes":["objetiva direta.","subjetiva.","objetiva indireta.","predicativa."],"correta":1,"explicacao":"Gabarito: <strong>subjetiva.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4410,"enunciado":"Relacione as colunas e assinale a alternativa correta:( 1 ) Tenho o desejo de que tudo se resolva da melhor maneira.( 2 ) Eu acho que não precisamos brigar por isso.( 3 ) O celular que comprei no ano passado já está ultrapassado.( 4 ) Este computador, que era da minha mãe, já está com problemas.( ) Oração Subordinada Adjetiva Restritiva( ) Oração Subordinada Substantiva Completiva Nominal( ) Oração Subordinada Substantiva Objetiva Direta( ) Oração Subordinada Adjetiva Explicativa","opcoes":["1 – 3 – 4 – 2","4 – 3 – 2 – 1","1 – 2 – 3 – 4","3 – 1 – 2 – 4"],"correta":3,"explicacao":"Gabarito: <strong>3 – 1 – 2 – 4</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4411,"enunciado":"Em “Mas os ativistas do clima temem que o aumento das exportações de gás natural liquefeito piore o aquecimento global” (1.º parágrafo), a oração destacada é classificada como subordinada substantiva:","opcoes":["subjetiva","apositiva","predicativa","objetiva direta"],"correta":3,"explicacao":"Gabarito: <strong>objetiva direta</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4412,"enunciado":"Além disso, os edifícios altos, geralmente com uma moldura mais fina do que os edifícios mais largos e de altura média, projetarão uma sombra mais estreita, que se move mais rapidamente ao longo do dia. (L.43-46)A oração sublinhada no período acima se classifica como:","opcoes":["Subordinada substantiva apositiva.","Subordinada substantiva predicativa.","Coordenada sindética explicativa.","Subordinada adjetiva restritiva.","Subordinada adjetiva explicativa."],"correta":4,"explicacao":"Gabarito: <strong>Subordinada adjetiva explicativa.</strong>.","banca":"FDC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4413,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item. No quarto parágrafo, a oração “que aproveitou 100% do evento” classifica‑se como substantiva.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4414,"enunciado":"Em “Cientistas nomearam a nova espécie e passaram anos tentando adivinhar que tipo de réptil era” (3º parágrafo), a oração subordinada destacada pode ser classificada como:","opcoes":["substantiva objetiva direta","substantiva predicativa","adjetiva explicativa","adjetiva restritiva"],"correta":0,"explicacao":"Gabarito: <strong>substantiva objetiva direta</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4415,"enunciado":"Em “Os autores do estudo explicam que o hormônio do crescimento é secretado pela hipófise...” (6º parágrafo), o segmento oracional destacado foi corretamente classificado na opção:","opcoes":["Oração subordinada substantiva objetiva direta.","Oração subordinada adverbial concessiva.","Oração subordinada adverbial consecutiva.","Oração subordinada adjetiva explicativa.","Oração subordinada adjetiva restritiva."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"IVIN","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4416,"enunciado":"Assinale a alternativa que represente o padrão de subordinação:Oração principal + Oração subordinada substantiva objetiva direta","opcoes":["“(...) nossa qualidade de vida e uma verdadeira fonte de felicidade (...)”.","“(...) ela tem a mais gloriosa capacidade (...)”.","“(...) ele descobriu que as pessoas em geral conseguem manter cerca de 150 conexões sociais (...)”.","“Por isso, desenvolver relacionamentos de apoio (...)”.","“Se usarmos tecnologia com sabedoria (...)”."],"correta":2,"explicacao":"Gabarito: <strong>“(...) ele descobriu que as pessoas em geral conseguem manter cerca de 150 conexões sociais (...)”.</strong>.","banca":"IBFC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4417,"enunciado":"No período “Pelo visto, eu estava lhe pedindo que chamasse a Banda do Corpo de Bombeiros para dar um concerto particular de marchas e dobrados na redação”, a oração destacada exerce, em relação à oração anterior, a função sintática de","opcoes":["objeto direto.","objeto indireto.","predicativo.","sujeito."],"correta":0,"explicacao":"Gabarito: <strong>objeto direto.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4419,"enunciado":"É triste que não haja cientistas suficientes querendo se tornar políticos. (L.102-103) A oração sublinhada no período acima se classifica como","opcoes":["subordinada substantiva predicativa.","subordinada substantiva subjetiva.","subordinada adjetiva restritiva.","subordinada substantiva apositiva."],"correta":1,"explicacao":"Gabarito: <strong>subordinada substantiva subjetiva.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4422,"enunciado":"Em “A volta às aulas traz novidades: o uso do telefone está proibido”, em relação à primeira, a segunda oração é classificada, pela gramática normativa, como subordinada substantiva","opcoes":["completiva nominal.","apositiva.","predicativa.","objetiva direta."],"correta":1,"explicacao":"Gabarito: <strong>apositiva.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4425,"enunciado":"Descobriu-se que as imagens anteriores de Netuno foram melhoradas para mostrar detalhes da atmosfera do planeta, o que alterou a sua verdadeira cor. (L.10-12)A oração sublinhada no período acima se classifica como","opcoes":["subordinada substantiva objetiva direta.","subordinada substantiva subjetiva.","subordinada substantiva predicativa.","subordinada adjetiva restritiva."],"correta":1,"explicacao":"Gabarito: <strong>subordinada substantiva subjetiva.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4427,"enunciado":"Leia com atenção as alternativas abaixo e assinale aquela que possui uma oração subordinada substantiva completiva nominal:","opcoes":["Quero que você me ligue depois da aula.","Desejo que todos possam encontrar um amor um dia.","Há necessidade de que Gabriel se esforce mais pela equipe.","Todos pensaram a mesma coisa: que ele estava com a razão."],"correta":2,"explicacao":"Gabarito: <strong>Há necessidade de que Gabriel se esforce mais pela equipe.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4430,"enunciado":"“Ela informa que fatores genéticos e vivências precoces, como traumas na infância, favorecem o desenvolvimento do distúrbio.” (3º§) A oração sublinhada é classificada como oração subordinada substantiva","opcoes":["subjetiva.","objetiva direta.","objetiva indireta.","completiva nominal."],"correta":1,"explicacao":"Gabarito: <strong>objetiva direta.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4431,"enunciado":"Tendo o texto 10A1 como referência, assinale a opção correta no que diz respeito à classificação da oração “que um idioma é uma coisa viva e pulsante” (segundo período do segundo parágrafo).","opcoes":["subordinada adverbial final","subordinada adjetiva restritiva","subordinada substantiva objetiva direta","coordenada sindética explicativa","subordinada substantiva predicativa"],"correta":2,"explicacao":"Gabarito: <strong>subordinada substantiva objetiva direta</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4435,"enunciado":"“Espero que ela possa ajudar” (4º quadrinho). A oração destacada funciona como ___________ da oração anterior. A opção que preenche corretamente a lacuna é:","opcoes":["objeto indireto.","objeto direto.","sujeito.","aposto."],"correta":1,"explicacao":"Gabarito: <strong>objeto direto.</strong>.","banca":"IPEFAE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4436,"enunciado":"Considerando o texto e os seus aspectos linguísticos, estruturais e de conteúdo, julgue o item. O termo “um trabalho pela regulamentação profissional da categoria” (linha 2 e 3) é uma oração subordinada substantiva objetiva direta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4439,"enunciado":"A oração sublinhada no período abaixo classifica-se como: “Conceição Evaristo me ensinou que os sonhos são águas que correm fora do rio do tempo”.","opcoes":["Coordenada sindética adversativa.","Subordinada substantiva objetiva indireta.","Subordinada substantiva objetiva direta.","Subordinada substantiva predicativa.","Subordinada adverbial causal."],"correta":2,"explicacao":"Gabarito: <strong>Subordinada substantiva objetiva direta.</strong>.","banca":"FAU","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4440,"enunciado":"Assinale a alternativa que contém uma oração subordina substantiva subjetiva.","opcoes":["É fundamental que você chegue antes à prefeitura.","Nosso desejo é que ela vença a corrida.","Temos fé de que a humanidade proteja o meio ambiente.","Desejo que vocês estejam prontos.","Todos pensam a mesma coisa: que eu estou errado."],"correta":0,"explicacao":"Gabarito: <strong>É fundamental que você chegue antes à prefeitura.</strong>.","banca":"MSConcursos","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4442,"enunciado":"Com eles, será possível ganhar ainda maior precisão em esforços de mitigação dos efeitos do aquecimento global... (linhas 23 e 24)A segunda oração do segmento acima se classifica como","opcoes":["principal.","subordinada substantiva predicativa.","subordinada adverbial final.","subordinada substantiva subjetiva.","subordinada substantiva completiva nominal."],"correta":3,"explicacao":"Gabarito: <strong>subordinada substantiva subjetiva.</strong>.","banca":"IDIB","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4443,"enunciado":"No trecho “De acordo com a Takeda, os estudos clínicos da Qdenga tiveram 28 mil participantes, com acompanhamento de mais de quatro anos dos voluntários da última fase do estudo” (8º parágrafo), há:","opcoes":["uma oração absoluta","uma oração coordenada assindética e uma oração assindética","uma oração subordinada adverbial conformativa e uma oração principal","uma oração subordinada adverbial conformativa, uma oração principal e uma coordenada sindética aditiva"],"correta":0,"explicacao":"Gabarito: <strong>uma oração absoluta</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4445,"enunciado":"Sobre o poema \"Do bem e do mal\" autoria de Mário Quintana, marque a alternativa com análise INCORRETA: Do bem e do mal Todos têm seu encanto: os santos e os corruptos. Não há coisa na vida inteiramente má. Tu dizes que a verdade produz frutos... Já viste as flores que a mentira dá? (Mário Quintana).","opcoes":["No período composto: \"Tu dizes que a verdade produz frutos\" − identificamos: sujeito simples representado por pronome pessoal do caso reto; conjunção subordinativa integral \"que\" e oração subordinada substantiva objetiva direta.","O núcleo do predicado da oração: \"Não há coisa na vida inteiramente má\" − está representado por um verbo de segunda conjugação, na terceira pessoa do presente do modo indicativo seguido de objeto direto representado por um substantivo.","O título do poema contém termos oxítonos que exemplificam uma antítese e contrações prepositivas impostas pela regência nominal.","A oração: \"Todos têm seu encanto\" está escrita com os termos essenciais na ordem direta e apresenta complemento verbal direto.","O verso: \"Já viste as flores que a mentira dá?\" − temos um pronome relativo posposto ao núcleo do objeto direto do verbo \"dá\"."],"correta":2,"explicacao":"Gabarito: <strong>O título do poema contém termos oxítonos que exemplificam uma antítese e contrações prepositivas impostas pela regência nominal.</strong>.","banca":"Unesc","ano":2023,"temas_relacionados":["analiseSintatica","oxitonas"]},{"id":4446,"enunciado":"No trecho \"Entre os médicos, não existe a cultura de solicitar exame de rastreamento de câncer de pulmão no Brasil\" (7° parágrafo), a oração destacada é substantiva:","opcoes":["subjetiva","apositiva","objetiva indireta","completiva nominal"],"correta":3,"explicacao":"Gabarito: <strong>completiva nominal</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4448,"enunciado":"Leia as alternativas com atenção e assinale em qual delas há uma oração subordinada substantiva objetiva indireta:","opcoes":["Os jovens de hoje tem necessidade de que os incentivem.","Recordo-me de que eles se enfrentaram.","Meu maior desejo é que me dessem o dia de folga no meu aniversário.","Todos nós desejamos que a sua viagem seja ótima."],"correta":1,"explicacao":"Gabarito: <strong>Recordo-me de que eles se enfrentaram.</strong>.","banca":"AMEOSC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4449,"enunciado":"A fim de evitar o desvio de sintaxe, que foi apresentado na questão anterior, o personagem poderia ter optado pelo uso da preposição (de). Assim, o trecho poderia ser reescrito de forma precisa“Você não gostaria de que fosse sempre assim?”Nesse contexto, quanto à classificação sintática da oração secundária:","opcoes":["Trata-se de uma Oração Subordinada Substantiva Objetiva Direta.","Trata-se de uma Oração Subordinada Substantiva Completiva Nominal.","Trata-se de uma Oração Subordinada Substantiva Predicativa.","Trata-se de uma Oração Subordinada Substantiva Objetiva Indireta.","Trata-se de uma Oração Subordinada Substantiva Apositiva."],"correta":3,"explicacao":"Gabarito: <strong>Trata-se de uma Oração Subordinada Substantiva Objetiva Indireta.</strong>.","banca":"FACET Concursos","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4450,"enunciado":"Julgue o item a seguir. Em “Nunca se soube como ele morreu”, a primeira oração está na voz passiva, e a segunda é Subordinada Substantiva Subjetiva.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4451,"enunciado":"No período: “Os professores desempenham um papel vital nas nossas sociedades, ainda assim a profissão enfrenta uma enorme crise de vocações”, a oração destacada pode ser classificada como:","opcoes":["oração principal.","oração subordinada substantiva.","oração subordinada adverbial.","oração adjetiva explicativa."],"correta":0,"explicacao":"Gabarito: <strong>oração principal.</strong>.","banca":"Itame","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4452,"enunciado":"No período a seguir, a oração em destaque se classifica como:Uma coisa lhe posso garantir: que a recompensa valerá a pena.","opcoes":["Subordinada substantiva predicativa.","Subordinada substantiva objetiva direta.","Subordinada substantiva subjetiva.","Subordinada substantiva apositiva."],"correta":3,"explicacao":"Gabarito: <strong>Subordinada substantiva apositiva.</strong>.","banca":"Itame","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4455,"enunciado":"No trecho “Passamos a depender de curadores ou de uma curadoria própria, que supõe o desenvolvimento de diferentes habilidades”, o elemento destacado introduz uma oração subordinada:","opcoes":["adjetiva restritiva","adjetiva explicativa","substantiva objetiva direta","substantiva completiva nominal"],"correta":1,"explicacao":"Gabarito: <strong>adjetiva explicativa</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4456,"enunciado":"No que tange à construção de períodos, valendo-se de orações coordenadas e subordinadas, avalie as assertivas que seguem a respeito do período “Diante desse cenário, é essencial que o professor saiba acolher e orientar as angústias e dúvidas comuns na adolescência, que podem ser ampliadas pelo uso indevido da tecnologia”, valendo-se do que preconiza Cegalla em relação à construção dos períodos compostos:I. Identifica-se no período a ocorrência de oração subordinada substantiva subjetiva.II. A oração assinalada em negrito é classificada como oração subordinada adjetiva explicativa.III. O período é composto, dada a ocorrência de três tipos de orações: coordenadas, principais e subordinadas.Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4457,"enunciado":"Considerando a forma e o conteúdo do texto, julgue o item.O trecho “recorrer a fontes seguras e confiáveis de organizações comprometidas com a causa” (linhas de 33 a 35) deve ser classificado como uma oração subordinada substantiva objetiva direta reduzida de infinitivo.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4458,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. A oração “é muito fácil encontrar opções de leitura nesse formato” (linhas 4 e 5) deve ser classificada como subordinada substantiva subjetiva reduzida de infinitivo.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4459,"enunciado":"Com base na leitura do texto e em seus aspectos linguísticos, de forma e de conteúdo, julgue o item a seguir.A oração “que estiverem em dia com suas anuidades ou honrando parcelamento das mesmas” (linhas 28 e 29) deve ser classificada como subordinada substantiva objetiva direta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4460,"enunciado":"Julgue o item a seguir. Ao analisar a oração \"Que é demasiada metafísica para um só tenor, não há dúvida.\", temos que \"Que é demasiada metafísica para um só tenor\" é a oração subordinada substantiva objetiva direta e funciona como sujeito da oração principal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4461,"enunciado":"Em “Sabemos — e eles, mais ainda — que são os donos da cidade.” (7º parágrafo), a correta classificação da oração subordinada destacada é:","opcoes":["Adverbial condicional.","Adjetiva restritiva.","Substantiva completiva nominal.","Adverbial concessiva.","Substantiva objetiva direta."],"correta":4,"explicacao":"Gabarito: <strong>Substantiva objetiva direta.</strong>.","banca":"IVIN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4462,"enunciado":"No período “Ao conviver com os bem mais jovens, com aqueles que se tornaram adultos há pouco e com aqueles que estão tateando para virar gente grande, percebo que estamos diante da geração mais preparada – e, ao mesmo tempo, da mais despreparada.”, a palavra “que” ocorre três vezes, sendo que, na primeira ocorrência, ela é um pronome relativo, introduzindo uma oração subordinada adjetiva","opcoes":["explicativa; na segunda ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva subjetiva; e na terceira ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva subjetiva.","restritiva; na segunda ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva completiva nominal; e na terceira ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva subjetiva.","restritiva; na segunda ocorrência, a palavra “que” é um pronome relativo, introduzindo uma oração subordinada adjetiva explicativa; e na terceira ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta.","restritiva; na segunda ocorrência, a palavra “que” é um pronome relativo, introduzindo uma oração subordinada adjetiva restritiva; e na terceira ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta."],"correta":3,"explicacao":"Gabarito: <strong>restritiva; na segunda ocorrência, a palavra “que” é um pronome relativo, introduzindo uma oração subordinada adjetiva restritiva; e na terceira ocorrência, a palavra “que” é uma conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4463,"enunciado":"Observe o trecho: “Muitas pessoas visitam o lugar para observar as estrelas...” e analise as afirmativas abaixo em relação à sintaxe.I. Muitas pessoas: sujeito composto. II. Para observar as estrelas: oração subordinada adverbial final. III. O lugar: objeto direto.Assinale a alternativa correta.","opcoes":["II e III estão corretas.","I, II e III estão corretas.","I e III estão corretas.","Apenas II está correta."],"correta":0,"explicacao":"Gabarito: <strong>II e III estão corretas.</strong>.","banca":"IBFC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4464,"enunciado":"“Quando questionados sobre a participação dos estudantes, a percepção dos professores é a de que apenas três de cada dez alunos com deficiência se envolvem efetivamente com as atividades em aula.” (4º§) Considerando trecho, analise as afirmativas a seguir.I. A oração “Quando questionados sobre a participação dos estudantes” é uma oração subordinada adverbial temporal.II. A oração “a percepção dos professores é” é uma oração coordenada explicativa.III. “a de que apenas três de cada dez alunos com deficiência se envolvem efetivamente com as atividades em aula” é uma oração subordinada substantiva predicativa.Está correto o que se afirma em","opcoes":["I, II e III.","I e II, apenas.","I e III, apenas.","II e III, apenas."],"correta":2,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4465,"enunciado":"Nos anos 1930, percebendo a relevância do personagem, a MGM decidiu lançar sua própria adaptação cinematográfica da obra de Leblanc.Assinale a alternativa CORRETA sobre a oração sublinhada no período acima.","opcoes":["Exerce a função sintática de um complemento nominal.","Exerce a função sintática de um objeto direto.","Exerce a função sintática de um objeto indireto.","Não exerce função sintática."],"correta":1,"explicacao":"Gabarito: <strong>Exerce a função sintática de um objeto direto.</strong>.","banca":"CONSULPAM","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4468,"enunciado":"A música Sutilmente, composta por Samuel Rosa e José Fernando Gomes Reis, traz, em uma de suas estrofes, o seguinte período: (...)Mas quando eu estiver mortoSuplico que não me mate, nãoDentro de tiDentro de ti(...) Sobre a classificação da oração destacada, assinale a correta.","opcoes":["Trata-se de uma oração subordinada adjetiva restritiva.","É uma oração subordinada objetiva direta.","É uma oração subordinada adverbial causal.","Trata-se de uma oração coordenada sindética aditiva."],"correta":1,"explicacao":"Gabarito: <strong>É uma oração subordinada objetiva direta.</strong>.","banca":"EPL Concursos","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4470,"enunciado":"Partindo da definição de que orações subordinadas são aquelas que dependem de outras orações no período e que não têm sentido completo isoladas, aponte a alternativa em que há uma oração subordinada destacada cuja classificação se encontra correta entre parênteses.","opcoes":["“Depois perder o barraco, que estava onde não podia estar.” (subordinada adverbial causal)","“Parece que a ideia era lhe dar uma terrinha”. (subordinada subjetiva completiva nominal)","“Concluiu que era provocação.” (subordinada substantiva objetiva direta)","“Aí ouviu que a reforma agrária não era bem assim.” (subordinada substantiva predicativa)"],"correta":2,"explicacao":"Gabarito: <strong>“Concluiu que era provocação.” (subordinada substantiva objetiva direta)</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4472,"enunciado":"Assinale a única alternativa em que ocorre pelo menos uma oração subordinada substantiva.","opcoes":["Quando os retirantes chegaram, foram bem acolhidos pelos responsáveis pelo projeto.","A produção, que custou mais de 100 milhões, arrecadou o triplo disso.","É certo que todos gostaram daquela obra do famoso arquiteto.","Ele fez tudo isso para que conquistasse o coração da garota."],"correta":2,"explicacao":"Gabarito: <strong>É certo que todos gostaram daquela obra do famoso arquiteto.</strong>.","banca":"EPL Concursos","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4474,"enunciado":"Leia a tira com atenção para responder à questão. Fonte: Níquel Náusea – Nem tudo que balança cai. São Paulo: Devir, 2003. p. 12 No primeiro quadrinho, a oração sublinhada SABIA QUE O BEIJA-FLOR BATE A ASA SETENTA VEZES POR SEGUNDO? é corretamente classificada como","opcoes":["oração subordinada substantiva completiva nominal.","oração subordinada substantiva apositiva.","oração subordinada substantiva objetiva direta.","oração subordinada substantiva objetiva indireta."],"correta":2,"explicacao":"Gabarito: <strong>oração subordinada substantiva objetiva direta.</strong>.","banca":"Unoesc","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4476,"enunciado":"Julgue o item subsequente. Uma oração subordinada substantiva pode desempenhar a função de sujeito, objeto direto ou objeto indireto da oração principal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4477,"enunciado":"Julgue o item a seguir.No período “Foi decidido QUE FAREMOS UMA MUDANÇA NO REGIMENTO”, a oração destacada funciona como sujeito da oração principal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4478,"enunciado":"Leia a oração a seguir:“Grande parte dos arqueólogos admite que o amendoim é um alimento básico para algumas culturas”.Assinale a alternativa correta quanto ao fragmento classificado como oração subordinada substantiva objetiva direta","opcoes":["“Grande parte dos arqueólogos admite”.","“que o amendoim é um alimento básico para algumas culturas”.","“Grande parte dos arqueólogos admite que”.","“o amendoim é um alimento básico para algumas culturas”."],"correta":1,"explicacao":"Gabarito: <strong>“que o amendoim é um alimento básico para algumas culturas”.</strong>.","banca":"IBFC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4480,"enunciado":"No período composto “eu disse que falava inglês perfeitamente ”, a oração em destaque se classifica como:","opcoes":["Oração principal.","Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva completiva nominal.","Oração subordinada adjetiva restritiva.","Oração subordinada adverbial causal."],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"CPCON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4481,"enunciado":"Na frase “Esse instituto, fundado com o intuito de reunir informações geográficas e estatísticas brasileiras, possui grande importância em termos governamentais”, destaca-se uma oração:","opcoes":["subordinada substantiva apositiva","subordinada substantiva objetiva indireta","subordinada substantiva completiva nominal","subordinada adjetiva restritiva (reduzida de infinitivo)","subordinada adjetiva explicativa (reduzida de particípio)"],"correta":2,"explicacao":"Gabarito: <strong>subordinada substantiva completiva nominal</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4482,"enunciado":"Um indivíduo comum pode apresentar alguns sintomas que lembram o TDAH, o que torna desafiador 'distinguir entre características semelhantes ao TDAH'. A oração destacada trata-se de uma oração:","opcoes":["coordenada sindética explicativa","subordinada adverbial reduzida de infinitivo","coordenada sindética conclusiva","subordinada substantiva objetiva direta"],"correta":1,"explicacao":"Gabarito: <strong>subordinada adverbial reduzida de infinitivo</strong>.","banca":"AMEOSC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4483,"enunciado":"Dado o período:É essencial que se considere o impacto tanto positivo quanto negativo da tecnologia na educação. Assinale a alternativa que classifica corretamente a oração subordinada do período selecionado:","opcoes":["Oração subordinada substantiva subjetiva.","Oração subordinada substantiva predicativa.","Oração subordinada adverbial causal.","Oração subordinada adverbial consecutiva.","Nenhuma das alternativas anteriores."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada substantiva subjetiva.</strong>.","banca":"FucapSul","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4486,"enunciado":"Assinale a alternativa que apresente a função sintática exercida pela oração subordinada em destaque no período: Os avós da Emily disseram que encontraram a menina desmaiada nos fundos do sítio.","opcoes":["Sujeito.","Objeto Direto.","Predicativo do Sujeito.","Objeto Indireto.","Vocativo."],"correta":1,"explicacao":"Gabarito: <strong>Objeto Direto.</strong>.","banca":"FAU","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4487,"enunciado":"“(...) é importante QUE VOCÊ DÊ O EXEMPLO EM SALA DE AULA.” Assinale a alternativa que indica a classificação CORRETA da oração destacada.","opcoes":["Subordinada substantiva completiva nominal.","Subordinada substantiva apositiva.","Subordinada substantiva objetiva direta.","Subordinada substantiva predicativa.","Subordinada substantiva subjetiva."],"correta":4,"explicacao":"Gabarito: <strong>Subordinada substantiva subjetiva.</strong>.","banca":"FAUEL","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4488,"enunciado":"A internet e os direitos autorais A internet e outras tecnologias mudaram a rotina das famílias, a vida social e até a percepção do mundo. Distâncias parecem menores, a ideia de privacidade está em questão e os relacionamentos amorosos ganharam nova dimensão, de forma tão avassaladora, que quem não participa das redes sociais, em algum momento, pode se sentir excluído ou desinformado. [...] Disponível em: https://oglobo.globo.com/opiniao/internet-nao-pode-atropelar-direitos-autorais. Acesso em: 12 jan. 2023Em “... a ideia de privacidade está em questão e os relacionamentos amorosos ganharam nova dimensão, de forma tão avassaladora, que quem não participa das redes sociais, em algum momento, pode se sentir excluído ou desinformado.”, encontramos, do ponto de vista sintático,","opcoes":["um período simples, com sua oração absoluta.","um período composto por coordenação e subordinação.","um período composto misto, cuja oração principal tem como núcleo o verbo “sentir”","um período composto por coordenação, cuja oração principal tem como núcleo o verbo “ganhar”."],"correta":1,"explicacao":"Gabarito: <strong>um período composto por coordenação e subordinação.</strong>.","banca":"Inovaty","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4490,"enunciado":"Considere as seguintes sentenças:I. Ele se pronunciou sobre o caso. II. Não sabia dizer se estava certo ou errado. III. O projeto terá sucesso, se todos fizerem a sua parte.A palavra “se” atua como conjunção subordinativa apenas na(s) sentença(s):","opcoes":["I e II.","II e III.","I e III.","I.","III."],"correta":1,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4492,"enunciado":"Ler o excerto abaixo e analisar os itens a seguir:Fiquei sabendo que a sogra lia meus textos e que meu livro pousava como predileto na sua cabeceira. Talvez viesse estudando o temperamento do futuro genro.I. As orações “que a sogra lia meus textos” e “que meu livro pousava como predileto na sua cabeceira” funcionam como sujeito da locução verbal “Fiquei sabendo”. São, portanto, orações subordinadas substantivas subjetivas.II. O advérbio “talvez” e o verbo “viesse” conjugado no modo subjuntivo denotam que o conteúdo da oração é hipotético.III. Transpondo-se a última oração do fragmento para a voz passiva, ter-se-ia: “Talvez o temperamento do futuro genro tinha sido estudado”.Está(ão) CORRETO(S):","opcoes":["Somente o item I.","Somente o item II.","Somente os itens I e II.","Somente os itens I e III.","Somente os itens II e III."],"correta":1,"explicacao":"Gabarito: <strong>Somente o item II.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4493,"enunciado":"“Na semana passada, o McDonald’s pediu aos funcionários corporativos, que geralmente trabalham no escritório pelo menos três dias por semana, que fizessem seu serviço de casa” (1º parágrafo). Nesse trecho, as duas partículas destacadas introduzem respectivamente:","opcoes":["uma oração subordinada adjetiva explicativa e uma oração subordinada substantiva objetiva direta","uma oração subordinada adjetiva restritiva e uma oração subordinada substantiva objetiva direta","uma oração subordinada substantiva objetiva direta e uma oração subordinada adjetiva explicativa","uma oração subordinada adjetiva explicativa e uma oração subordinada substantiva completiva nominal"],"correta":0,"explicacao":"Gabarito: <strong>uma oração subordinada adjetiva explicativa e uma oração subordinada substantiva objetiva direta</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4494,"enunciado":"Os usos do termo \"que\" no texto têm diferentes funções gramaticais. Em qual das alternativas a seguir o \"que\" está sendo utilizado para introduzir uma oração subordinada substantiva objetiva direta?","opcoes":["\"Não se trata exatamente de um livro, mas de um estudo, que pode ser baixado de graça na internet.\"","\"Os autores propõem que a busca pela objetividade deixe de ser uma meta declarada do jornalismo.\"","\"Não há indivíduo que não tenha manias, preferências ideológicas e vieses.\"","\"O repórter que se preocupa em buscar o equilíbrio e considera perspectivas diferentes da sua provavelmente fará um trabalho melhor.\"","\"Como comerciantes, que são o grosso dos anunciantes, querem ficar bem com todos, os jornais escaparam um pouco das pressões de seu próprio público.\""],"correta":1,"explicacao":"Gabarito: <strong>\"Os autores propõem que a busca pela objetividade deixe de ser uma meta declarada do jornalismo.\"</strong>.","banca":"NC-UFPR","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4496,"enunciado":"O texto 1 pertence ao gênero textual notícia de divulgação científica. Um reflexo formal desse fato na superfície do texto 1 é a recorrência de:","opcoes":["orações subordinadas substantivas, como em “O grupo que manteve essas células registrou perdas menos significativas [...]”;","pronomes relativos, como em “Todos os testes foram conduzidos em animais que receberam 6-hidroxidopamina [...]”;","sujeitos pospostos ao verbo, como em \"[...] disse a doutoranda Carolina Parga à assessoria de imprensa do ICBUSP”;","apostos explicativos, como em \"São dois genes relacionados à transmissão por dopamina [substância que influencia nossas emoções, aprendizado e locomoção, além de outras funções] [...]”;","verbos flexionados no gerúndio, como em “[...] mas sendo mitigadas pela micróglia e outros mecanismos\"."],"correta":3,"explicacao":"Gabarito: <strong>apostos explicativos, como em \"São dois genes relacionados à transmissão por dopamina [substância que influencia nossas emoções, aprendizado e locomoção, além de outras funções] [...]”;</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4497,"enunciado":"Assinale a alternativa que contém período com construção semelhante e mesma classificação da oração destacada.“(...) Na sola se desenhava a curva graciosa da planta sutil, que só nas extremidades beijava o chão”.","opcoes":["Como admitir que um príncipe da moda não aproveitasse a aventura do carro(...)? - Oração subordinada substantiva objetiva direta","Eram sobretudo os debuxos suaves, as ondulações voluptuosas que tinham deixado na pelica os contornos do pezinho desconhecido. - Oração subordinada adjetiva restritiva","Mas aconchega-se mais ao solo, de que recebe toda a nutrição. - Oração subordinada adjetiva restritiva","Sondou o interior da concha, que servira de regaço ao feiticeiro pezinho. - Oração subordinada adjetiva explicativa","De repente uma ideia perpassou no espírito do moço que o fez estremecer. - Oração subordinada adjetiva explicativa"],"correta":3,"explicacao":"Gabarito: <strong>Sondou o interior da concha, que servira de regaço ao feiticeiro pezinho. - Oração subordinada adjetiva explicativa</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4498,"enunciado":"“Examinou novamente a obra-prima, voltou-a de todos os lados, apalpou docemente o salto e o bico, dobrou a orla da haste, sondou o interior da concha”. A relação presente entre as orações do período destacado acima, corresponde a","opcoes":["coordenação sindética.","subordinação adjetiva.","coordenação assindética.","subordinação adverbial.","subordinação substantiva."],"correta":2,"explicacao":"Gabarito: <strong>coordenação assindética.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4499,"enunciado":"Tendo em vista sua relação com o verbo “comentar”, como se classifica sintaticamente o período composto sublinhado no excerto abaixo? “Jim Starlin, criador do personagem Thanos, é um dos nomes mais recentes a entrar na lista de pessoas que gostaram de The Flash – mas ele tem um motivo bastante específico. O quadrinista comentou que a DC fez algo nesse longa que não é costume na Marvel. De acordo com Starlin, a DC acertou ao destacar os criadores dos quadrinhos que inspiraram The Flash no início dos créditos do filme. [...]”ALMEIDA, Saori. Criador de Thanos elogia The Flash por fazer algo que Marvel não faz. Jovem Nerd, 12 de junho de 2023. Disponível em: https://jovemnerd.com.br/nerdbunker/criador-thanos-elogia-the-flashpor-fazer-o-que-marvel-nao-faz/. Acesso em: 16 jun. 2023.","opcoes":["Oração subordinada substantiva subjetiva","Oração subordinada substantiva objetiva direta","Oração subordinada substantiva apositiva","Oração subordinada adverbial causal","Oração subordinada adverbial consecutiva"],"correta":1,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta</strong>.","banca":"IBADE","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4500,"enunciado":"Julgue o item a seguir, no que diz respeito à sintaxe de orações e períodos no texto 8A1-I. No segundo período do primeiro parágrafo, o vocábulo “que” introduz uma oração subordinada substantiva objetiva direta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4504,"enunciado":"Sobre a classificação da oração sublinhada no fragmento “Por meio de seus conteúdos, seus rituais, sua disciplina e sua moral, esperava-se que a escola tradicional formasse novas disposições nos indivíduos, que, embora não diminuíssem as disposições familiares e comunitárias de origem, deveriam dotar os estudantes de relativa autonomia quanto a novos caminhos e decisões.”, assinalar a alternativa CORRETA:","opcoes":["Oração subordinada substantiva objetiva direta.","Oração subordinada adjetiva restritiva.","Oração subordinada adverbial concessiva.","Oração subordinada adverbial consecutiva."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada adverbial concessiva.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4505,"enunciado":"Quatro alternativas a seguir contêm orações destacadas que desempenham a mesma função. Assinale a que não exerce a mesma função que as demais.","opcoes":["A verdade é que você deve aprender português.","É fundamental que você aprenda português.","Está decidido que a prefeitura terá programa de reforço escolar.","Consta que as aulas de reforço escolar já começaram.","Parece que o professor mudou seu método e sua técnica de ensino."],"correta":0,"explicacao":"Gabarito: <strong>A verdade é que você deve aprender português.</strong>.","banca":"CETREDE","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4506,"enunciado":"Analise as seguintes orações: I. “Fui crescendo; e derrubei telhados com a cabeça” (linhas 11-12). II. “desde que eu era muito pequena, os livros me deram casa e comida” (linhas 01-02) III. “Foi assim que, devagarinho, me habituei com essa troca tão gostosa que no meu jeito de ver as coisas é a troca da própria vida” (linhas 22-24) São orações subordinadas as contidas em","opcoes":["I e II apenas.","I e III apenas.","II e III apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>II e III apenas.</strong>.","banca":"UECE-CEV","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4507,"enunciado":"Acerca da estrutura e do conteúdo do texto, julgue o item. O trecho “de que essas mesmas ordens corporificavam algum princípio absoluto de verdade ou beleza” (linhas de 5 a 7) exerce a função sintática de complemento nominal do núcleo “persuadido” (linha 5), na forma de uma oração subordinada.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4508,"enunciado":"A opção que contém uma oração subordinada substantiva objetiva direta é:","opcoes":["“Eles descobriram que um dos sensores de estresse, IRE1, era significativamente mais ativo em vermes jovens...” (7º parágrafo)","“...os cientistas induziram em vermes da espécie Caenorhabditis elegans...” (6º parágrafo)","“O que acontece é que as células produzem uma resposta ao estresse...” (5º parágrafo)","“...o que estendeu sua vida útil em comparação com vermes alimentados com uma dieta normal.” (2º parágrafo)","“O experimento foi conduzido em algumas espécies de vermes. “(1º parágrafo)"],"correta":0,"explicacao":"Gabarito: <strong>“Eles descobriram que um dos sensores de estresse, IRE1, era significativamente mais ativo em vermes jovens...” (7º parágrafo)</strong>.","banca":"IVIN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4509,"enunciado":"“O problema é que os outros 2 pacientes do estudo não mostraram o mesmo aumento nos batimentos cardíacos...” (7º parágrafo), a correta classificação da oração destacada é:","opcoes":["Oração subordinada substantiva subjetiva.","Oração subordinada adjetiva restritiva.","Oração subordinada substantiva predicativa.","Oração subordinada adverbial concessiva.","Oração subordinada adverbial explicativa."],"correta":2,"explicacao":"Gabarito: <strong>Oração subordinada substantiva predicativa.</strong>.","banca":"IVIN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4510,"enunciado":"Sintaticamente, analise a oração: “É importante que o trabalho em sala de aula se organize”. Assinale a alternativa correta.","opcoes":["Oração subordinada substantiva subjetiva","Oração subordinada substantiva objetiva direta","Oração subordinada substantiva objetiva indireta","Oração coordenada assindética"],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada substantiva subjetiva</strong>.","banca":"IBFC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4511,"enunciado":"Analise: “Avancei lentamente até o bueiro, sentei-me.” (Graciliano Ramos) A oração acima pode ser classificada como:","opcoes":["Oração Coordenada Assindética","Oração Coordenada Sindética","Oração Subordinada","Não é possível classificar a oração."],"correta":0,"explicacao":"Gabarito: <strong>Oração Coordenada Assindética</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4512,"enunciado":"Relacione as colunas: (1 ) Oração Subordinada Substantiva Subjetiva ( 2 ) Oração Subordinada Substantiva Predicativa ( 3 ) Oração Subordinada Substantiva Completiva Nominal ( ) Temos fé de que a humanidade viverá em paz. ( ) É fundamental que você chegue cedo. ( ) Nosso desejo é que ela passe no vestibular.","opcoes":["1 – 2 – 3","3 – 2 – 1","2 – 3 – 1","3 – 1 – 2"],"correta":3,"explicacao":"Gabarito: <strong>3 – 1 – 2</strong>.","banca":"Prefeitura de Bombinhas - SC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4513,"enunciado":"Assinale a alternativa que indica o número correto de orações que compõem o período a seguir: “Nada adianta fazermos das nossas casas – corpo e residência – lugares belos para se fotografar, mas que dão a impressão de não haver nenhum morador dentro”.","opcoes":["2.","3.","4.","5.","6."],"correta":3,"explicacao":"Gabarito: <strong>5.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4515,"enunciado":"Junto à moda da harmonização facial, tem surgido resultados nas redes sociais nada satisfatórios. Queixos pontudos, faces largas e quadradas, nariz desproporcional… Afinal, qual é o maior erro que os profissionais têm cometido nos procedimentos estéticos? Disponível em: <https://veja.abril.com.br/coluna/veja-gnte/o-maior-erro-que-se-comete-na-harmonização-facial/>. Acesso em: 12 mar.2023.Em: “Afinal, qual é o maior erro que os profissionais têm cometido nos procedimentos estéticos?\", a oração sublinhada","opcoes":["restringe o sentido do substantivo “erro”, por isso é uma oração subordinada adjetiva restritiva.","explica o sentido do substantivo “erro”, por isso é uma oração subordinada adjetiva explicativa.","está intercalada, por isso apresenta função de aposto, explicando apenas o substantivo “erro”.","completa o substantivo “erro”, por isso é uma oração subordinada substantiva completiva nominal.","completa o verbo da oração anterior, por meio de uma preposição, por isso é uma oração subordinada substantiva objetiva indireta."],"correta":0,"explicacao":"Gabarito: <strong>restringe o sentido do substantivo “erro”, por isso é uma oração subordinada adjetiva restritiva.</strong>.","banca":"FUNDEPES","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4516,"enunciado":"A oração “que discuto aqui a experiência de nos descobrir sem casa” (linha 16) é subordinada à oração “é como privilegiada” (linhas 15 e 16).\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4517,"enunciado":"A função sintática de um termo pode variar dependendo do tipo de oração em que ele se encontra. Por exemplo, em uma oração subordinada substantiva, um termo que seria um objeto direto em uma oração principal pode assumir a função de sujeito.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4520,"enunciado":"Releia o período observando sua organização sintática. “A fotografia mostra que estamos muito bem no atacado, acima da média mundial em alguns recortes.” A oração subordinada apresenta função sintática de","opcoes":["adjunto adnominal do substantivo \"fotografia\"","adjunto adverbial do verbo \"estamos\".","aposto que explica os adjuntos adverbiais \"muito\"e \"bem\".","complemento da forma verbal \"mostra\"."],"correta":3,"explicacao":"Gabarito: <strong>complemento da forma verbal \"mostra\".</strong>.","banca":"Prefeitura de Iguatu - CE","ano":2023,"temas_relacionados":["analiseSintatica","ortografia"]},{"id":4521,"enunciado":"O ISS (Instituto Saúde e Sustentabilidade) vem revelando há muito tempo que 4.700 pessoas morrem por doenças respiratórias na cidade de São Paulo a cada ano. (L.20-22) A respeito do período acima, analise as afirmativas a seguir:I. O período é composto por quatro orações. II. O período é composto por coordenação e subordinação. III. Nele, há um exemplo de objeto indireto.Assinale","opcoes":["se apenas as afirmativas I e II estiverem corretas.","se apenas as afirmativas I e III estiverem corretas.","se apenas as afirmativas II e III estiverem corretas.","se nenhuma afirmativa estiver correta.","se todas as afirmativas estiverem corretas."],"correta":3,"explicacao":"Gabarito: <strong>se nenhuma afirmativa estiver correta.</strong>.","banca":"Instituto Access","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4522,"enunciado":"Susto, angústia, tosse, tosse, tosse, consternação familiar e, mais uma vez, a constatação de que não podemos adiar (1) o que desejamos na vida (2). (L.17-19)As orações (1) e (2) do período acima se classificam, respectivamente, como","opcoes":["subordinada substantiva completiva nominal e subordinada adjetiva restritiva.","subordinada adjetiva restritiva e subordinada adjetiva restritiva.","subordinada substantiva objetiva indireta e subordinada substantiva objetiva direta.","subordinada substantiva completiva nominal e subordinada substantiva objetivo direta.","subordinada adjetiva restritiva e subordinada adjetiva explicativa."],"correta":0,"explicacao":"Gabarito: <strong>subordinada substantiva completiva nominal e subordinada adjetiva restritiva.</strong>.","banca":"Instituto Access","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4523,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. A oração “E que o cérebro possui uma malha de circuitos, a chamada rede de modo padrão” (linhas 27 e 28) é classificada como subordinada substantiva objetiva direta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4524,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. A oração “O mais provável é que a felicidade e a infelicidade estejam relacionadas a mecanismos cerebrais mais complexos do que se imagina” (linhas de 22 a 24) é classificada como subordinada substantiva predicativa.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4525,"enunciado":"No segundo quadrinho, o período: “Se formos ao deserto, você terá camuflagem de deserto”, a oração em destaque é a","opcoes":["principal.","subordinada adjetiva.","subordinada adverbial.","coordenada assindética.","subordinada substantiva."],"correta":0,"explicacao":"Gabarito: <strong>principal.</strong>.","banca":"FUNDEPES","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4526,"enunciado":"O homem tem o direito fundamental à liberdade, à igualdade e ao desfrute de condições de vida adequadas, em um meio ambiente de qualidade tal que lhe permite levar uma vida digna, gozar de bem-estar e é portador solene de obrigação de proteger e melhorar o meio ambiente, para as gerações presentes e futuras. A esse respeito, as políticas que promovem ou perpetuam o ‘apartheid’, a segregação racial, a discriminação, a opressão colonial e outras formas de opressão e de dominação estrangeira permanecem condenadas e devem ser eliminadas. Os recursos naturais da Terra, incluídos o ar, a água, o solo, a flora e a fauna e, especialmente, parcelas representativas dos ecossistemas naturais, devem ser preservados em benefício das gerações atuais e futuras, mediante um cuidadoso planejamento ou administração adequados. Deve ser mantida e, sempre que possível, restaurada ou melhorada a capacidade da Terra de produzir recursos renováveis vitais. O homem tem a responsabilidade especial de preservar e administrar judiciosamente o patrimônio representado pela fauna e flora silvestres, bem assim o seu habitat, que se encontram atualmente em grave perigo, por uma combinação de fatores adversos. Em consequência, ao planificar o desenvolvimento econômico, deve ser atribuída importância à conservação da natureza, incluídas a flora e a fauna silvestres.ORGANIZAÇÃO DAS NAÇÕES UNIDAS. Declaração de Estocolmo sobre meio ambiente. In: Anais Conferência das Nações Unidas sobre Meio Ambiente Humano. Estocolmo, 1972 (Preâmbulo).A respeito dos segmentos do texto em destaque, I. “... em um meio ambiente de qualidade tal que lhe permite levar uma vida digna” II. “... as políticas que promovem ou perpetuam o ‘apartheid\" III. “... pela fauna e flora silvestres, bem assim o seu habitat, que se encontram atualmente em grave perigo\"é correto afirmar que","opcoes":["são orações subordinadas substantivas.","são orações subordinadas adverbiais consecutivas.","apenas em II e III o que funciona como pronome relativo.","apenas em I e II o que funciona como conjunção integrante.","em I, II e III o vocábulo que funciona, respectivamente, como conjunção integrante, pronome relativo e pronome relativo."],"correta":2,"explicacao":"Gabarito: <strong>apenas em II e III o que funciona como pronome relativo.</strong>.","banca":"FUNDEPES","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4527,"enunciado":"No período “É pouco provável que o surto da Guiné Equatorial se torne uma pandemia tão disseminada quanto a da Covid-19”, a oração em destaque é:","opcoes":["Subordinada substantiva predicativa.","Subordinada adjetiva restritiva.","Subordinada substantiva subjetiva.","Subordinada adverbial comparativa."],"correta":2,"explicacao":"Gabarito: <strong>Subordinada substantiva subjetiva.</strong>.","banca":"CONSULPAM","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4528,"enunciado":"Em “um laudo da Polícia Federal feito em meados de 2022 constatou que quatro rios da região tinham contaminação por mercúrio”, a oração destacada se classifica como:","opcoes":["Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva subjetiva.","Oração subordinada adjetiva explicativa.","Oração subordinada adverbial de causa."],"correta":0,"explicacao":"Gabarito: <strong>Oração subordinada substantiva objetiva direta.</strong>.","banca":"CONSULPAM","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4533,"enunciado":"O período abaixo transcrito é formado por quatro orações. Quanto à sua configuração, é CORRETO afirmar que:“A Covid-19 alterou para sempre a dinâmica corporativa, normalizou o home office e escancarou a necessidade de priorizar o bem estar”.","opcoes":["Três orações estão coordenadas, estando presa ao último membro de coordenação uma oração subordinada substantiva objetiva indireta.","As quatro orações são coordenadas, sendo a última representada sob a forma reduzida de infinitivo.","Três orações estão coordenadas, estando vinculada ao último membro de coordenação uma oração subordinada substantiva completiva nominal.","As três primeiras orações são coordenadas e a última é objetiva direta reduzida de infinitivo.","Há três orações coordenadas e a última é subordinada adverbial de finalidade, sob a forma reduzida de infinitivo."],"correta":2,"explicacao":"Gabarito: <strong>Três orações estão coordenadas, estando vinculada ao último membro de coordenação uma oração subordinada substantiva completiva nominal.</strong>.","banca":"CPCON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4534,"enunciado":"Mas não se pode descartar que essas e outras tecnologias tenham aumentado a eficiência de obtenção de alimentos por parte dos Homo sapiens, tendo um efeito indireto negativo sobre os humanos arcaicos, que competiam por esses recursos com eles. (L.77-82) Em relação ao período acima, analise as afirmativas a seguir:I. Há uma ocorrência de conjunção integrante e uma ocorrência de pronome relativo. II. Há uma ocorrência de oração subordinada substantiva subjetiva. III. São quatro orações, sendo uma delas reduzida.Assinale","opcoes":["se apenas as afirmativas I e II estiverem corretas.","se apenas as afirmativas I e III estiverem corretas.","se apenas as afirmativas II e III estiverem corretas.","se nenhuma afirmativa estiver correta.","se todas as afirmativas estiverem corretas."],"correta":4,"explicacao":"Gabarito: <strong>se todas as afirmativas estiverem corretas.</strong>.","banca":"Instituto Access","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4535,"enunciado":"No trecho “O governo do Japão planeja aumentar o apoio financeiro oferecido às famílias que se mudarem da sua capital [...]” (1º parágrafo), a oração destacada classifica-se como:","opcoes":["subordinada adjetiva restritiva","subordinada adjetiva explicativa","subordinada substantiva objetiva direta","subordinada substantiva completiva nominal"],"correta":0,"explicacao":"Gabarito: <strong>subordinada adjetiva restritiva</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4536,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. A oração “Brown constatou que, quando as partículas estão suspensas em um meio [...], tendem a se movimentar de uma forma aleatória” (linhas 7 e 8) é classificada como subordinada substantiva apositiva.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4537,"enunciado":"Assinale a alternativa que indica o número correto de orações que compõem o período a seguir: “Ele leva sua questão até Júpiter, que propõe um acordo: ele ajudaria Cupido; em troca, o deus do amor daria uma mãozinha para que ele conquistasse qualquer donzela que chamasse sua atenção no futuro”.","opcoes":["2.","3.","4.","5.","6."],"correta":4,"explicacao":"Gabarito: <strong>6.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4542,"enunciado":"“Adentre, amigo. Puxe uma cadeira e sente. Converse. Pergunte pela família. Olhe nos olhos. Cinco minutos de atenção não arrancarão pedaço. Fique o suficiente para demonstrar que se importa com seu interlocutor.” (linhas 19 e 20) As orações desse trecho classificam-se como","opcoes":["orações coordenadas sindéticas aditivas.","orações coordenadas sindéticas adversativas.","orações assindéticas com períodos justapostos.","orações coordenadas sindéticas explicativas.","orações assindéticas sem períodos justapostos."],"correta":2,"explicacao":"Gabarito: <strong>orações assindéticas com períodos justapostos.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4544,"enunciado":"Considerando o texto e suas estruturas gramaticais, julgue o item. O termo “prestar serviço à população” (linhas 11 e 12) desempenha função de oração subordinada subjetiva para o predicado “deve ser sempre a meta dos servidores” (linhas 12 e 13).\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4545,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. A oração ‘Não esqueça que, além das oito horas de trabalho, cada dia tem oito horas para se divertir’ (linhas 16 e 17) é classificada como subordinada substantiva objetiva indireta.\nC) Certo\nE) Errado Resposta correta","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4546,"enunciado":"Atente para os excertos I e II:I. Há muito mais há dizer, mas o registro histórico demonstra com clareza o pouco mérito da doutrina padrão. II. Como todos sabemos muito bem, agora estamos diante das decisões mais agourentas da história humana.A classificação correta das orações em negrito está indicada em:","opcoes":["Oração subordinada adverbial concessiva e oração subordinada adverbial condicional.","Oração coordenada sindética explicativa e oração subordinada adverbial concessiva.","Oração coordenada sindética adversativa e oração subordinada adverbial conformativa.","Oração coordenada assindética e oração subordinada adverbial proporcional. Resposta correta"],"correta":3,"explicacao":"Gabarito: <strong>Oração coordenada assindética e oração subordinada adverbial proporcional. Resposta correta</strong>.","banca":"FUMARC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4547,"enunciado":"Considere o diagrama abaixo. No período do diagrama, identifica-se uma oração I. subordinada, pois depende sintaticamente do período complexo do qual é constituinte. II. subordinada adverbial, pois funciona como adjunto adverbial do período complexo. III. subordinada subjetiva, que funciona como sujeito da outra oração. Está CORRETO o que se afirma em:","opcoes":["I, apenas.","I e II, apenas.","II e III, apenas.","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FUMARC","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4548,"enunciado":"Na subordinação, há orações que dependem sintaticamente de outras, isto é, que são termos de outras.A esse respeito, informe se é verdadeiro (V) ou falso (F) o que se afirma sobre as orações sublinhadas.( ) Em “Apanhei muitas frutas para os meus filhos quando eram pequenos.”, há uma oração adverbial temporal. ( ) Na passagem “Então, é uma criação coletiva que contribuiu para consolidar a cidade-parque.”, a oração subordinada é adjetiva explicativa. ( ) A oração “É necessário haver envolvimento da população em geral para que se possa despertar o interesse das pessoas” é subordinada adverbial final. ( ) A oração subordinada “ele propõe que sejam plantadas árvores frutíferas nativas no Plano Piloto e nas cidades-satélites.” classifica-se como substantiva subjetiva.De acordo com as afirmações, a sequência correta é","opcoes":["F, F, V, V.","V, V, F, F.","F, V, F, V.","V, F, V, F","V, V, V, F."],"correta":3,"explicacao":"Gabarito: <strong>V, F, V, F</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4549,"enunciado":"A oração “Fico feliz sempre que faço uma viagem diferente” pode ser classificada como:","opcoes":["oração subordinada adverbial condicional.","oração subordinada adverbial conformativa.","oração subordinada adverbial final.","oração subordinada adverbial proporcional.","oração subordinada adverbial temporal."],"correta":4,"explicacao":"Gabarito: <strong>oração subordinada adverbial temporal.</strong>.","banca":"Instituto Avalia","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4550,"enunciado":"No que se refere ao texto e a seus aspectos linguísticos, julgue o item. A oração “é fato que os serviços ecossistêmicos marinhos e costeiros sofrem frequentemente interferências destrutivas” (linha 18) classifica-se como subordinada substantiva objetiva direta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4552,"enunciado":"Considerando os aspectos linguísticos e semânticos do texto, julgue o item. A oração “Ele afirma que essa mistura de espécies de climas temperados e do Ártico, vivendo lado a lado, não tem equivalente na era moderna” (linhas de 15 a 17) é classificada como subordinada objetiva indireta.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4553,"enunciado":"Na análise da organização dos períodos do texto, o trabalho em sala de aula deverá assinalar que se encontra oração substantiva em relação à oração principal em:","opcoes":["... passou velozmente pelo punho da rede e entrou na palha do telhado.","Era o presente do rato de merda que fez meu dedão de queijo...","Tenho a certeza de que estou envenenado.","... a ser cortada o mercúrio cromo, que escorre pelo pé...","... os ratos do sertão não são venenosos como os seus irmãos urbanos."],"correta":2,"explicacao":"Gabarito: <strong>Tenho a certeza de que estou envenenado.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4554,"enunciado":"Nunca pude entender a conversação que tive com uma senhora, há muitos anos, contava eu dezessete, ela trinta. Era noite de Natal. Havendo ajustado com um vizinho irmos à missa do galo, preferi não dormir; combinei que eu iria acordá-lo à meia-noite.A casa em que eu estava hospedado era a do escrivão Meneses, que fora casado, em primeiras núpcias, com uma de minhas primas. A segunda mulher, Conceição, e a mãe desta acolheram-me bem, quando vim de Mangaratiba para o Rio de Janeiro, meses antes, a estudar preparatórios. Vivia tranquilo, naquela casa assobradada da rua do Senado, com os meus livros, poucas relações, alguns passeios.ASSIS, Machado de. Missa do Galo. Disponível em: http:// www.biblio.com.br/defaultz.asp?link=http://www.biblio.com.br/ conteudo/MachadodeAssis/missadogalo.htm. Acesso em: 20 ago. 2022.A oração destacada no texto pode ser classificada sintaticamente como","opcoes":["subordinada adjetiva restritiva.","subordinada adjetiva explicativa.","subordinada completiva nominal.","subordinada substantiva subjetiva."],"correta":1,"explicacao":"Gabarito: <strong>subordinada adjetiva explicativa.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":4555,"enunciado":"Assinale a alternativa que indica a correta função sintática da oração sublinhada no trecho a seguir: “E eles me disseram que eu poderia rezar para qualquer coisa”.","opcoes":["Sujeito.","Predicativo do sujeito.","Complemento nominal.","Objeto indireto.","Objeto direto."],"correta":4,"explicacao":"Gabarito: <strong>Objeto direto.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4556,"enunciado":"Assinale a alternativa que indica a correta função sintática da oração sublinhada no período a seguir: “Não é novidade para ninguém que as novas tecnologias imprimiram um novo ritmo”.","opcoes":["Adjunto adverbial.","Adjunto adnominal.","Objeto direto.","Predicativo do sujeito.","Sujeito."],"correta":4,"explicacao":"Gabarito: <strong>Sujeito.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4557,"enunciado":"Assinale a alternativa que indica a correta função sintática da oração substantiva sublinhada no trecho a seguir: “Não é incomum que um adulto tão racional tenha precisado se estruturar dessa forma para lidar com os sentimentos”.","opcoes":["Sujeito.","Predicativo do sujeito.","Objeto direto.","Objeto indireto.","Complemento nominal."],"correta":0,"explicacao":"Gabarito: <strong>Sujeito.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4558,"enunciado":"A oração em destaque, no verso “é preciso suportar Antônio” é um exemplo de:","opcoes":["Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva predicativa.","Oração subordinada substantiva objetiva direta reduzida de infinitivo.","Oração subordinada substantiva subjetiva reduzida de infinitivo."],"correta":3,"explicacao":"Gabarito: <strong>Oração subordinada substantiva subjetiva reduzida de infinitivo.</strong>.","banca":"AGIRH","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4559,"enunciado":"Na frase: \"Mas andei lendo livros; e descobri QUE AQUELAS CORES TODAS NÃO EXISTEM NA PENA DO PAVÃO\" a oração \"QUE AQUELAS CORES TODAS NÃO EXISTEM NA PENA DO PAVÃO\", exerce a função de:","opcoes":["Sujeito.","Objeto Indireto.","Adjunto adnominal.","Objeto direto."],"correta":3,"explicacao":"Gabarito: <strong>Objeto direto.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4562,"enunciado":"A frase “Acho que posso, pessoalmente, terminar com o problema das n-rainhas por um tempo” é um exemplo de oração subordinada substantiva objetiva direta. Assinale a alternativa que apresente outro exemplo desse tipo de oração:","opcoes":["Viviane é muito sociável, mas também esperta.","Tenho medo de dirigir à noite.","Eu não tenho nada a ver com isso!","Todos querem que você tenha sucesso profissional."],"correta":3,"explicacao":"Gabarito: <strong>Todos querem que você tenha sucesso profissional.</strong>.","banca":"AGIRH","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4564,"enunciado":"Na frase “Os historiadores e estudiosos dizem que o termo surgiu na Grã-Bretanha” (linha 5, texto 2), a oração subordinada exerce a mesma função sintática que a expressão:","opcoes":["“atividade produtiva”, em “a economia solidária é uma atividade produtiva” (linha 32, texto 1).","“de diretores”, em “caso a cooperativa precise de diretores, estes são votados diretamente” (linhas 17-18, texto 2).","“o movimento”, em “o movimento da economia solidária se transformou em um modelo de desenvolvimento” (linha 24, texto 1).","“a prática de políticas públicas”, em “a inclusão da economia solidária entre os princípios da ordem econômica nacional irá facilitar a prática de políticas públicas” (linhas 37- 38, texto 1).","“o relator”, em “Inicialmente, destaca o relator, o movimento da economia solidária teve o objetivo de combater a miséria e o desemprego” (linhas 22-23, texto 1)."],"correta":3,"explicacao":"Gabarito: <strong>“a prática de políticas públicas”, em “a inclusão da economia solidária entre os princípios da ordem econômica nacional irá facilitar a prática de políticas públicas” (linhas 37- 38, texto 1).</strong>.","banca":"UEG","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4565,"enunciado":"Assinale a alternativa que indica a correta função sintática da oração destacada a seguir: “Tudo que eu olhava e achava que ia vender, eu vendia”.","opcoes":["Sujeito.","Objeto Direto.","Adjunto Adnominal.","Adjunto Adverbial.","Complemento Nominal."],"correta":1,"explicacao":"Gabarito: <strong>Objeto Direto.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4566,"enunciado":"Dentre as ocorrências do emprego do vocábulo “que”, assinale o que foi empregado para introduzir uma oração subordinada substantiva que atua, no período, como complemento verbal.","opcoes":["“O psiquiatra reforçou que identificar os casos precocemente é essencial [...]”","[...] é muito particular, só podemos fazer hipóteses sobre o que aconteceu, [...]”","“Falta de ar, tremor e crise de choro foram alguns dos sintomas que afetaram 26 estudantes [...]”","“A ansiedade e depressão são experiências emocionais que as pessoas muitas vezes não compartilham [...]”"],"correta":0,"explicacao":"Gabarito: <strong>“O psiquiatra reforçou que identificar os casos precocemente é essencial [...]”</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4567,"enunciado":"Leia o trecho e analise as afirmações que seguem:Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo, é importante que o dentista seja consultado para que seja feita uma avaliação, identificada a causa e iniciado o tratamento, caso seja necessário.I.A primeira vírgula do trecho foi empregada para separar expressões que indiquem explicação intercaladas na oração.II.Em \"Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo\" a primeira oração é subordinada adverbial condicional.III.Em \"...é importante que o dentista seja consultado para que seja feita uma avaliação\" a segunda oração tem a função de um sujeito.Está CORRETO o que se afirma em:","opcoes":["II, apenas.","I e II, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4568,"enunciado":"Leia o trecho e analise as afirmações que seguem: Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo, é importante que o dentista seja consultado para que seja feita uma avaliação, identificada a causa e iniciado o tratamento, caso seja necessário.I.A primeira vírgula do trecho foi empregada para separar expressões que indiquem explicação intercaladas na oração.II.Em \"Caso sejam notadas feridas no céu da boca que causam desconforto e não melhoram ao longo do tempo\" a primeira oração é subordinada adverbial condicional.III.Em \"...é importante que o dentista seja consultado para que seja feita uma avaliação\" a segunda oração tem a função de um sujeito.Está CORRETO o que se afirma em:","opcoes":["II, apenas.","I e II, apenas.","I, II e III.","II e III, apenas."],"correta":3,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4573,"enunciado":"Marque a alternativa com análise CORRETA.","opcoes":["O trecho: \"instiga e conduz, mas sem exigir-se desumanamente\" - está escrito com verbos de segunda conjugação","No segmento: \"buscar lá dentro o que nos mobiliza\" - temos exemplos de orações adverbiais reduzidas.","O período: \"É importante pensar ao extremo\" está escrito com exemplo de oração subordinada substantiva subjetiva.","A oração: \"o que nos mobiliza\" - está escrita com exemplo de ênclise."],"correta":2,"explicacao":"Gabarito: <strong>O período: \"É importante pensar ao extremo\" está escrito com exemplo de oração subordinada substantiva subjetiva.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4574,"enunciado":"Marque a alternativa com análise CORRETA.","opcoes":["O trecho: \"instiga e conduz, mas sem exigir-se desumanamente\" - está escrito com verbos de segunda conjugação.","No segmento: \"buscar lá dentro o que nos mobiliza\" - temos exemplos de orações adverbiais reduzidas.","A oração: \"o que nos mobiliza\" - está escrita com exemplo de ênclise.","O período: \"É importante pensar ao extremo\" está escrito com exemplo de oração subordinada substantiva subjetiva."],"correta":3,"explicacao":"Gabarito: <strong>O período: \"É importante pensar ao extremo\" está escrito com exemplo de oração subordinada substantiva subjetiva.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4578,"enunciado":"Segundo Bechara: “As orações reduzidas são subordinadas e quase sempre se podem desdobrar em orações desenvolvidas. O emprego das reduzidas por desenvolvidas e vice-versa, quando feito com arte e bom gosto, permite ao escritor variados modos de tornar o estilo conciso, não acumulado de quês e outros transpositores, enfim, elegante”. Avalie as orações reduzidas e as respectivas desenvolvidas apresentadas nas assertivas a seguir:I. Disse estar muito triste. – Disse que estava muito triste.II. Terminada a tarefa, ele se recolheu aos seus aposentos. – Quando terminou a tarefa, recolheu se aos seus aposentos.III. Foi à festa sem ser convidado. – Foi à festa sem que fosse convidado.IV. Tenho a impressão de o estar vendo. – Tenho a impressão de que o estou vendo.Quais das assertivas acima mantêm a correta relação entre a reduzida e a desenvolvida?","opcoes":["Apenas I e II.","Apenas III e IV.","Apenas I, II e III.","Apenas II, III e IV.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4579,"enunciado":"Assinale a alternativa que indica a correta função sintática exercida pela oração “que fazem isso bem” (l. 20-21).","opcoes":["Sujeito.","Objeto Direto.","Objeto Indireto.","Predicativo do Sujeito.","Complemento Nominal."],"correta":1,"explicacao":"Gabarito: <strong>Objeto Direto.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4582,"enunciado":"Na análise de um período composto cumpre, pois, ter em mente que a oração principal não exerce nenhuma função sintática em outra oração do período; que a oração subordinada desempenha sempre uma função sintática em outra oração, pois que dela é um termo ou parte de termos dependente. A oração subordinada substantiva, especificamente, exerce, portanto, a função de um substantivo, que pode ser sujeito, objeto direto, objeto indireto, predicativo, complemento nominal e aposto.Assim, no primeiro balão da charge, a oração “que o desmatamento na Amazônia cresceu 88% em junho?” exerce uma função sintática sobre a principal. Esta oração sublinhada classifica-se por oração subordinada substantiva","opcoes":["subjetiva.","predicativa.","objetiva direta.","objetiva indireta.","completiva nominal."],"correta":2,"explicacao":"Gabarito: <strong>objetiva direta.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4583,"enunciado":"Analise a frase: Tenho certeza de que você precisa melhorar sua postura. A frase analisada é uma oração:","opcoes":["Subordinada Substantiva Objetiva Indireta.","Coordenada Sindética Conclusiva.","Subordinada Adverbial Consecutiva.","Subordinada Substantiva Completiva Nominal."],"correta":3,"explicacao":"Gabarito: <strong>Subordinada Substantiva Completiva Nominal.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4586,"enunciado":"Num período podem aparecer orações que se relacionam pela coordenação e pela subordinação, tendo-se assim, um período misto.Com base nessa informação, analise a frase a seguir: \"O atleta entrou na piscina e pediu que todos saíssem.\"Sobre tal frase é INCORRETO afirmar que:","opcoes":["A 3ª oração é subordinada substantiva objetiva direta (em relação à 2ª Oração).","A 2ª oração é principal (em relação à 3ª oração).","A 2ª oração é coordenada sindética aditiva (em relação à 1ª oração).","A 1ª oração é coordenada sindética."],"correta":3,"explicacao":"Gabarito: <strong>A 1ª oração é coordenada sindética.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["analiseSintatica"]},{"id":4655,"enunciado":"Observe o trecho abaixo, extraído do poema, e indique em qual alternativa há a observação INCORRETA sobre as estruturas morfossintáticas:e aos domingossaem todos a passearo problema, sua senhorae outros pequenos probleminhas.Alternativas:","opcoes":["“Aos domingos” poderia ser realocado ao final do enunciado sem alterar seu sentido e gramaticalidade.","Colocar uma vírgula após “Aos domingos” não altera o sentido do texto e também não muda sua gramaticalidade.","A substituição de “a passear” por “passeando” manteria o sentido original pretendido pelo poeta.","“o problema, sua senhora / e outros pequenos probleminhas” exerce a função sintática de sujeito da forma verbal “saem a passear”.","“o problema, sua senhora / e outros pequenos probleminhas” exerce a função de sujeito composto, tendo como núcleos “problema”, “senhora” e “probleminhas”."],"correta":2,"explicacao":"Gabarito: <strong>A substituição de “a passear” por “passeando” manteria o sentido original pretendido pelo poeta.</strong>.","banca":"PS Concursos","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":4782,"enunciado":"Analise as assertivas a seguir a respeito da palavra “peculiar” (l. 10):I. Em relação à classe morfológica, a palavra é classificada como um substantivo.II. Sua função sintática no trecho é a de adjunto adnominal.III. Um sinônimo possível para o vocábulo é “singular”.Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas II e III.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas II e III.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4796,"enunciado":"Leia os trechos e analise as afirmativas pospostas:\"E ainda mais pessoas foram atraídas para o bufê ao lado do banquete repleto de insetos.\"\"Alguns teriam argumentado que era o de sempre: peixe selvagem com infusão de capim-limão e limão, lombo grelhado com geleia de cebola, curry de legumes com leite de coco.\"I.O vocábulo 'para o bufe' é agente da passiva.II.'pessoas' é o núcleo do sujeito de 'foram'.III.O vocábulo 'atraídas' é predicativo do sujeito.IV.A forma verbal 'teriam' apresenta sujeito indeterminado.V.'selvagem', 'grelhado' e 'de cebola' são adjuntos adnominais.VI.No segundo período, há predicado verbal e predicado nominal.Estão corretas:","opcoes":["Apenas II, III e VI.","Apenas III, IV e V.","Apenas II, III , V e VI.","Apenas I, II, IV e VI."],"correta":2,"explicacao":"Gabarito: <strong>Apenas II, III , V e VI.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4932,"enunciado":"Com base na classificação das classes de palavras da língua portuguesa, relacionar as colunas e assinalar a sequência correspondente.(1) Variável, pois pode ser flexionada. (2) Invariável, pois não pode ser flexionada.( ) Portanto. ( ) Batata frita. ( ) Divertido. ( ) No entanto.","opcoes":["2 - 1 - 1 - 2.","2 - 1 - 2 - 1.","1 - 2 - 2 - 1.","1 - 2 - 1 - 2."],"correta":0,"explicacao":"Gabarito: <strong>2 - 1 - 1 - 2.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":4985,"enunciado":"Sujeito é o termo sobre o qual se declara algo. Predicado é o que se declara do sujeito. Diante dos conceitos apresentados, qual alternativa a seguir possui, respectivamente, um sujeito e um predicado.","opcoes":["Ventava muito aquela noite.","Eram três horas da manhã.","Está aberta a temporada de férias.","Devagar vinha o jogador.","A ação do professor é necessária."],"correta":4,"explicacao":"Gabarito: <strong>A ação do professor é necessária.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":5179,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item abaixo. O substantivo “garagens” (linha 3) exerce a função sintática de objeto direto da forma verbal “existem”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":5356,"enunciado":"A saga começou quando ela publicou um vídeo em que provoca o espectador a descobrir qual vídeo foi gerado por IA e qual é real. Em relação às classes de palavras, é correto afirmar que o número de artigos simples presentes na frase é de","opcoes":["um","quatro","cinco","dois","três"],"correta":4,"explicacao":"Gabarito: <strong>três</strong>.","banca":"AMAUC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":5376,"enunciado":"Observe o trecho abaixo, extraído do poema, e indique em qual alternativa há a observação INCORRETA sobre as estruturas morfossintáticas: e aos domingos saem todos a passear o problema, sua senhora e outros pequenos probleminhas. Alternativas:","opcoes":["“Aos domingos” poderia ser realocado ao final do enunciado sem alterar seu sentido e gramaticalidade.","Colocar uma vírgula após “Aos domingos” não altera o sentido do texto e também não muda sua gramaticalidade.","A substituição de “a passear” por “passeando” manteria o sentido original pretendido pelo poeta.","“o problema, sua senhora / e outros pequenos probleminhas” exerce a função sintática de sujeito da forma verbal “saem a passear”.","“o problema, sua senhora / e outros pequenos probleminhas” exerce a função de sujeito composto, tendo como núcleos “problema”, “senhora” e “probleminhas”."],"correta":2,"explicacao":"Gabarito: <strong>A substituição de “a passear” por “passeando” manteria o sentido original pretendido pelo poeta.</strong>.","banca":"PS Concursos","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":5449,"enunciado":"O perfeccionismo socialmente prescrito torna-nos obstinadamente hipervigilantes. Assinale a opção CORRETA quanto a função sintática dos termos mencionados:","opcoes":["hipervigilantes = objeto direto.","obstinadamente = predicativo do sujeito.","o = artigo definido masculino singular.","prescrito = adjunto adnominal do sujeito."],"correta":3,"explicacao":"Gabarito: <strong>prescrito = adjunto adnominal do sujeito.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":5908,"enunciado":"Leia o período a seguir: “[...] em momento em que lutava para reestruturar operações para enfrentar a pandemia e o fracasso de um acordo de 4 bilhões de dólares com a Boeing, destaca a Reuters.” (linhas 9 a 13). Sobre o período, é CORRETO afirmar que:","opcoes":["A expressão “em que” poderia ser corretamente substituída por “no qual”.","Não há preposições no período.","A partícula “que” introduz uma oração subordinada adverbial.","Há erro de pontuação no período em questão."],"correta":0,"explicacao":"Gabarito: <strong>A expressão “em que” poderia ser corretamente substituída por “no qual”.</strong>.","banca":"IBGP","ano":2021,"temas_relacionados":["analiseSintatica"]},{"id":5923,"enunciado":"Assinale a alternativa CORRETA com relação ao seguinte trecho: “Em algum momento, milhares de anos atrás, algum humano da Pré-História modificou um osso, uma concha, uma pedra ou um pedaço de madeira e começou a apostar com os colegas qual marca apareceria quando ele lançasse o objeto ao chão”.","opcoes":["O trecho revela uma situação incerta, imprecisa, duvidosa ou eventual, expressa por elementos linguísticos como pronomes e artigos indefinidos.","A expressão adverbial “em algum momento” indica que é possível identificar, por meio das descobertas arqueológicas, um período mais ou menos preciso no qual os humanos começaram a jogar.","A construção “quando ele lançasse o objeto ao chão” é uma oração subordinada adverbial consecutiva, pois expressa uma consequência do exposto no predicado da oração principal.","Na passagem “modificou um osso, uma concha, uma pedra ou um pedaço de madeira e começou a apostar”, o verbo “modificar” apresenta objetos diretos coordenados entre si e um objeto indireto oracional (“começou a apostar”)."],"correta":0,"explicacao":"Gabarito: <strong>O trecho revela uma situação incerta, imprecisa, duvidosa ou eventual, expressa por elementos linguísticos como pronomes e artigos indefinidos.</strong>.","banca":"UNIOESTE","ano":2021,"temas_relacionados":["analiseSintatica"]},{"id":5949,"enunciado":"Assinale a alternativa correta, considerando o texto.","opcoes":["Na primeira estrofe, nas três vezes em que aparece a palavra “o”, ela é um artigo.","A expressão “e apesar da pura forma concluída” traz uma ideia de consequência ao fato expresso na estrofe.","A expressão “no ponto de partida”, sintaticamente, é um adjunto adverbial e tem função igual a das expressões “na água” e “na brisa”.","A palavra “entretanto”, usada na segunda e na última estrofe, denotam significados diferentes no contexto em que se inserem, pois iniciam oração coordenada e subordinada respectivamente.","A palavra “ovo” é usada duas vezes no poema. Em ambas as vezes, ela funciona como complemento do verbo da oração."],"correta":2,"explicacao":"Gabarito: <strong>A expressão “no ponto de partida”, sintaticamente, é um adjunto adverbial e tem função igual a das expressões “na água” e “na brisa”.</strong>.","banca":"FEPESE","ano":2021,"temas_relacionados":["analiseSintatica"]},{"id":6131,"enunciado":"Das classes de palavras do Texto, há contração entre elas em:","opcoes":["“O” (linha 1)","“de” (linha 2)","“no” (linha 4)","“para” (linha 11)"],"correta":2,"explicacao":"Gabarito: <strong>“no” (linha 4)</strong>.","banca":"AMEOSC","ano":2018,"temas_relacionados":["analiseSintatica"]},{"id":6163,"enunciado":"Das classes de palavras do Texto, há contração entre elas em:","opcoes":["“As” (linha 1)","“de” (linha 5)","“um” (linha 5)","“após” (linha 15)","“da” (linha 25)"],"correta":4,"explicacao":"Gabarito: <strong>“da” (linha 25)</strong>.","banca":"IDCAP","ano":2018,"temas_relacionados":["analiseSintatica"]},{"id":6232,"enunciado":"No trecho “É alentador constatar que tem caído de forma expressiva a disseminação da dengue no Brasil”, retirado do texto, qual é a classificação sintática do termo “alentador”?","opcoes":["Objeto direto.","Predicativo do sujeito.","Predicativo do objeto.","Complemento nominal."],"correta":1,"explicacao":"Gabarito: <strong>Predicativo do sujeito.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6259,"enunciado":"Nomeie a função CORRETA exercida pelos termos \"cardiovascular, óssea, muscular, metabólica, digestiva e ocular\" no subtítulo da reportagem.","opcoes":["Complemento verbal.","Adjunto adnominal.","Sujeito composto.","Adjunto adverbial.","Complemento nominal."],"correta":1,"explicacao":"Gabarito: <strong>Adjunto adnominal.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6263,"enunciado":"Assinale a opção correta, quanto à estrutura morfossintática do período “Textos institucionais precisam ser acessíveis, mas também tecnicamente suficientes”.","opcoes":["O termo “tecnicamente” exerce função adverbial e modifica o adjetivo “suficientes”.","O termo “institucionais” exerce a função sintática de predicativo do sujeito, por estabelecer relação com o verbo “ser”.","A conjunção “mas” estabelece relação conclusiva entre orações independentes.","O termo “acessíveis” funciona como núcleo do sujeito da oração.","A expressão “precisam ser” constitui locução nominal de valor explicativo."],"correta":0,"explicacao":"Gabarito: <strong>O termo “tecnicamente” exerce função adverbial e modifica o adjetivo “suficientes”.</strong>.","banca":"Quadrix","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6316,"enunciado":"Considerando a classificação dos predicados na norma padrão da língua portuguesa, assinale a alternativa em que há emprego de predicado nominal.","opcoes":["Os candidatos entregaram os formulários exigidos antes do encerramento oficial das inscrições acadêmicas.","A equipe organizadora apresentou os novos critérios avaliativos durante a reunião extraordinária do conselho.","Os pesquisadores concluíram o relatório técnico após extensa análise documental realizada pela comissão.","Os estudantes permaneceram apreensivos diante da divulgação dos resultados preliminares do processo seletivo"],"correta":3,"explicacao":"Gabarito: <strong>Os estudantes permaneceram apreensivos diante da divulgação dos resultados preliminares do processo seletivo</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6323,"enunciado":"Considerando os princípios da análise sintática na língua portuguesa, especialmente no que se refere aos termos acessórios da oração, analise a estrutura da frase a seguir: \"Os alunos dedicados receberam reconhecimento durante a cerimônia acadêmica.\" Assinale a alternativa que classifica corretamente a função sintática do termo destacado:","opcoes":["Objeto indireto.","Complemento nominal.","Predicativo do sujeito.","Adjunto adnominal."],"correta":3,"explicacao":"Gabarito: <strong>Adjunto adnominal.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6422,"enunciado":"Considerando a organização sintática e as relações estabelecidas entre os constituintes da oração abaixo, analise as assertivas que seguem: Uma cidade sustentável deve oferecer qualidade de vida aos seus habitantes, ... I. O adjetivo sustentável exerce função adnominal, integrando-se ao sintagma nominal e não ao predicado. II. A frase apresenta predicado verbo-nominal, em razão da presença de atributo implícito ao objeto direto. III. A locução verbal presente na oração indica aspecto conclusivo da ação verbal. Está CORRETO o que se afirma em:","opcoes":["I, apenas.","I e II, apenas.","I e lll, apenas.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I, apenas.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6429,"enunciado":"Leia o trecho transcrito do texto. “A sobreposição geracional começa na família, mas é aumentada exponencialmente graças a uma dessas invenções humanas: a escola. O que acontece de tão transformador na escola é que projetos de humanos têm tempo protegido para interagir com humanos adultos e aprender com eles, de forma sistematizada e eficiente, todo o conhecimento que a humanidade já construiu de mais importante para funcionarmos no planeta.” Com base na análise morfológica e sintática dos termos destacados no contexto em que aparecem, avalie as afirmações a seguir. I- Os termos “transformador”, “protegidos” e “adultos” exercem função adjetiva, qualificando os substantivos a que se referem. II- A expressão “na família”, na primeira oração, desempenha o papel de adjunto adverbial e expressa uma circunstância de intensidade. III- O verbo “aprender” rege dois complementos – um objeto direto e um objeto indireto – ambos exigidos por sua regência no contexto. IV- A conjunção “mas”, em “mas é aumentada exponencialmente graças a uma dessas invenções humanas: a escola.”, exerce a função de finalidade entre as orações. Está correto apenas o que se afirma em","opcoes":["I e III.","II e IV.","I, II e III.","I, II e IV.","II, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"CEFET-MG","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6468,"enunciado":"Assinale a alternativa com a classificação sintática incorreta das palavras destacadas no trecho abaixo. Para não perder (1) a autonomia, diz Fernanda, (2) muitos (3) idosos não querem parar de dirigir, não aceitam ir ao médico ou não querem abandonar (4) outras atividades que costumavam fazer (5) sozinhos.","opcoes":["(1) Substantivo","(2) Adjunto adnominal","(3) Núcleo do sujeito","(4) Objeto direto","(5) Adjunto adverbial"],"correta":0,"explicacao":"Gabarito: <strong>(1) Substantivo</strong>.","banca":"IBPTEC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6488,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir. No trecho “Trazer essa temática à tona é de grande importância”, o termo “de grande importância” exerce a função de complemento nominal do verbo “ser”, motivo pelo qual a substituição do adjetivo “grande” por grandiosa manteria a correção gramatical e a função sintática original.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":6641,"enunciado":"Observe o verso: \"Dinheiro não lhe emprestei.\" Assinale a alternativa CORRETA quanto à análise sintática dos termos da oração.","opcoes":["\"Dinheiro\" exerce a função de objeto direto do verbo \"emprestei\".","\"Lhe\" exerce a função de sujeito da oração.","\"Dinheiro\" exerce a função de sujeito da oração.","O sujeito da oração é indeterminado.","O verbo \"emprestei\" é impessoal."],"correta":0,"explicacao":"Gabarito: <strong>\"Dinheiro\" exerce a função de objeto direto do verbo \"emprestei\".</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6655,"enunciado":"Leia o trecho a seguir, adaptado da obra de Fernando Pessoa: \"Tenho em mim todos os sonhos do mundo. E, ainda assim, sinto que nada possuo verdadeiramente. Caminho pelas ruas sem destino, observando a vida que passa diante de meus olhos.\" Assinale a alternativa em que a análise gramatical do trecho está CORRETA.","opcoes":["O termo \"todos os sonhos do mundo\" exerce a função sintática de objeto indireto do verbo \"tenho\".","A expressão \"verdadeiramente\" é um adjetivo que caracteriza o substantivo \"nada\".","No trecho \"a vida que passa diante de meus olhos\", o pronome relativo \"que\" retoma o termo \"vida\" e introduz uma oração subordinada adjetiva.","A forma verbal \"caminho\" encontra-se no pretérito perfeito do indicativo.","A expressão \"sem destino\" desempenha a função de sujeito da oração."],"correta":2,"explicacao":"Gabarito: <strong>No trecho \"a vida que passa diante de meus olhos\", o pronome relativo \"que\" retoma o termo \"vida\" e introduz uma oração subordinada adjetiva.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6687,"enunciado":"No trecho “mais de 140 milhões de pessoas se conectaram à internet entre março e agosto de 2024 (Cetic.br), o que amplia o alcance de conteúdos sem comprovação científica”, o pronome relativo “que”:","opcoes":["Retoma o antecedente “internet” e exerce a função de sujeito da oração adjetiva explicativa subordinada à oração principal, indicando que é a internet que amplia o alcance dos conteúdos.","Retoma o substantivo “pessoas” e exerce a função de objeto direto da oração relativa, indicando que as pessoas são ampliadas em seu alcance pelos conteúdos sem comprovação científica.","Retoma o numeral “140 milhões” e exerce a função de adjunto adverbial de quantidade na oração adjetiva, quantificando o alcance dos conteúdos sem comprovação científica na internet brasileira.","Retoma toda a oração anterior (fato de 140 milhões de pessoas terem se conectado) e exerce a função de sujeito da oração adjetiva explicativa “amplia o alcance de conteúdos sem comprovação científica”."],"correta":3,"explicacao":"Gabarito: <strong>Retoma toda a oração anterior (fato de 140 milhões de pessoas terem se conectado) e exerce a função de sujeito da oração adjetiva explicativa “amplia o alcance de conteúdos sem comprovação científica”.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6696,"enunciado":"Assinale a alternativa cujo elemento de coesão formal destacado exerce uma função sintática de objeto direto e constitui, ainda, um elemento anafórico.","opcoes":["Especialistas em segurança alertam que o site é um exemplo de como agentes de IA podem facilmente sair de controle [...].","A visão do bilionário é compartilhada por outros no Vale do Silício, que se perguntam se um experimento online estaria aproximando os computadores de superar a inteligência de seus próprios criadores.","[...] AI slop - conteúdo de baixa qualidade gerado por IA que vem inundando a internet.","Andrej Karpathy, ex-diretor de IA da Tesla, chamou o Moltbook de \"genuinamente a coisa mais incrível, próxima de uma decolagem de ficção científica, que vi recentemente\"[...].","[...] é apenas fruto do desejo humano de acreditar que modelos de IA sejam capazes desse tipo de engano."],"correta":3,"explicacao":"Gabarito: <strong>Andrej Karpathy, ex-diretor de IA da Tesla, chamou o Moltbook de \"genuinamente a coisa mais incrível, próxima de uma decolagem de ficção científica, que vi recentemente\"[...].</strong>.","banca":"Instituto Legatus","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6697,"enunciado":"Considerando a norma-padrão da língua portuguesa e o funcionamento textual-discursivo dos elementos linguísticos presentes na charge, assinale a alternativa correta.","opcoes":["O pronome possessivo “seu”, em “qual o seu maior medo?”, exerce função determinante no sintagma nominal e estabelece referenciação direta com o interlocutor da pesquisa.","A construção “ficar sem internet” apresenta desvio de regência verbal, pois o verbo “ficar” exige preposição “de”.","O termo “desempregado” exerce função sintática de objeto direto do verbo “ficar”.","Em “Estou fazendo uma pesquisa”, o verbo auxiliar poderia ser substituído por “estar a fazer”, sem alteração de registro ou variação linguística.","O período do primeiro quadrinho é composto exclusivamente por subordinação adverbial consecutiva."],"correta":0,"explicacao":"Gabarito: <strong>O pronome possessivo “seu”, em “qual o seu maior medo?”, exerce função determinante no sintagma nominal e estabelece referenciação direta com o interlocutor da pesquisa.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6740,"enunciado":"Considerando o trecho, extraído do texto 1 “Em vez de negociar com cada credor isoladamente, o devedor pode acionar um procedimento que reúne todos os credores de dívidas de consumo em uma única audiência de conciliação, com apresentação de plano de pagamento unificado [...]” (linhas 25-28), analise as assertivas e identifique com V as verdadeiras e com F as falsas. ( ) O termo “que” é uma conjunção integrante que introduz uma oração subordinada substantiva objetiva direta. ( ) A expressão “de consumo” atua como um adjunto adnominal, caracterizando o tipo de dívida mencionada. ( ) No trecho “reúne todos os credores”, o termo “todos” é um pronome substantivo que exerce função de núcleo do objeto direto. ( ) O vocábulo “isoladamente” é um advérbio de modo porque indica a maneira como a ação de negociar é praticada no contexto. ( ) A expressão “em vez de” pode ser substituída por “ao invés de” sem alteração de sentido, pois ambas são equivalentes em qualquer contexto. A alternativa que contém a sequência correta, de cima para baixo, é","opcoes":["F V F F V","F V F V F","F F F V F","V V F V V","V V F F F"],"correta":1,"explicacao":"Gabarito: <strong>F V F V F</strong>.","banca":"CEFET-BA","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6826,"enunciado":"Leia o texto a seguir, adaptado de um trecho de José Régio, e assinale a alternativa CORRETA: \"Não sei por onde vou, não sei para onde vou, sei que não vou por aí.\"","opcoes":["A expressão \"por onde\" introduz uma oração subordinada substantiva objetiva direta.","O termo \"aí\" é um advérbio de lugar.","Todas as ocorrências da palavra \"não\" desempenham a função de pronome.","A forma verbal \"vou\" está no futuro do presente do indicativo.","A oração \"que não vou por aí\" exerce a função de sujeito da oração principal."],"correta":1,"explicacao":"Gabarito: <strong>O termo \"aí\" é um advérbio de lugar.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6843,"enunciado":"“[...] a empresa foi condenada a devolver integralmente o valor gasto nos desodorantes [...]” Em se tratando da estrutura sintática do período, é correto afirmar que:","opcoes":["está na voz passiva ativa, com agente expresso.","está na voz passiva analítica, sem agente expresso.","está na voz passiva analítica, com agente expresso.","está na voz passiva sintética, com agente expresso.","está na voz passiva sintética, sem agente expresso."],"correta":1,"explicacao":"Gabarito: <strong>está na voz passiva analítica, sem agente expresso.</strong>.","banca":"IDECAN","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6882,"enunciado":"No trecho “Ter um site atualizado, estar presente nas redes sociais, produzir conteúdo relevante e adotar canais de atendimento digitais são medidas essenciais”, as formas verbais “ter”, “estar”, “produzir” e “adotar” desempenham uma função específica na organização das ideias. Com base nessa informação, assinale a opção que apresenta corretamente essa estruturação sintático&#8209;semântica.","opcoes":["Atuam como conectores de oposição às inovações tecnológicas citadas anteriormente.","Funcionam como núcleos de orações substantivas subjetivas que enumeram ações necessárias.","Representam marcas de linguagem coloquial voltadas à aproximação com o público jovem.","Constituem uma estrutura de subordinação adjetiva que restringe o conceito de “medidas”.","Indicam uma relação de causa e consequência direta entre o site e a venda final."],"correta":1,"explicacao":"Gabarito: <strong>Funcionam como núcleos de orações substantivas subjetivas que enumeram ações necessárias.</strong>.","banca":"Quadrix","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6888,"enunciado":"“A equipe técnica veio analisando os relatórios até que a auditoria externa pudesse aprovar o seu trabalho.” Assinale a alternativa em que o período acima é integralmente transposto para a voz passiva, respeitando sua estrutura sintática.","opcoes":["Os relatórios vieram sendo analisados pela equipe técnica até que o seu trabalho pudesse ser aprovado pela auditoria externa.","Os relatórios vieram sendo analisados pela equipe técnica até que pudesse ser aprovado os trabalhos pela auditoria externa.","Os relatórios foram sendo analisados pela equipe técnica até que o trabalho seja aprovado pela auditoria externa.","Os relatórios foram sendo analisados pela equipe técnica até que o trabalho pudesse ser aprovado pela auditoria externa."],"correta":0,"explicacao":"Gabarito: <strong>Os relatórios vieram sendo analisados pela equipe técnica até que o seu trabalho pudesse ser aprovado pela auditoria externa.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6889,"enunciado":"Considere o período abaixo: “Os concorrentes demonstram que exames qualificatórios têm desdobramentos inevitáveis na qualidade de vida a curto prazo.” Em relação ao verbo “têm”, assinale a alternativa que classifica corretamente o seu sujeito, considerando a estrutura sintática do período e a norma-padrão da Língua Portuguesa.","opcoes":["Sujeito simples, expresso por um núcleo substantivo acompanhado de adjunto adnominal.","Sujeito composto, formado por núcleo e adjunto flexionados no plural.","Sujeito oracional, representado por uma oração subordinada substantiva.","Sujeito indeterminado, como próprio do verbo “ter” no sentido de denominar existência."],"correta":0,"explicacao":"Gabarito: <strong>Sujeito simples, expresso por um núcleo substantivo acompanhado de adjunto adnominal.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6910,"enunciado":"Considerando o preconizado por Cegalla (2005), analise as assertivas a seguir sobre o emprego do infinitivo pessoal flexionado: I. É empregado quando o infinitivo tem sujeito próprio, diverso do sujeito da oração principal, como, por exemplo, em: “Trabalharia muito para eles alcançarem um futuro brilhante”. II. O emprego dessa estrutura verbal é vinculado a normas rígidas e, mesmo em questões relacionadas à liberdade ou gosto literário, não há possibilidade de usos distintos. III. Se o infinitivo tiver como sujeito um pronome oblíquo com o qual constitua o objeto direto dos verbos “deixar, fazer, mandar, ver, ouvir e sentir”, deverá ser flexionado, como, por exemplo, em: “Faça-os entrarem em casa”. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas II e III."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6958,"enunciado":"Em textos de opinião, determinadas palavras assumem função gramatical decisiva para a construção do sentido. No trecho “Acontece aos montes, todo dia”, a expressão “aos montes” classifica-se gramaticalmente como","opcoes":["locução adjetiva de valor quantificador.","adjunto adnominal de núcleo elíptico.","sintagma nominal com função de objeto indireto.","locução adverbial de intensidade."],"correta":3,"explicacao":"Gabarito: <strong>locução adverbial de intensidade.</strong>.","banca":"IV - UFG","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":6968,"enunciado":"Palavra expletiva é aquela que não exerce função sintática, sendo empregada como realce ou ênfase. Constitui uma palavra expletiva aquela sublinhada no seguinte trecho:","opcoes":["- Mas no saco só tem areia!","- Que diabo a senhora leva nesse saco?","- O senhor promete que não \"espaia\"?","Aí quem sorriu foi o fiscal.","Talvez a velhinha passasse um dia com areia e no outro com muamba."],"correta":1,"explicacao":"Gabarito: <strong>- Que diabo a senhora leva nesse saco?</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7002,"enunciado":"No último parágrafo, os vocábulos “são”, em “medos são adaptações”, e “vão”, em “geralmente em vão”, pertencem a classes de palavras distintas.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":7038,"enunciado":"\"De quem morreu sinto é a falta, o prejuízo da perda, a ausência.\" Analise a organização sintática e os diferentes modos de ordenação dos termos da oração, assinalando V para as afirmativas verdadeiras e F para as falsas. (__) A disposição dos termos respeita a ordem direta, uma vez que se organizam de forma linear, estabelecendo adequada relação entre o sujeito, o verbo e seus respectivos complementos. (__) A construção apresenta inversão da ordem canônica, com deslocamento do complemento e uso de estrutura enfática. (__) A expressão 'de quem morreu' exerce função de complemento nominal do substantivo 'falta'. (__) O emprego de 'falta' e 'ausência' configura redundância nominal, por se tratarem de termos semanticamente próximos, resultando em repetição desnecessária de sentido no enunciado. Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["V, F, F, V.","F, V, F, F.","F, V, V, F.","F, V, V, V."],"correta":2,"explicacao":"Gabarito: <strong>F, V, V, F.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7084,"enunciado":"A respeito do texto precedente e de seus aspectos linguísticos e literários, julgue o item a seguir. No período \"Parecerá que se chamam assim por correr nelas vento fresco; mas a razão por que os portugueses lhe deram este nome é a que direi a V. Rev.ma.\", a preposição \"por\" introduz oração subordinada adverbial causal nas duas ocorrências.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":7182,"enunciado":"\"À medida que\" nossa dependência de dispositivos digitais para trabalho, educação e interação social só aumenta, há mais riscos à saúde de nossos olhos. Morfologicamente, o termo destacado, nesta frase, trata-se de:","opcoes":["Adjunto adverbial.","Complemento nominal.","Locução conjuntiva.","Adjunto adnominal."],"correta":2,"explicacao":"Gabarito: <strong>Locução conjuntiva.</strong>.","banca":"IDCAP","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":7223,"enunciado":"No trecho \"Não me engano achando que velocidade é virtude\", a palavra \"que\" desempenha um papel fundamental na construção do sentido da frase. Assinale a alternativa que indica corretamente a classe gramatical do termo \"que\" e a função que ele exerce nesse contexto.","opcoes":["Advérbio, intensificando a ideia expressa pela oração principal e conferindo ênfase ao sentido de \"velocidade\".","Conjunção coordenativa explicativa, conectando ideias que estabelecem relação de explicação sobre a afirmação anterior.","Conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta, complementando o verbo \"achando\".","Pronome relativo, retomando o antecedente \"velocidade\" e introduzindo uma oração subordinada adjetiva explicativa."],"correta":2,"explicacao":"Gabarito: <strong>Conjunção integrante, introduzindo uma oração subordinada substantiva objetiva direta, complementando o verbo \"achando\".</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":7246,"enunciado":"A língua possui unidades que têm por missão reunir orações num mesmo enunciado. Estas unidades são chamadas conjunções, que se têm repartido em coordenativas e subordinativas. Tendo isso como referência, analise a frase: \"Todos foram embora, visto que a escuridão da noite chegou repentinamente.\" A conjunção do enunciado acima tem a função de indicar:","opcoes":["Tempo, expressando o tempo em que ocorre a ação declarada na oração principal.","Causa, introduzindo uma oração que exprime a causa, o motivo, a razão do pensamento da oração principal.","Finalidade, introduzindo oração que exprime a intenção, o objetivo da declaração expressa na oração principal.","Conformidade, introduzindo oração que exprime um fato em conformidade com outro expresso na oração principal.","Concessão, introduzindo uma oração que exprime que um obstáculo não impedirá ou modificará a declaração da oração principal."],"correta":1,"explicacao":"Gabarito: <strong>Causa, introduzindo uma oração que exprime a causa, o motivo, a razão do pensamento da oração principal.</strong>.","banca":"AMAUC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":7267,"enunciado":"Analise as assertivas abaixo e assinale V, se verdadeiras, ou F, se falsas. ( ) Na linha 08, o “que” em destaque é classificado como pronome relativo. ( ) Na linha 12, o “que” em destaque introduz uma oração subordinada adjetiva restritiva. ( ) Na linha 13, o “que” em destaque é classificado como conjunção integrante. ( ) Na linha 34, o “que” em destaque está retomando “órgão”. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V – V – F – V.","V – F – V – F.","V – F – F – V.","F – V – V – F.","F – V – F – V."],"correta":1,"explicacao":"Gabarito: <strong>V – F – V – F.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":7280,"enunciado":"\"O agro não promete vida eterna, mas, sem dúvida, tem contribuído para que possamos viver mais e melhor.\" Em relação à oração destacada é correto o que se afirma em:","opcoes":["É uma oração coordenada sindética aditiva, com a conjunção 'mas' com valor de adição.","É uma oração coordenada sindética concessiva, com a conjunção 'mas' com valor de oposição.","É uma oração coordenada sindética adversativa, com a conjunção 'mas' com valor de oposição.","É uma oração coordenada sindética adversativa, com a conjunção 'sem dúvida' com valor de oposição."],"correta":2,"explicacao":"Gabarito: <strong>É uma oração coordenada sindética adversativa, com a conjunção 'mas' com valor de oposição.</strong>.","banca":"Unesc","ano":2025,"temas_relacionados":["analiseSintatica"]},{"id":7357,"enunciado":"No trecho motivo da resiliência do mercado de trabalho, que vem mantendo a taxa de desemprego em nível mais baixo, o termo sublinhado classifica-se sintaticamente como:","opcoes":["Uma conjunção integrante, introduzindo uma oração subordinada substantiva com função de objeto direto.","Um pronome relativo, pois retoma o antecedente mercado de trabalho e atua como sujeito da oração que introduz.","Uma partícula apassivadora, indicando que a ação de manter a taxa é sofrida pelo mercado.","Uma preposição essencial, exigida pela regência obrigatória do substantivo resiliência."],"correta":1,"explicacao":"Gabarito: <strong>Um pronome relativo, pois retoma o antecedente mercado de trabalho e atua como sujeito da oração que introduz.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7360,"enunciado":"\"É um projeto que fortalece o Sistema Único de Saúde e melhora a vida dos brasileiros.\" Considerando a análise sintática do período acima, marque com V as afirmativas verdadeiras ou com F as falsas. (__)O termo 'que' é um pronome relativo que retoma 'projeto', exercendo a mesma função sintática que em 'Chegaram as pessoas que convidei para o evento', na qual retoma 'pessoas'. (__)A oração 'um projeto que fortalece...' exerce a função sintática de sujeito do verbo 'ser', posposto ao verbo. (__)Os verbos 'fortalecer' e 'melhorar' compartilham o mesmo sujeito, que é retomado pelo pronome relativo 'que', o qual faz referência ao termo 'projeto'. (__)A expressão 'a vida dos brasileiros' exerce a mesma função sintática do pronome oblíquo 'me' em 'Ana me telefonou ontem à noite para avisar sobre a reunião'. Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["F, F, V, F.","V, F, F, V.","V, V, V, V.","F, V, V, F."],"correta":0,"explicacao":"Gabarito: <strong>F, F, V, F.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7369,"enunciado":"Observe o trecho presente após o quinto parágrafo, no modelo de atendimento chamado \"Notícia de fato ou denúncia\": envolve o recebimento e registro de informações sobre possíveis casos, que podem ser comunicados por qualquer pessoa ou instituição. Sobre o pronome relativo sublinhado e a oração que ele introduz, assinale a alternativa que apresenta sua classificação gramatical CORRETA na frase em destaque.","opcoes":["Trata-se de uma oração subordinada adjetiva explicativa, pois, separada por vírgula, adiciona uma informação complementar ao antecedente casos, sem restringir o seu universo.","Configura-se como uma oração subordinada adjetiva restritiva, uma vez que delimita e restringe de forma estrita quais tipos de casos policiais deverão ser registrados.","É uma oração subordinada substantiva apositiva, exercendo a função sintática exclusiva de explicar e enumerar o termo genérico informações.","Trata-se de uma oração subordinada adverbial causal, justificando para o leitor o motivo lógico pelo qual a denúncia pode ser feita por qualquer cidadão."],"correta":0,"explicacao":"Gabarito: <strong>Trata-se de uma oração subordinada adjetiva explicativa, pois, separada por vírgula, adiciona uma informação complementar ao antecedente casos, sem restringir o seu universo.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7370,"enunciado":"A palavra que possui alta versatilidade morfossintática na Língua Portuguesa. Diante disso, observe o seu emprego na passagem: O documento estabelece princípios que devem orientar o atendimento às vítimas. Sobre a classificação e a relação sintática desempenhada por esse termo sublinhado na oração, assinale a alternativa CORRETA.","opcoes":["Funciona como uma conjunção integrante introduzindo uma oração subordinada substantiva que atua como objeto direto do verbo estabelece.","Atua como uma preposição acidental de subordinação, unindo duas orações assindéticas que possuem valores semânticos finais.","Classifica-se como pronome relativo, retomando o substantivo antecedente princípios e exercendo a função sintática de sujeito da oração que introduz.","Exerce o papel estrito de partícula expletiva de realce, podendo ser retirada da oração sem causar qualquer falha estrutural, gramatical ou semântica."],"correta":2,"explicacao":"Gabarito: <strong>Classifica-se como pronome relativo, retomando o substantivo antecedente princípios e exercendo a função sintática de sujeito da oração que introduz.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7406,"enunciado":"\"Embora se trate de uma unidade de distância, o ano-luz nos conta quanto tempo levou a viagem.\" Considerando os elementos linguísticos utilizados no trecho, julgue as afirmativas: I.A oração iniciada pela conjunção 'Embora...é subordinada adverbial concessiva, indicando que há uma contradição aparente entre ser unidade de distância e informar tempo, mas isso não impede a ideia principal. II.A expressão 'a viagem' exerce a função de objeto direto do verbo 'levar', uma vez que completa o sentido do verbo sem o auxílio de preposição. III.O pronome oblíquo 'nos' é objeto indireto do verbo 'contar', ao passo que a expressão 'quanto tempo levou a viagem' exerce a função de objeto direto. IV.A expressão 'de uma unidade de distância' exerce a função de sujeito do verbo 'tratar', configurando uma construção em voz passiva. Assinale a alternativa que apresenta as proposições CORRETAS.","opcoes":["I e III, apenas.","I, II e III, apenas.","I e IV, apenas.","I, II, III e IV.","II e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"Unesc","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7415,"enunciado":"Considerando a frase Ela atravessa a renda, bem como seus aspectos sintáticos e semânticos no contexto em que se insere, assinale a alternativa INCORRETA.","opcoes":["O pronome Ela exerce função de sujeito simples, retomando um referente previamente estabelecido.","O predicado é classificado como nominal, uma vez que o verbo expressa estado atribuído ao sujeito.","O sintagma a renda desempenha função de objeto direto, constituindo o complemento do verbo.","A ordem sintática observada corresponde ao padrão canônico da língua portuguesa (Sujeito + Verbo + Complemento)."],"correta":2,"explicacao":"Gabarito: <strong>O sintagma a renda desempenha função de objeto direto, constituindo o complemento do verbo.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7441,"enunciado":"\"Poucos países possuem um programa de biocombustíveis tão avançado quanto o brasileiro, o que aumenta a resiliência diante de choques externos. Considerando a análise sintática dos elementos linguísticos empregados no trecho, julgue as afirmativas a seguir: I. O sintagma 'Poucos países' exerce a função de sujeito simples, assim como \"duas horas\" na oração 'No relógio deram duas horas', construção gramaticalmente correta. II. O substantivo 'programa' exerce a função de núcleo do objeto direto do verbo 'possuir' e de núcleo do sujeito do verbo 'avançar'. III. A expressão 'a resiliência diante de choques externos' exerce a função sintática de sujeito posposto do verbo 'aumentar'. IV. O vocábulo 'países' exerce a mesma função sintática do pronome oblíquo 'a', considerando o verbo 'entrar', na frase 'Eu a vi entrar no quarto'. Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["I, II e IV, apenas.","II e III, apenas.","II, III e IV, apenas.","I e II, apenas","III e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7443,"enunciado":"\"Poucos países possuem um programa de biocombustíveis tão avançado quanto o brasileiro, o que aumenta a resiliência diante de choques externos. Considerando a análise sintática dos elementos linguísticos empregados no trecho, julgue as afirmativas a seguir: I. O sintagma 'Poucos países' exerce a função de sujeito simples, assim como \"duas horas\" na oração 'No relógio deram duas horas', construção gramaticalmente correta. II. O substantivo 'programa' exerce a função de núcleo do objeto direto do verbo 'possuir' e de núcleo do sujeito do verbo 'avançar'. III. A expressão 'a resiliência diante de choques externos' exerce a função sintática de sujeito posposto do verbo 'aumentar'. IV. O vocábulo 'países' exerce a mesma função sintática do pronome oblíquo 'a', considerando o verbo 'entrar', na frase 'Eu a vi entrar no quarto'. Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["I, II e IV, apenas","I e II, apenas.","II e III, apenas.","III e IV, apenas.","II, III e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e IV, apenas</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7444,"enunciado":"\"Poucos países possuem um programa de biocombustíveis tão avançado quanto o brasileiro, o que aumenta a resiliência diante de choques externos. Considerando a análise sintática dos elementos linguísticos empregados no trecho, julgue as afirmativas a seguir: I. O sintagma 'Poucos países' exerce a função de sujeito simples, assim como \"duas horas\" na oração 'No relógio deram duas horas', construção gramaticalmente correta. II. O substantivo 'programa' exerce a função de núcleo do objeto direto do verbo 'possuir' e de núcleo do sujeito do verbo 'avançar'. III. A expressão 'a resiliência diante de choques externos' exerce a função sintática de sujeito posposto do verbo 'aumentar'. IV. O vocábulo 'países' exerce a mesma função sintática do pronome oblíquo 'a', considerando o verbo 'entrar', na frase 'Eu a vi entrar no quarto'. Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["III e IV, apenas.","II e III, apenas.","I, II e IV, apenas.","II, III e IV, apenas.","I e II, apenas."],"correta":2,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7622,"enunciado":"No trecho \"podendo suspender o uso de faixas de rolamento e determinar desvios de rota sempre que o quadro operacional assim indicar\", a forma verbal \"indicar\" integra uma estrutura subordinada. A classificação morfossintática que descreve a natureza dessa forma verbal e sua relação com a oração principal é:","opcoes":["trata-se de verbo no futuro do subjuntivo, integrando oração subordinada adverbial temporal introduzida por \"sempre que\", que indica a recorrência de uma condição como fator que aciona a possibilidade descrita na oração principal.","trata-se de verbo no presente do subjuntivo, em oração subordinada adverbial concessiva introduzida por \"sempre que\", em que a ação principal ocorre independentemente das variações do quadro operacional descrito.","trata-se de verbo no futuro do subjuntivo, que integra uma oração subordinada adverbial condicional introduzida por \"sempre que\", estabelecendo que a realização da ação principal está condicionada à verificação habitual da circunstância descrita.","trata-se de verbo no presente do indicativo, em oração subordinada adverbial conformativa introduzida por \"sempre que\", indicando que a ação dos agentes se conforma ao estado do quadro operacional no momento da decisão."],"correta":0,"explicacao":"Gabarito: <strong>trata-se de verbo no futuro do subjuntivo, integrando oração subordinada adverbial temporal introduzida por \"sempre que\", que indica a recorrência de uma condição como fator que aciona a possibilidade descrita na oração principal.</strong>.","banca":"IBAM","ano":2026,"temas_relacionados":["analiseSintatica"]},{"id":7647,"enunciado":"Quanto aos aspectos gramaticais do texto, analise as afirmativas. I. Em: “[...] o que só foi possível devido à existência de ferramentas tecnológicas avançadas e à capacidade do ser humano de encontrar soluções [...]” (2º parágrafo), o emprego da crase é obrigatório. II. Em: “Há cinco, dez anos atrás [...]” (2º parágrafo), o verbo “haver” está conjugado no futuro. III. Em: “Carreira bem-sucedida e sustentável” (3º parágrafo), os elementos em destaque exercem a função sintática de adjunto adverbial. IV. Em: “Profissionais que utilizam a IA tendem a ser considerados estratégicos [...]” (4º parágrafo), o sujeito em destaque é composto. Assinale a alternativa CORRETA.","opcoes":["Apenas a afirmativa I está correta.","Apenas a afirmativa III está correta","Apenas as afirmativas II e III estão corretas.","Apenas as afirmativas I e IV estão corretas.","Apenas as afirmativas III e IV estão corretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas a afirmativa I está correta.</strong>.","banca":"COPESE - UFT","ano":2026,"temas_relacionados":["analiseSintatica","crase"]},{"id":7904,"enunciado":"Quanto aos aspectos linguísticos do texto, julgue o item. No segmento “a dados, metodologias e ferramentas” (linhas 22 e 23), o emprego da preposição “a” justifica&#8209;se pela função sintática de objeto indireto exercida pelo referido segmento.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":8055,"enunciado":"O excerto a seguir é introduzido por uma oração subordinada adverbial concessiva: “Apesar de ter se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa.” Assinale a alternativa em que ocorre a substituição da locução “apesar de” por outra expressão de mesmo valor, com todas as modificações necessárias para manter a adequação da sentença.","opcoes":["Embora ter se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa.","Consoante tenha se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa.","Ainda que tenha se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa.","Além de ter se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa.","Contudo tenha se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa."],"correta":2,"explicacao":"Gabarito: <strong>Ainda que tenha se tornado a marca registrada da nobreza, tem uma origem pouco glamourosa.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":8129,"enunciado":"Com base na classificação das classes de palavras da língua portuguesa, relacionar as colunas e assinalar a sequência correspondente. (1) Variável, pois pode ser flexionada. (2) Invariável, pois não pode ser flexionada. ( ) Portanto. ( ) Batata frita. ( ) Divertido. ( ) No entanto.","opcoes":["2 - 1 - 1 - 2.","2 - 1 - 2 - 1.","1 - 2 - 2 - 1.","1 - 2 - 1 - 2."],"correta":0,"explicacao":"Gabarito: <strong>2 - 1 - 1 - 2.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":8153,"enunciado":"Ainda com relação ao enunciado presente no último quadrinho da tira (“Bem que dizem que repartir é morrer um pouco\"), analise as assertivas abaixo. I- As duas ocorrências da palavra que correspondem à mesma função sintática. II- A segunda ocorrência da palavra que atende à função sintática de conjunção integrante. III- Os verbos repartir e morrer estão no infinitivo. IV- Em “Bem que dizem”, tem-se uma oração sem sujeito. É CORRETO o que se afirma apenas em:","opcoes":["II e III.","I e II.","I e IV.","II e IV.","III e IV."],"correta":0,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":8474,"enunciado":"Foi prevenido aos candidatos deste concurso que as informações gramaticais do conteúdo programático seriam consideradas sob o ponto de vista textual. Nesse caso, assinale a opção em que a preposição “a” tem seu papel textual corretamente identificado.","opcoes":["Introduzir um objeto direto preposicionado: Amar a Deus sobre todas as coisas.","Introduzir um objeto indireto: Chegar à eternidade na flor da idade.","Preceder um complemento nominal: Decidiu entregar à sorte a sua decisão.","Introduzir um adjunto adverbial: Deu bom-dia a todos os presentes.","Evitar a ambiguidade na frase: O turista cumprimentou a todos os presentes."],"correta":0,"explicacao":"Gabarito: <strong>Introduzir um objeto direto preposicionado: Amar a Deus sobre todas as coisas.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["analiseSintatica"]},{"id":133018,"enunciado":"A respeito do emprego e flexão de palavras no texto, julgue os itens que se seguem.\n\nDada a função acessória que desempenham nos sintagmas em que se inserem, os termos “excessiva” (L.10) e “ao vivo” (L.11) poderiam ser suprimidos da estrutura sintática, sem prejuízo para o sentido original e a coerência do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":342951,"enunciado":"Julgue os itens de 8 a 20 com relação a aspectos gramaticais e ortográficos do texto.\n\nNo trecho “a mulher é que lhe disse” (l.13), a expressão “é que” confere ênfase ao elemento que exerce a função de sujeito da oração.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":377367,"enunciado":"As expressões “outras formas de prestação/realização de trabalho” (l.5-6) e “o alcance das expressões relação de trabalho e relação de emprego” (l.12-13) desempenham a mesma função sintática nos períodos em que ocorrem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":377368,"enunciado":"No trecho “está ligada à relação de trabalho subordinado que corresponde ao vínculo de emprego” (l.16-17), seria mantida a correção gramatical caso se substituisse o elemento “que” por a que, embora as relações entre os termos da oração fossem alteradas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":417459,"enunciado":"Acerca das estruturas linguísticas do texto acima, julgue o item .\n\nOs trechos “a tendência à escrita a textos enxutos” (l.16), “um ato solitário” (l.22 e 23) e “discursos de improviso” (l.27) desempenham a mesma função sintática nas orações em que estão inseridos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":420813,"enunciado":"Os vocábulos “russos” (L.6), “velho” (L.15) e “global” (L.16) exercem uma mesma função sintática no contexto em que ocorrem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":857202,"enunciado":"No texto 1, o vocábulo \"que\" grifado em \"Viajar é apenas o tubo de oxigênio que nos permite mergulhar mais fundo na nossa estranheza e insegurança\" (3° parágrafo) exerce a mesma função morfossintática que o vocábulo grifado em:","opcoes":["Que seja.","Quê! Surpresas minhas.","É mais do que dura uma viagem lisérgica.","Tanto que, quando aterrissei em Londres [...].","Viajar é correr atrás do nosso eu ancestral, aquele rebelde que escapou da domesticação [...]."],"correta":4,"explicacao":"Gabarito: <strong>Viajar é correr atrás do nosso eu ancestral, aquele rebelde que escapou da domesticação [...].</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["analiseSintatica"]},{"id":857204,"enunciado":"Associe as colunas 1 e 2 abaixo: Coluna 1 1. Substantivo com função sintática de sujeito simples. 2. Substantivo com função sintática de objeto direto. 3. Adjetivo com função sintática de adjunto adnominal. 4. Adjetivo com função sintática de predicativo do sujeito. 5. Pronome com função sintática de objeto direto. 6. Pronome com função sintática de objeto indireto. Coluna 2 ( ) [...] o vício incurável no deslumbre. ( ) Viajar é apenas o tubo de oxigênio [...]. ( ) [...] não vê a hora do reencontro [...]. ( ) O processo é interno, sempre foi. ( ) [...] o que nos encanta, na verdade, é o confronto com o nosso outro eu [...]. ( ) Viajar é apenas o tubo de oxigênio que nos permite mergulhar mais fundo na nossa estranheza e insegurança. Assinale a alternativa que indica a sequência correta, de cima para baixo.","opcoes":["1 • 2 • 3 • 4 • 6 • 5","2 • 3 • 1 • 4 • 5 • 6","3 • 1 • 2 • 3 • 6 • 5","3 • 1 • 2 • 4 • 5 • 6","3 • 4 • 2 • 1 • 5 • 6"],"correta":3,"explicacao":"Gabarito: <strong>3 • 1 • 2 • 4 • 5 • 6</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["analiseSintatica"]},{"id":857207,"enunciado":"Assinale a alternativa correta com base no texto 2.","opcoes":["A palavra \"que\", em todas as ocorrências, exerce a mesma função sintática.","As palavras \"bom\" (1° quadrinho) e \"mãe\" (3° quadrinho) são separadas por vírgula por exercerem função sintática de vocativo.","O uso de \"a gente\" marca a variação pronominal na língua portuguesa.","A palavra \"mapa', em todas as ocorrências, exerce a função sintática de objeto direto preposicionado.","As palavras \"aqui\" e \"Estados Unidos\" (4° quadrinho), nas orações em que ocorrem, exercem função sintática de adjunto adverbial de lugar."],"correta":2,"explicacao":"Gabarito: <strong>O uso de \"a gente\" marca a variação pronominal na língua portuguesa.</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["analiseSintatica"]},{"id":872741,"enunciado":"Com relação à variação linguística bem como aos sentidos e aos aspectos linguísticos do texto 6A1AAA, julgue o próximo item.\n\n\n\n\nO vocábulo “daí” (ℓ.15) e a expressão “da ignorância” (ℓ.16) exercem a mesma função sintática no período em que ocorrem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":872790,"enunciado":"Considerando os aspectos linguísticos e os sentidos do texto 6A3BBB, julgue o item que se segue.\n\n\n\n\nNo contexto em que aparece, a oração reduzida “rompendo corporativismos e privilégios históricos” (ℓ. 28 e 29) possui sentido de finalidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":986742,"enunciado":"Acerca dos aspectos linguísticos do texto, julgue o item a seguir.\n\n\n\n\nO primeiro período do texto é composto por subordinação, sendo que a segunda e a terceira orações estabelecem relação de consequência com a oração “Seduzidos pelo charme transitório da juventude” (linha 1).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1012957,"enunciado":"No que diz  respeito ao  texto e a  seus aspectos linguísticos,  julgue o item.\n\n\n\n\nNa linha 2, a  forma verbal “surjam” está  flexionada na terceira pessoa  do plural  porque concorda com o núcleo do sujeito da oração, o termo “indivíduos”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1012961,"enunciado":"No que diz  respeito ao  texto e a  seus aspectos linguísticos,  julgue o item.\n\n\n\n\nNa  linha  29,  o  vocábulo  “nem”  introduz  oração  coordenada de sentido adversativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1055766,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item.\n\n\n\n\nO conector “que” (linha 32) introduz oração coordenada  de sentido explicativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1101164,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item.\nO  conector  “e”  (linha  11)  liga,  por  coordenação,  duas  orações  que  funcionam  como  sujeito  da  oração  “É  importante”   (linha 10).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1682792,"enunciado":"Em “Tia Tula, que achava que mormaço fazia mal, sempre gritava: ‘Vem pra dentro, menino, olha o mormaço!’“, os termos “Tia Tula” e “menino” desempenham a mesma função sintática nas orações em que ocorrem, o que justifica o fato de serem isolados por vírgulas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1682796,"enunciado":"Em “Acontece que eu, acostumado a conversar com a gente das Minas Gerais, falei em ‘varreção’ — do verbo ‘varrer’”, o sujeito da oração iniciada com “Acontece” é indeterminado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1865411,"enunciado":"A expressão “um doente poeta que resistiu a tudo” (linhas 18 e 19) exerce a função sintática de sujeito da forma verbal “Houve” (linha 18).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1909167,"enunciado":"Acerca das estruturas linguísticas do texto CG2A1-I, julgue o item a seguir.\nNo trecho “crimes que visam o ataque a computadores” (último parágrafo do texto), o termo “que” remete semanticamente ao nome “crimes”, que o antecede, e funciona como sujeito da oração “que visam o ataque a computadores”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1913150,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nA oração que segue o termo “consenso” (linha 1) classifica-se como subordinada adjetiva restritiva, por isso não está separada por vírgula.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1913151,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nNa linha 3, o sujeito da oração “é importante” é “o pecuarista”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1976613,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto apresentado, julgue o item. \n\nNo trecho “que algo está errado e que precisamos prestar atenção em nossas atitudes, relações, padrões” (linhas 23 e 24), as duas orações introduzidas pelo termo “que” exercem a mesma função sintática no último período do antepenúltimo parágrafo do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1976623,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto apresentado, julgue o item. \n\nA oração “que o despertador receba esse nome” (linha 1) exerce a função de sujeito no primeiro período do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1982022,"enunciado":"Em relação aos sentidos e aos aspectos linguísticos do texto apresentado, julgue o item.\n\nNa linha 12, o segmento “levar mensagens entre as cidades” exerce a função de sujeito de “era”, o que justifica a flexão desta forma verbal no singular.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1996105,"enunciado":"Com relação aos aspectos linguísticos do texto, julgue o item a seguir: \n\n\n\n\nNa linha 26, “dos corpos negros” exerce a função sintática de complemento nominal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":1996107,"enunciado":"Com relação aos aspectos linguísticos do texto, julgue o item a seguir: \n\n\n\n\nO termo “como cidadão de segunda classe” (linha 39) apresenta função sintática de predicativo do objeto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2077723,"enunciado":"Considerando o texto e suas estruturas gramaticais, julgue o item.\n\nO termo “prestar serviço à população” (linhas 11 e 12) desempenha função de oração subordinada subjetiva para o predicado “deve ser sempre a meta dos servidores” (linhas 12 e 13).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2134698,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. \n\n\n\n\nO sujeito da oração “Esperamos que sim” (linha 2) é indeterminado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2134703,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. \n\n\n\n\nA oração “O mais provável é que a felicidade e a infelicidade estejam relacionadas a mecanismos cerebrais mais complexos do que se imagina” (linhas de 22 a 24) é classificada como subordinada substantiva predicativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2134707,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. \n\n\n\n\nA oração “E que o cérebro possui uma malha de circuitos, a chamada rede de modo padrão” (linhas 27 e 28) é classificada como subordinada substantiva objetiva direta.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2183465,"enunciado":"Considerando a estrutura e os aspectos linguísticos do texto, julgue o item.\n\n\n\n\nO termo “daquele jardim” (linha 1) desempenha a função sintática de adjunto adverbial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2183476,"enunciado":"Acerca da estrutura e dos sentidos do texto, julgue o item.\n\n\n\n\nA oração “quando passou um gordo vigário a cavalo” (linha 4) classifica-se como subordinada adverbial temporal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2205202,"enunciado":"Com base na estrutura e no conteúdo do texto, julgue o item.\n\n\n\n\nA expressão “Prêmio Raízes” (linha 4) deve ser classificada sintaticamente como objeto direto de um verbo anterior.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2205214,"enunciado":"Acerca da estrutura do texto, julgue o item.\n\n\n\n\nA locução “de edifícios ou de outras estruturas” (linha 2) funciona como complemento nominal do núcleo ao qual se liga.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2205217,"enunciado":"Acerca da estrutura do texto, julgue o item.\n\n\n\n\nA expressão “os diversos tipos de atividades humanas” (linhas 6 e 7) desempenha função de objeto direto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2286811,"enunciado":"Em relação ao texto e a seus aspectos linguísticos e semânticos, julgue o item.\n\n\n\n\nNa oração “Mas nós entendemos que aquilo que seria comum seja entendido como normal” (linhas de 36 e 37), o conectivo “que” introduz uma oração subordinada substantiva subjetiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2320401,"enunciado":"Com base na leitura do texto e em seus aspectos linguísticos, de forma e de conteúdo, julgue o item a seguir.\n\nA oração “que estiverem em dia com suas anuidades ou honrando parcelamento das mesmas” (linhas 28 e 29) deve ser classificada como subordinada substantiva objetiva direta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2320402,"enunciado":"Com base na leitura do texto e em seus aspectos linguísticos, de forma e de conteúdo, julgue o item a seguir.\n\nAs expressões “Após aprovação” (linha 24) e “De tempos em tempos” (linha 30) são exemplos de termos que assumem, no texto, a função sintática de adjunto adverbial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2345625,"enunciado":"Considerando o texto e os seus aspectos linguísticos, estruturais e de conteúdo, julgue o item.\n\n\n\n\n\n\n\nO termo “um trabalho pela regulamentação profissional da categoria” (linha 2 e 3) é uma oração subordinada substantiva objetiva direta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2345635,"enunciado":"Com base na leitura do texto, julgue o item.\n\n\n\n\n\n\n\nO termo “da equipe” (linha 6) funciona como complemento nominal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2345636,"enunciado":"Com base na leitura do texto, julgue o item.\n\n\n\n\n\n\n\nA oração “para que as empresas possam corrigir todas as questões” (linhas 16 e 17) deve ser classificada como subordinada adverbial final.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2360378,"enunciado":"Acerca da tipologia, dos sentidos do texto e dos aspectos linguísticos, julgue o item.\n\n\n\n\nO segundo período do terceiro parágrafo inicia‑se pela oração principal, seguida pela oração coordenada “com aulas práticas e laboratoriais” e finaliza com a oração subordinada “além da aplicação clínica supervisionada em pacientes reais”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2441388,"enunciado":"Em relação a aspectos gerais do texto, julgue o item.\n\n\n\n\nO termo “pra cá” (linha 12) exerce a função sintática de objeto indireto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2441397,"enunciado":"Em relação ao texto, julgue o item.\n\n\n\n\nNo primeiro parágrafo do texto, a oração “na medida em que possuem atuação sólida” é adverbial e tem sentido de proporção.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2463794,"enunciado":"Em relação a aspectos estruturais do texto, julgue o item.\n\n\n\n\nA oração “antes de afundar no oceano” (linhas 5 e 6) é subordinada adverbial temporal reduzida de infinitivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2463799,"enunciado":"Em relação a aspectos estruturais do texto, julgue o item.\n\n\n\n\nNa oração “Isso é terrível” (linha 23), há predicado nominal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2463800,"enunciado":"Em relação a aspectos estruturais do texto, julgue o item.\n\n\n\n\nO vocábulo “que” (linha 23) é uma conjunção integrante, que encabeça uma oração subordinada substantiva subjetiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2467741,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item.\n\n\n\n\nNo segundo parágrafo, a oração “quando encontrou nas pesquisas de busca do Google a notícia do processo seletivo” é uma subordinada adverbial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2467742,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item.\n\n\n\n\nO pronome “que” (linha 29) apresenta função sintática de objeto direto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2467743,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item.\n\n\n\n\nNo quarto parágrafo, a oração “que aproveitou 100% do evento” classifica‑se como substantiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2469093,"enunciado":"Com relação a aspectos gerais do texto, julgue o item.\n\n\n\n\nNo verso “De santos fui artéria vigorosa” (linha 8), o termo “de santos” funciona como complemento nominal de “vigorosa”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2469094,"enunciado":"Com relação a aspectos gerais do texto, julgue o item.\n\n\n\n\nNo subtítulo, a construção “para evitar aqueles que coçam” é uma oração subordinada adverbial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2500662,"enunciado":"Acerca dos aspectos gerais do texto, julgue o item.\n\n\nNo trecho “Uma denúncia foi feita ao Conselho Regional de Fisioterapia e Terapia Ocupacional (CREFITO‑RJ) por uma mãe de uma criança de seis anos com espectro autista que vinha sendo atendida nessa clínica” (linhas de 7 a 10), o termo que se inicia com “ao” funciona sintaticamente como agente da passiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2500668,"enunciado":"Em relação ao anúncio, julgue o item. \n\n\nNo texto de fonte maior, o termo “em terapia ocupacional em contextos hospitalares” exerce a função sintática de complemento nominal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2501247,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item.\n\n\n\n\nA expressão “de que” (linha 7) introduz uma oração subordinada adjetiva que tem função de objeto direto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2519999,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item a seguir.\n\n\n\n\nNo subtítulo do texto, o termo “por projetos sustentáveis” funciona sintaticamente como complemento nominal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":2520007,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item a seguir.\n\n\n\n\nNo último parágrafo, a oração “que a Viveza ainda conta com uma equipe de vendas, gestores e projetistas” classifica‑se como substantiva objetiva direta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3028206,"enunciado":"Assinale a alternativa que indica a relação existente entre as orações subordinadas adverbiais “Ela prestou socorro, conforme manda a lei”.","opcoes":["Causa.","Condição.","Finalidade.","Conformidade.","Consequência."],"correta":3,"explicacao":"Gabarito: <strong>Conformidade.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["analiseSintatica"]},{"id":3031816,"enunciado":"A respeito do texto, julgue o item seguinte. \nNa linha 32, o termo “pela Opaq” é o complemento nominal de “asfixiante”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3122278,"enunciado":"Com base no texto, julgue o item a seguir. \n\n\n\n\nNa linha 4, a oração “em que eu era administrador” classifica‑se como subordinada adjetiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3185038,"enunciado":"Com base na estrutura linguística e no vocabulário empregados no texto, julgue o item seguinte.\n\nNa linha 7, a oração iniciada por “que” funciona como objeto direto da forma verbal “revela”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3198372,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nA oração “que fazia trabalho extramuros” (linha 13) classifica‑se como subordinada adjetiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3198386,"enunciado":"Com base no texto, julgue o item seguinte.\n\n\n\n\nNa linha 33, o trecho “para não ser cobrada pelo serviço” é uma oração subordinada adverbial causal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3274414,"enunciado":"No que se refere a aspectos linguísticos do texto, julgue o item seguinte.\n\n\n\n\nA substituição do vocábulo “que” (linha 16) por as quais estaria de acordo com as regras gramaticais de coesão textual, dada a função sintática que o referido termo exerce no período.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3274415,"enunciado":"No que se refere a aspectos linguísticos do texto, julgue o item seguinte.\n\n\n\n\nO sujeito da oração expressa pela forma verbal “tendo sido reconhecido” (linha 19) é “patrimônio cultural do Brasil” (linha 20).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3448584,"enunciado":"No trecho “Esse uso está tão sedimentado que aparece até em recados de restaurante” (4º parágrafo), a palavra “que” é um pronome relativo e a oração por ele introduzida é classificada como oração adjetiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3505347,"enunciado":"Com base no texto, julgue o item a seguir.\n\n\n\n\nNo trecho “A informação foi confirmada, nesta terça‑feira (13), pela defesa de Daniele.”, o termo “pela defesa de Daniele” funciona, sintaticamente, como agente da passiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3505359,"enunciado":"Quanto a aspectos gerais do texto, julgue o item seguinte.\n\n\n\n\nNo trecho “Ele foi socorrido por pessoas que estavam próximas ao local do acidente e levado ao hospital, mas não resistiu e faleceu na manhã deste domingo.”, a oração “mas não resistiu”, introduzida por uma conjunção subordinativa, classifica‑se como adverbial concessiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3610460,"enunciado":"Quanto à estruturação linguística e gramatical do texto, julgue o item seguinte.\n\n\n\n\nNos trechos “os consensos para a prática de exercícios preventivos ou terapêuticos recomendam atividades” e “os consensos preconizam, além dessas atividades, a inclusão de exercícios”, as formas verbais “recomendam” e “preconizam” têm a mesma função sintática e semântica na oração em que se encontram.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3638067,"enunciado":"Considerando as características textuais e gramaticais presentes no texto, julgue o item seguinte.\n\n\n\n\nOs termos preposicionados “de conforto” em “promoção de conforto”, “de materiais” em “ o emprego de materiais” e “de pessoas em situação de rua” em “o afastamento de pessoas em situação de rua” desempenham a mesma função sintática.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3683392,"enunciado":"Com base no texto e nos seus aspectos linguísticos, julgue o item seguinte.\n\n\n\n\nNo trecho “Não diga que a canção está perdida”, a segunda oração é classificada como subordinada substantiva completiva nominal, ao completar o sentido da primeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3759675,"enunciado":"Com base nos aspectos gerais do texto, julgue o item a seguir.\n\n\n\n\nNa sequência “Dez anos após estava livre, pobre, endividada e dez anos mais velha”, os termos “livre” e “pobre” desempenham função sintática distinta do termo “endividada”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3759676,"enunciado":"Com base nos aspectos gerais do texto, julgue o item a seguir.\n\n\n\n\nOs termos “servidor público” e “pai dedicado”, no trecho “o ex‑marido ainda era servidor público e pai dedicado”, apresentam a função de sujeito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3937022,"enunciado":"Com base nas ideias e nos aspectos gramaticais do texto, julgue o item a seguir.\n\n\n\n\nNo trecho “a leitura, por si só, não basta”, as vírgulas são corretamente empregadas para isolar expressão explicativa intercalada, sem comprometer a estrutura sintática da oração principal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":3951978,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir.\n\n\n\n\nNo trecho “Trazer essa temática à tona é de grande importância”, o termo “de grande importância” exerce a função de complemento nominal do verbo “ser”, motivo pelo qual a substituição do adjetivo “grande” por grandiosa manteria a correção gramatical e a função sintática original.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4019370,"enunciado":"Considerando os sentidos do texto, a sua tipologia e os seus mecanismos de construção de significado, julgue o item a seguir.\n\n\n\n\nEm “impõe‑se a intimação do interessado”, o termo “a intimação do interessado” exerce função de sujeito posposto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4019377,"enunciado":"Julgue o item seguinte, em relação às funções sintáticas dos termos da oração e à classificação de orações subordinadas.\n\n\n\n\nNo trecho “cuja inobservância pode acarretar prejuízos institucionais”, o termo “institucionais” funciona como predicativo do objeto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]},{"id":4019379,"enunciado":"Julgue o item seguinte, em relação às funções sintáticas dos termos da oração e à classificação de orações subordinadas.\n\n\n\n\nNo trecho “impõe‑se a intimação”, a partícula “se” é índice de indeterminação do sujeito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["analiseSintatica"]}];
